(1, '1-800-123-4567', '1-800-123-6789', 'info@car_agency1.com', 'company_logo_1.png', '<iframe width="100%" height="400" frameborder="0" scrolling="no" marginheight="0" marginwidth="0" src="http://maps.google.com/maps?f=q&source=s_q&hl=en&geocode=&q=Hotel+Circle+South,+San+Diego,+California,+United+States&aq=1&sll=33.981232,-84.173813&sspn=0.12868,0.307274&ie=UTF8&hq=&hnear=Hotel+Cir+S,+San+Diego,+California&ll=32.759,-117.177036&spn=0.017215,0.038409&z=14&output=embed"></iframe>', 0, 1),
(2, '1-800-123-2222', '1-800-123-2223', 'info@car_agency2.com', 'company_logo_2.png', '<iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d2948.0965968856144!2d-71.0666208!3d42.361780599999996!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x89e3709a3c7713c5%3A0x922cf2c02c6d4e5a!2s5+Blossom+St%2C+Charles+River+Plaza+Shopping+Center%2C+Boston%2C+MA+02114!5e0!3m2!1sen!2s!4v1405938488556" width="100%" height="450" frameborder="0" style="border:0"></iframe>', 0, 1);
INSERT INTO `uhb289_car_agencies_description` (`id`, `agency_id`, `language_id`, `name`, `address`, `description`, `terms_and_conditions`) VALUES
(1, 1, 'en', 'Transportation Agency 1', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(2, 1, 'es', 'Transportation Agency 1', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(3, 1, 'de', 'Transportation Agency 1', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(4, 2, 'en', 'Transportation Agency 2', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(5, 2, 'es', 'Transportation Agency 2', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(6, 2, 'de', 'Transportation Agency 2', 'address here...', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '<h3>Excess Protection - Excellent Value, Best Cover, Peace of Mind</h3><p>When you pick up your car a deposit is usually held on your card for your excess which may be charged if the vehicle is damaged. Take our Damage Excess Refund and if you have any bumps or scrapes we''ll refund any deductions from your excess.<br /><br /></p><div class="hpadding20"><ul class="checklist"><li><span class="bold green">You''re protected</span> - Damage Excess Refund protects you when things go wrong and you are required to pay out from your excess</li><li><span class="bold green">Accidents covered</span> - Your excess will be protected if your vehicle is damaged in an accident</li><li><span class="bold green">Damage cover</span> - Damage to bodywork, vehicle parts and accessories incurred during most driving incidents is covered.</li></ul></div>'),
(7, 1, 'ar', 'Transportation Agency 1', '', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', ''),
(8, 2, 'ar', 'Transportation Agency 2', '', '<h3>We give you the following for free</h3><div class="col-md-6"><ul class="checklist"><li>Amendments</li><li>Theft Protection</li><li>Direct-dial phone</li><li>Collision Damage Waiver</li></ul></div><div class="col-md-6"><ul class="checklist"><li>Unlimited Kilometres for ALL car groups</li><li>Local Taxes</li><li>PRoad Fee</li><li>First Additional Driver</li></ul></div>', '');
