INSERT INTO `uhb289_conference_types_translations` (`id`, `conference_type_id`, `language_id`, `name`, `short_description`, `full_description`) VALUES
(1, 1, 'en', 'Advanced Cardiac Life Support', '<p><span style="color: #404040; font-family: Arial, Helvetica, sans-serif; font-size: 13px;">Due to the inherent knowledge, skills, practice locations, and populations of patients served by practitioners of anesthesiology, emergency and critical care medicine, the physicians, nurses, and other advanced care providers are summoned to interpret the EKG reading and often treat the underlying dysrhythmias. This program is designed to update these practitioners with the latest information on this body of scientific information. This course offers 8 contact hours.</span></p>', '<p><span style="color: #404040; font-family: Arial, Helvetica, sans-serif; font-size: 13px;">Due to the inherent knowledge, skills, practice locations, and populations of patients served by practitioners of anesthesiology, emergency and critical care medicine, the physicians, nurses, and other advanced care providers are summoned to interpret the EKG reading and often treat the underlying dysrhythmias. This program is designed to update these practitioners with the latest information on this body of scientific information. This course offers 8 contact hours.</span></p>'),
