INSERT INTO `uhb289_email_templates` (`id`, `language_id`, `template_code`, `template_name`, `template_subject`, `template_content`, `is_system_template`) VALUES
(1, 'en', 'new_account_created', 'Email for new customer', 'Your account has been created', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYou login: {USER NAME}\r\nYou password: {USER PASSWORD}\r\n\r\nYou may follow the link below to log into your account:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(2, 'es', 'new_account_created', 'Email para el nuevo cliente', 'Tu cuenta ha sido creada', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nFelicitaciones por la creación de su nueva cuenta.\r\n\r\nPor favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar, si surge algún problema u olvidas tu contraseña.\r\n\r\nUsted entrada: {USER NAME}\r\nUsted contraseña: {USER PASSWORD}\r\n\r\nUsted puede seguir el siguiente enlace para acceder a su cuenta: <a href="{BASE URL}index.php?customer=login">Acceso Clientes</a>\r\n\r\nPD Recuerde, nosotros nunca venderemos su nombre o dirección de correo electrónico.\r\n\r\nDisfrute!\r\n-\r\nSinceramente,\r\nSoporte al cliente', 1),
(3, 'de', 'new_account_created', 'E-Mail für neuen Kunden', 'Ihr Konto wurde erstellt', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nHerzlichen Glückwunsch zu Ihrem neuen Konto erstellen.\r\n\r\nBitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen, sollten Sie Probleme auftreten oder Ihr Passwort vergessen enthält.\r\n\r\nSie Login: {USER NAME}\r\nIhr Passwort: {USER PASSWORD}\r\n\r\nSie können den folgenden Link in Ihren Account einloggen:\r\n<a href="{BASE URL}index.php?customer=login">Kunden-Login</a>\r\n\r\nP.S. Denken Sie daran, wir werden nie verkaufen Ihren Namen oder E-Mail-Adresse.\r\n\r\nViel Spaß!\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(4, 'en', 'new_account_created_confirm_by_admin', 'Email for new user (admin approval required)', 'Your account has been created (approval required)', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYour login: {USER NAME}\r\nYour password: {USER PASSWORD}\r\n\r\nAfter your registration will be approved by administrator,  you could log into your account with a following link:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(5, 'es', 'new_account_created_confirm_by_admin', 'E-mail para el nuevo usuario (requiere aprobación del administrador)', 'Su cuenta ha sido creada (requiere aprobación)', 'Estimados <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nFelicitaciones por la creación de su nueva cuenta.\r\n\r\nPor favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar, si surge algún problema u olvidas tu contraseña.\r\n\r\nSu entrada: {USER NAME}\r\nSu contraseña: {USER PASSWORD}\r\n\r\nDespués de su registro será aprobado por el administrador, puede acceder a su cuenta con el siguiente enlace: <a href="\r\n{BASE URL}index.php?customer=login">Acceso Clientes</a>\r\n\r\nPD Recuerde, nosotros nunca venderemos su nombre o dirección de correo electrónico.\r\n\r\nDisfrute!\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(6, 'de', 'new_account_created_confirm_by_admin', 'E-Mail für neue Benutzer (admin Genehmigung erforderlich)', 'Ihr Konto wurde erstellt (Bestätigung erforderlich)', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nHerzlichen Glückwunsch zu Ihrem neuen Konto erstellen.\r\n\r\nBitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen, sollten Sie Probleme auftreten oder Ihr Passwort vergessen enthält.\r\n\r\nIhre Login: {USER NAME}\r\nIhr Passwort: {USER PASSWORD}\r\n\r\nNach Ihrer Anmeldung vom Administrator genehmigt werden, könnten Sie sich in Ihrem Konto mit folgendem Link anmelden:\r\n<a href="{BASE URL}index.php?customer=login">Kunden-Login</a>\r\n\r\nP.S. Denken Sie daran, wir werden nie verkaufen Ihren Namen oder E-Mail-Adresse.\r\n\r\nViel Spaß!\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(7, 'en', 'new_account_created_confirm_by_email', 'Email for new user (email confirmation required)', 'Your account has been created (confirmation required)', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYour login: {USER NAME}\r\nYour password: {USER PASSWORD}\r\n\r\nIn order to become authorized member, you will need to confirm your registration. You may follow the link below to access the confirmation page:\r\n<a href="{BASE URL}index.php?customer=confirm_registration&c={REGISTRATION CODE}">Confirm Registration</a>\r\n\r\nP.S. Remember, we will never sell your personal information or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(8, 'es', 'new_account_created_confirm_by_email', 'Correo electrónico para el nuevo usuario (se requiere confirmación)', 'Su cuenta ha sido creada (requiere confirmación por e-mail)', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nFelicitaciones por la creación de su nueva cuenta.\r\n\r\nPor favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar, si surge algún problema u olvidas tu contraseña.\r\n\r\nUsted entrada: {USER NAME}\r\nUsted contraseña: {USER PASSWORD}\r\n\r\nPara convertirse en miembro autorizado, tendrá que confirmar su registro. Por favor siga el siguiente enlace para acceder a la página de confirmación: <a href="\r\n{BASE URL}index.php?customer=confirm_registration&c={REGISTRATION CODE}">Confirmar registro</a>\r\n\r\nPD Recuerde, nosotros nunca venderemos su nombre o dirección de correo electrónico.\r\n\r\nDisfrute!\r\n-\r\nSinceramente,\r\nSoporte al cliente', 1),
(9, 'de', 'new_account_created_confirm_by_email', 'E-Mail für neue Benutzer (E-Mail eine Bestätigung erforderlich)', 'Ihr Konto wurde erstellt (Bestätigung erforderlich)', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nHerzlichen Glückwunsch zu Ihrem neuen Konto erstellen.\r\n\r\nBitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen, sollten Sie Probleme auftreten oder Ihr Passwort vergessen enthält.\r\n\r\nIhre Login: {USER NAME}\r\nIhr Passwort: {USER PASSWORD}\r\n\r\nUm Mitglied zu werden ermächtigt, müssen Sie Ihre Registrierung bestätigen. Sie können folgen Sie den untenstehenden Link, um die Bestätigungs-Seite zu erreichen: <a href="{BASE URL}index.php?customer=confirm_registration&c={REGISTRATION CODE}">Bestätigung der Registrierung</a>\r\n\r\nP.S. Denken Sie daran, wir werden nie verkaufen Ihre persönlichen Informationen oder E-Mail-Adresse.\r\n\r\nViel Spaß!\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(10, 'en', 'new_account_created_by_admin', 'Email for new user (account created by admin)', 'Your account has been created by admin', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nOur administrator just created a new account for you.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYou login: {USER NAME}\r\nYou password: {USER PASSWORD}\r\n\r\nYou may follow the link below to log into your account:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(11, 'es', 'new_account_created_by_admin', 'Correo electrónico para el nuevo usuario (cuenta creada por el admin)', 'Su cuenta ha sido creada por admin', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nNuestro administrador acaba de crear una cuenta nueva para usted.\r\n\r\nPor favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar, si surge algún problema u olvidas tu contraseña.\r\n\r\nUsted entrada: {USER NAME}\r\nUsted contraseña: {USER PASSWORD}\r\n\r\nUsted puede seguir el siguiente enlace para acceder a su cuenta: <a href="{BASE URL}index.php?customer=login">Acceso Clientes</a>\r\n\r\nPD Recuerde, nosotros nunca venderemos su nombre o dirección de correo electrónico.\r\n\r\nDisfrute!\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(12, 'de', 'new_account_created_by_admin', 'E-Mail für neue Benutzer (Account erstellt von admin)', 'Ihr Konto wurde von admin erstellt', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nUnser Administrator gerade erstellt ein neues Konto für Sie.\r\n\r\nBitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen, sollten Sie Probleme auftreten oder Ihr Passwort vergessen enthält.\r\n\r\nSie Login: {USER NAME}\r\nIhr Passwort: {USER PASSWORD}\r\n\r\nSie können den folgenden Link in Ihren Account einloggen: <a href="{BASE URL}index.php?customer=login">Kunden-Login</a>\r\n\r\nP.S. Denken Sie daran, wir werden nie verkaufen Ihren Namen oder E-Mail-Adresse.\r\n\r\nViel Spaß!\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(13, 'de', 'new_account_created_notify_admin', 'Neues Konto erstellt wurde (benachrichtigen admin)', 'Neues Konto erstellt wurde', 'Hallo Admin!\r\n\r\nEin neuer Benutzer hat bei Ihnen vor Ort registriert worden.\r\nDiese Email enthält einen Benutzer-Account Details:\r\n\r\nName: {FIRST NAME} {LAST NAME}\r\nE-Mail: {USER EMAIL}\r\nBenutzername: {USER NAME}\r\n\r\nP.S. Bitte überprüfen Sie, ob es nicht erforderlich, Ihre Zustimmung zur Aktivierung.', 1),
(14, 'en', 'new_account_created_notify_admin', 'New account has been created (notify admin)', 'New account has been created', 'Hello Admin!\r\n\r\nA new user has been registered at your site.\r\nThis email contains a user account details:\r\n\r\nName: {FIRST NAME} {LAST NAME}\r\nEmail: {USER EMAIL}\r\nUsername: {USER NAME}\r\n\r\nP.S. Please check if it doesn''t require your approval for activation', 1),
(15, 'es', 'new_account_created_notify_admin', 'Nueva cuenta se ha creado (notificar admin)', 'Nueva cuenta se ha creado', 'Hola admin!\r\n\r\nUn nuevo usuario ha sido registrado en su sitio.\r\nEste correo electrónico contiene una información de la cuenta de usuario:\r\n\r\nNombre: {FIRST NAME} {LAST NAME}\r\nE-mail: {USER EMAIL}\r\nNombre de usuario: {USER NAME}\r\n\r\nPD Por favor, compruebe si no se requiere su aprobación para la activación.', 1),
(16, 'en', 'password_forgotten', 'Email for customer or admin forgotten password', 'Forgotten Password', 'Hello <b>{USER NAME}</b>!\r\n\r\nYou or someone else asked for your login info on our site:\r\n{WEB SITE}\r\n\r\nYour Login Info:\r\n\r\nUsername: {USER NAME}\r\nPassword: {USER PASSWORD}\r\n\r\n\r\nBest regards,\r\n{WEB SITE}', 1),
(17, 'es', 'password_forgotten', 'Email para el cliente o administrador contraseña olvidada', 'He olvidado la contraseña', 'Hola <b>{USER NAME}</b>!\r\n\r\nUsted o alguien más pide su información de acceso en nuestro sitio:\r\n{WEB SITE}\r\n\r\nSu usuario Info:\r\n\r\nNombre de usuario: {USER NAME}\r\nContraseña: {USER PASSWORD}\r\n\r\n\r\nSaludos cordiales,\r\n{WEB SITE}', 1),
(18, 'de', 'password_forgotten', 'E-Mail-Client oder für admin vergessenes Passwort', 'Passwort vergessen?', 'Hallo <b>{USER NAME}</b>!\r\n\r\nSie oder jemand anderes baten um Ihre Login-Informationen auf unserer Website:\r\n{WEB SITE}\r\n\r\nIhre Login-Infos:\r\n\r\nBenutzername: {USER NAME}\r\nPasswort: {USER PASSWORD}\r\n\r\n\r\nMit freundlichen Grüßen,\r\n{WEB SITE}\r\n', 1),
(19, 'en', 'password_changed_by_admin', 'Password changed by admin', 'Your password has been changed', 'Hello <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour password was changed by administrator of the site:\r\n{WEB SITE}\r\n\r\nHere your new login info:\r\n-\r\nUsername: {USER NAME} \r\nPassword: {USER PASSWORD}\r\n\r\n-\r\nBest regards,\r\nAdministration', 1),
(20, 'es', 'password_changed_by_admin', 'Contraseña cambiada por admin', 'Su contraseña ha sido cambiada', 'Hola <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nSu contraseña se ha cambiado por el administrador del sitio:\r\n{WEB SITE}\r\n\r\nAquí la información de su nuevo inicio de sesión:\r\n-\r\nNombre de usuario: {USER NAME} \r\nContraseña: {USER PASSWORD}\r\n\r\n-\r\nSaludos cordiales,\r\nAdministración', 1),
(21, 'de', 'password_changed_by_admin', 'Kennwort von admin geändert', 'Ihr Passwort wurde geändert', 'Hallo <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nIhr Passwort wurde durch den Administrator der Website geändert:\r\n{WEB SITE}\r\n\r\nHier werden Ihre neuen Login-Info:\r\n-\r\nBenutzername: {USER NAME} \r\nKennwort: {USER PASSWORD}\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nVerwaltung', 1),
(22, 'en', 'registration_approved_by_admin', 'Email for new customer (registration was approved by admin)', 'Your registration has been approved', 'Dear <b>{FIRST NAME} {LAST NAME}!</b>\r\n\r\nCongratulations! This e-mail is to confirm that your registration at {WEB SITE} has been approved.\r\n\r\nYou can now login in to your account now.\r\n\r\nThank you for choosing {WEB SITE}.\r\n-\r\nSincerely,\r\nAdministration', 1),
(23, 'es', 'registration_approved_by_admin', 'E-mail para clientes nuevos (el registro fue aprobado por el administrador)', 'Su registro ha sido aprobado', 'Estimado <b>{FIRST NAME} {LAST NAME}!</b>\r\n\r\n¡Felicitaciones! Este e-mail es para confirmar que su inscripción en {WEB SITE} ha sido aprobado.\r\n\r\nAhora puede acceder a su cuenta ahora.\r\n\r\nGracias por elegir {WEB SITE}.\r\n-\r\nAtentamente,\r\nadministración', 1),
(24, 'de', 'registration_approved_by_admin', 'E-Mail für neue Kunden (Registrierung wurde von admin zugelassen)', 'Ihre Registrierung genehmigt wurde', 'Sehr geehrte <b>{FIRST NAME} {LAST NAME}!</b>\r\n\r\nHerzlichen Glückwunsch! Diese E-Mail ist zu bestätigen, dass Ihre Anmeldung bei {WEB SITE} genehmigt wurde.\r\n\r\nSie können jetzt in Ihr Konto jetzt einloggen.\r\n\r\nDanke für die Wahl {WEB SITE}.\r\n-\r\nMit freundlichen Grüßen,\r\nVerwaltung', 1),
(25, 'en', 'account_deleted_by_user', 'Account removed email (by customer)', 'Your account has been removed', 'Dear {USER NAME}!\r\n\r\nYour account was removed.\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(26, 'es', 'account_deleted_by_user', 'Cuenta Eliminada Email (por el cliente)', 'Su cuenta ha sido fue eliminado', 'Estimado {USER NAME}!\r\n\r\nTu cuenta ha sido eliminada.\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(27, 'de', 'account_deleted_by_user', 'Konto entfernt E-Mail (vom Client)', 'Ihr Konto wurde entfernt', 'Sehr geehrte {USER NAME}!\r\n\r\nIhr Konto wurde entfernt.\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(28, 'es', 'new_account_created_without', 'Correo electrónico para el nuevo cliente/devuelto (sin cuenta)', 'Su información de contacto ha sido aceptada', 'Querido <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nGracias por enviarnos su información de contacto. Ahora puede completar su reserva - sólo tienes que seguir las instrucciones que aparecen en la página de pago.\r\n\r\nPor favor, recuerde que aún no tiene cuenta en nuestro sitio, siempre se puede crear con facilidad. Para ello basta con seguir este enlace e introducir toda la información necesaria para crear una cuenta nueva: <a href="{BASE URL}index.php?client=create_account">Crear una cuenta</a>\r\n\r\nPD Recuerde, nosotros nunca venderemos su nombre o dirección de correo electrónico.\r\n\r\nDisfrutar!\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(29, 'de', 'new_account_created_without', 'E-Mail für neue/kehrte Kunden (ohne Rechnung)', 'Ihre Kontaktinformationen angenommen wurde', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nVielen Dank für die Zusendung Ihrer Kontaktdaten. Sie können nun vervollständigen Sie Ihre Buchung - folgen Sie einfach den Anweisungen auf der Checkout-Seite.\r\n\r\nBitte denken Sie daran, dass auch Sie nicht über Konto auf unserer Website, können Sie immer schaffen es mit leicht. Um dies zu tun folgen Sie einfach diesem Link und geben Sie alle benötigten Informationen auf neue Rechnung erstellen: <a href="{BASE URL}index.php?customer=create_account">Konto erstellen</a>\r\n\r\nP.S. Denken Sie daran, wir werden nie verkaufen Ihren Namen oder E-Mail-Adresse.\r\n\r\nGenießen!\r\n-\r\nMit freundlichen Grüßen,\r\nCustomer Support', 1),
(30, 'en', 'new_account_created_without', 'Email for new/returned customer (without account)', 'Your contact information has been accepted', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for sending us your contact information. You may now complete your booking - just follow the instructions on the checkout page.\r\n\r\nPlease remember that even you don''t have account on our site, you may always create it with easily. To do it simply follow this link and enter all needed information to create a new account: <a href="{BASE URL}index.php?customer=create_account">Create Account</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(31, 'en', 'order_placed_online', 'Email for online placed orders (not paid yet)', 'Your order has been placed in our system!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for reservation request!\r\n\r\nYour order {BOOKING NUMBER} has been placed in our system and will be processed shortly.\r\n{STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\nP.S. Please keep this email for your records, as it contains an important information that you may\r\nneed.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(32, 'es', 'order_placed_online', 'Email para pedidos en línea (aún sin pagar)', 'Su pedido ha sido realizado en nuestro sistema!', 'Estimado <b>{LAST NAME} {FIRST NAME}</b>!\r\n\r\nGracias por solicitud de reserva!\r\n\r\nSu {BOOKING NUMBER} pedido ha sido realizado en nuestro sistema y se procesará en breve.\r\n{STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\nPD Por favor, mantenga este e-mail para sus registros, ya que contiene una información importante que puede\r\nnecesitan.\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente\r\n\r\n{HOTEL INFO}', 1),
(33, 'de', 'order_placed_online', 'E-Mail für Bestellungen online gestellt (noch nicht bezahlt)', 'Ihre Bestellung wurde in unserem System gelegt!', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nVielen Dank für Reservierungs-Anfrage!\r\n\r\nIhre Bestellung {BOOKING NUMBER} hat in unserem System platziert und wird in Kürze bearbeitet werden.\r\n{STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\nP.S. Bitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information enthält, dass Sie möglicherweise\r\nbenötigen.\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support\r\n\r\n{HOTEL INFO}', 1),
(34, 'en', 'order_paid', 'Email for orders paid via payment processing systems', 'Your order {BOOKING NUMBER} has been paid and received by the system!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for reservation!\r\n\r\nYour order {BOOKING NUMBER} has been completed!\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\n{BILLING INFORMATION}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Please keep this email for your records, as it contains an important information that you may need.\r\nP.P.S You may always check your booking status here:\r\n<a href="{BASE URL}index.php?page=check_status">Check Status</a>\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(35, 'es', 'order_paid', 'Email para los pedidos pagados a través de sistemas de procesamiento de pagos', 'Su pedido {BOOKING NUMBER} ha sido pagado y recibido por el sistema!', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nGracias por su reservación!\r\n\r\nSu {BOOKING NUMBER} fin se ha terminado!\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\n{BILLING INFORMATION}\r\n\r\n{REFUND INFORMATION}\r\n\r\nPD Por favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar.\r\nPPD Usted siempre puede revisar su estado de su reserva aquí: <a href="{BASE URL}index.php?page=check_status">Comprobar el estado de</a>\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente\r\n\r\n{HOTEL INFO}', 1),
(36, 'de', 'order_paid', 'E-Mail für Bestellungen via Zahlungsabwicklung Systeme bezahlt', 'Ihre Bestellung {BOOKING NUMBER} wurde bezahlt und erhalten vom System!', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nVielen Dank für die Reservierung!\r\n\r\nIhre Bestellung {BOOKING NUMBER} ist abgeschlossen!\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\n{BILLING INFORMATION}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Bitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen enthält.\r\nP.P.S. Sie können jederzeit überprüfen Sie Ihre Buchung Status hier: <a href="{BASE URL}index.php?page=check_status">Status überprüfen</a>\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support\r\n\r\n{HOTEL INFO}', 1),
(37, 'en', 'events_new_registration', 'Events - new member has registered (member copy)', 'You have been successfully registered to the event!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on registering to {EVENT}.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need.\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(38, 'es', 'events_new_registration', 'Eventos - nuevo miembro se ha registrado (copia de miembro)', 'Se le ha registrado con éxito en el evento!', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nFelicitaciones por el registro de {EVENT}.\r\n\r\nPor favor, mantenga este e-mail para sus registros, ya que contiene una información importante que usted pueda necesitar.\r\n\r\n-\r\nSaludos cordiales,\r\nAdministración', 1),
(39, 'de', 'events_new_registration', 'Veranstaltungen - neues Mitglied registriert hat (Mitglied Kopie)', 'Sie haben erfolgreich an der Veranstaltung angemeldet haben!', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nHerzlichen Glückwunsch zu der Registrierung zu {EVENT}.\r\n\r\nBitte bewahren Sie diese E-Mail für Ihre Aufzeichnungen, da sie eine wichtige Information, die Sie benötigen enthält.\r\n\r\n-\r\nMit besten Grüßen,\r\nVerwaltung', 1),
(40, 'en', 'order_canceled', 'Reservation has been canceled by Customer/Administrator', 'Your order has been canceled!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order {BOOKING NUMBER} has been canceled.\r\n\r\n{BOOKING DETAILS}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(41, 'es', 'order_canceled', 'Reserva ha sido cancelada por Cliente/Administrator', 'Su pedido ha sido cancelado!', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nSu pedido {BOOKING_NUMBER} ha sido cancelado.\r\n\r\n{BOOKING DETAILS}\r\n\r\n{REFUND INFORMATION}\r\n\r\nPD Por favor, no dude en contactar con nosotros si tiene alguna pregunta.\r\n\r\n-\r\nAtentamente,\r\nSoporte al Cliente\r\n\r\n{HOTEL INFO}', 1),
(42, 'de', 'order_canceled', 'Die Reservierung muss durch Kunden/Administrator wurde abgesagt', 'Ihre Bestellung wurde abgesagt!', 'Sehr geehrte <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nIhre Bestellung {BOOKING NUMBER} wurde abgebrochen.\r\n\r\n{BOOKING DETAILS}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Bitte zögern Sie nicht uns zu kontaktieren, wenn Sie Fragen haben.\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support\r\n\r\n{HOTEL INFO}', 1),
(43, 'de', 'order_refunded', 'Die Reservierung wurde erstattet Administrator', 'Ihre Bestellung wurde erstattet', 'Liebe <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nIhre Bestellung {BOOKING NUMBER} wurde erstattet!\r\n\r\n{BOOKING DETAILS}\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nCustomer Support', 1),
(44, 'en', 'order_refunded', 'Reservation has been refunded by administrator', 'Your order  has been refunded', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order {BOOKING NUMBER} has been refunded!\r\n\r\n{BOOKING DETAILS}\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(45, 'es', 'order_refunded', 'Reserva ha sido reembolsado por el administrador', 'Su orden ha sido reembolsado', 'Querido <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nSu orden {BOOKING NUMBER} ha sido devuelto!\r\n\r\n{BOOKING DETAILS}\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(46, 'de', 'order_status_changed', 'Reservation Status wurde geändert', 'Ihre Reservierung Status wurde geändert.', 'Liebe <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nDer Status Ihrer Reservierung #{BOOKING NUMBER} hat {STATUS DESCRIPTION} geändert worden!\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nCustomer Support', 1),
(47, 'en', 'order_status_changed', 'Reservation status has been changed', 'Your reservation status has been changed.', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThe status of your reservation #{BOOKING NUMBER} has been changed to {STATUS DESCRIPTION}!\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n', 1),
(48, 'es', 'order_status_changed', 'Estado de la reserva se ha cambiado', 'Su estado de la reserva se ha cambiado.', 'Querido <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nEl estado de su reserva #{BOOKING NUMBER} se ha cambiado a {STATUS DESCRIPTION}!\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(49, 'en', 'payment_error', 'Customer payment has been failed for some reason', 'Your payment has been failed', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThe payment for your booking {BOOKING NUMBER} has been failed. The reason was: {STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(50, 'es', 'payment_error', 'De pago del cliente ha sido fallado por alguna razón', 'Su pago se ha fallado', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nEl pago de su reserva {BOOKING NUMBER} se ha fallado. La razón era: {STATUS DESCRIPTION}\r\n \r\n{BOOKING DETAILS}\r\n\r\nPD Por favor, no dude en contactar con nosotros si tiene alguna pregunta.\r\n\r\n-\r\nAtentamente,\r\nSoporte al Cliente\r\n\r\n{HOTEL INFO}', 1),
(51, 'de', 'payment_error', 'Client-Zahlung aus irgendeinem Grund nicht bestanden', 'Ihre Zahlung wurde nicht', 'Sehr geehrte <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nDie Zahlung für Ihre Buchung {BOOKING NUMBER} wurde fehlgeschlagen. Der Grund war: {STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Bitte zögern Sie nicht uns zu kontaktieren, wenn Sie Fragen haben.\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support\r\n\r\n{HOTEL INFO}', 1),
(52, 'en', 'subscription_to_newsletter', 'Newsletter - new member has subscribed (member copy)', 'You have been subscribed to the Newsletter', 'Hello!\r\n\r\nYou are receiving this email because you, or someone using this email address, subscribed to the Newsletter of {WEB SITE}\r\n\r\nIf you do not wish to receive such emails in the future, please click this link: <a href="{BASE URL}index.php?page=newsletter&task=pre_unsubscribe&email={USER EMAIL}">Unsubscribe</a>\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(53, 'es', 'subscription_to_newsletter', 'Newsletter - nuevo miembro se ha suscrito (copia miembros)', 'Que se han suscrito al boletín de noticias', 'Hola!\r\n\r\nUsted está recibiendo este correo electrónico porque usted o alguien que use la siguiente dirección de correo electrónico, suscritas al boletín de noticias de {WEB SITE}\r\n\r\nSi usted no desea recibir dichos correos electrónicos en el futuro, por favor haga clic en este enlace: <a href="{BASE URL}index.php?page=newsletter&task=pre_unsubscribe&email={USER EMAIL}">Cancelar la suscripción</a>\r\n\r\n-\r\nSaludos cordiales,\r\nadministración', 1),
(54, 'de', 'subscription_to_newsletter', 'Newsletter - neues Mitglied abonniert hat (Mitglied Kopie)', 'Sie haben den Newsletter abonniert haben', 'Hallo!\r\n\r\nSie erhalten diese E-Mail, weil Sie oder jemand mit dieser E-Mail-Adresse, den Newsletter von {WEB SITE} abonniert\r\n\r\nWenn Sie nicht möchten, dass solche E-Mails in der Zukunft erhalten, klicken Sie bitte diesen Link: <a href="{BASE URL}index.php?page=newsletter&task=pre_unsubscribe&email={USER EMAIL}">Abmelden</a>\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nVerwaltung', 1),
(55, 'en', 'unsubscription_from_newsletter', 'Newsletter - member has unsubscribed (member copy)', 'You have been unsubscribed from the Newsletter', 'Hello!\r\n\r\nYou are receiving this email because you, or someone using this email address, unsubscribed from the Newsletter of {WEB SITE}\r\n\r\nYou can always restore your subscription, using the link below: <a href="{BASE URL}index.php?page=newsletter&task=pre_subscribe&email={USER EMAIL}">Subscribe</a>\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(56, 'es', 'unsubscription_from_newsletter', 'Newsletter - miembro ha dado de baja (miembro de la copia)', 'Se le ha cancelado la suscripción a la Newsletter', 'Hola!\r\n\r\nUsted está recibiendo este correo electrónico porque usted o alguien que use la siguiente dirección de correo electrónico, de baja de la Newsletter de {WEB SITE}\r\n\r\nSiempre podrá restaurar su suscripción, usando el siguiente enlace: <a href="{BASE URL}index.php?page=newsletter&task=pre_subscribe&email={USER EMAIL}">Suscribirse</a>\r\n\r\n-\r\nSaludos cordiales,\r\nadministración', 1),
(57, 'de', 'unsubscription_from_newsletter', 'Newsletter - Mitglied hat sich abgemeldet (Mitglied Kopie)', 'Sie haben den Newsletter abbestellt worden', 'Hallo!\r\n\r\nSie erhalten diese E-Mail, weil Sie oder jemand mit dieser E-Mail-Adresse, von der Newsletter von {WEB SITE} abgemeldet\r\n\r\nSie können immer wieder Ihr Abonnement, über den Link unten: <a href="{BASE URL}index.php?page=newsletter&task=pre_subscribe&email={USER EMAIL}">Abonnieren</a>\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nVerwaltung', 1),
(58, 'en', 'reservation_expired', 'Reservation has been expired', 'Your reservation has been expired!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order reservation has been expired.\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(59, 'es', 'reservation_expired', 'Reserva ha expirado', 'Su reserva ha sido vencido!', 'Querido <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nSu reserva orden ha sido vencido.\r\n\r\n{BOOKING DETAILS}\r\n\r\nPD Por favor, no dude en contactar con nosotros si tiene alguna pregunta.\r\n\r\n-\r\nAtentamente, \r\nAtención al cliente\r\n\r\n{HOTEL INFO}', 1),
(60, 'de', 'reservation_expired', 'Reservierung ist abgelaufen', 'Ihre Reservierung ist abgelaufen!', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nIhre Bestellung Reservierung ist abgelaufen.\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Bitte zögern Sie nicht uns zu kontaktieren, wenn Sie Fragen haben.\r\n\r\n-\r\nMit freundlichen Grüßen, \r\nKunden-Support\r\n\r\n{HOTEL INFO}', 1),
(61, 'en', 'new_review', 'Email for new review', 'You left a review', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour review has been set aside for the hotel {HOTEL}.\r\nYou can view the link below\r\n{REVIEW LINK}\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(62, 'es', 'new_review', 'Email un examen de nuevo', 'Dejaste una revisión', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nTu opinión se ha reservado para el hotel {HOTEL}.\r\nSe puede ver en el siguiente enlace\r\n{REVIEW LINK}\r\n\r\n-\r\nAtentamente,\r\nAtención al cliente', 1),
(63, 'de', 'new_review', 'E-Mail für neue Bewertung', 'Sie hinterließ eine Bewertung', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nIhre Meinung ist für das Hotel beiseite legen {HOTEL}.\r\n\r\nKönnen Sie den Link ansehen{REVIEW LINK}\r\n\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(64, 'en', 'test_template', 'Testing Email', 'Testing Email', 'Hello <b>{USER NAME}</b>!\r\n\r\nThis a testing email.\r\n\r\nBest regards,\r\n{WEB SITE}', 0),
(65, 'es', 'test_template', 'Prueba de correo electrónico', 'Prueba de correo electrónico', 'Hola <b>{USER NAME}</b>!\r\n\r\nEsta es una prueba de correo electrónico.\r\n\r\nSaludos cordiales,\r\n{WEB SITE}', 0),
(66, 'de', 'test_template', 'Testen E-Mail', 'Testen E-Mail', 'Hallo <b>{USER NAME}</b>!\r\n\r\nDies ist ein Test E-Mail.\r\n\r\nMit freundlichen Grüßen,\r\n{WEB SITE}', 0),
(67, 'en', 'notice_leave_review', 'Notice to leave a review', 'Please Leave a Review', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for using our hotel we hope that you enjoyed it.\r\nYou can post a review about our hotel <a href="{LINK REVIEW}">here</a>\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(68, 'es', 'notice_leave_review', 'Notar en dejar un comentario', 'Por favor Lave y Revev', 'Estimado <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nGracias por usar nuestro hotel, esperamos que les haya gustado usted.\r\nUsted puede dejar un comentario sobre nuestro hotel <a href="{LINK REVIEW}">aquí</a>\r\n\r\nDisfrute!\r\n-\r\nSinceramente,\r\nSoporte al cliente', 1),
(69, 'de', 'notice_leave_review', 'Bemerken Sie eine Rezension zu verlassen', 'Bitte Lave und Revev', 'Lieber <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nVielen Dank, dass Sie sich für unser Hotel wir hoffen, dass es Ihnen gefallen hat.\r\nSie können einen Überblick über unser Hotel Post <a href="{LINK REVIEW}">hier</a>\r\n\r\nViel Spaß!\r\n-\r\nMit freundlichen Grüßen,\r\nKunden-Support', 1),
(70, 'ar', 'new_account_created', 'Email for new customer', 'Your account has been created', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYou login: {USER NAME}\r\nYou password: {USER PASSWORD}\r\n\r\nYou may follow the link below to log into your account:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(71, 'ar', 'new_account_created_confirm_by_admin', 'Email for new user (admin approval required)', 'Your account has been created (approval required)', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYour login: {USER NAME}\r\nYour password: {USER PASSWORD}\r\n\r\nAfter your registration will be approved by administrator,  you could log into your account with a following link:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(72, 'ar', 'new_account_created_confirm_by_email', 'Email for new user (email confirmation required)', 'Your account has been created (confirmation required)', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on creating your new account.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYour login: {USER NAME}\r\nYour password: {USER PASSWORD}\r\n\r\nIn order to become authorized member, you will need to confirm your registration. You may follow the link below to access the confirmation page:\r\n<a href="{BASE URL}index.php?customer=confirm_registration&c={REGISTRATION CODE}">Confirm Registration</a>\r\n\r\nP.S. Remember, we will never sell your personal information or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(73, 'ar', 'new_account_created_by_admin', 'Email for new user (account created by admin)', 'Your account has been created by admin', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nOur administrator just created a new account for you.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need, should you ever encounter problems or forget your password.\r\n\r\nYou login: {USER NAME}\r\nYou password: {USER PASSWORD}\r\n\r\nYou may follow the link below to log into your account:\r\n<a href="{BASE URL}index.php?customer=login">Login</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(74, 'ar', 'new_account_created_notify_admin', 'New account has been created (notify admin)', 'New account has been created', 'Hello Admin!\r\n\r\nA new user has been registered at your site.\r\nThis email contains a user account details:\r\n\r\nName: {FIRST NAME} {LAST NAME}\r\nEmail: {USER EMAIL}\r\nUsername: {USER NAME}\r\n\r\nP.S. Please check if it doesn''t require your approval for activation', 1),
(75, 'ar', 'password_forgotten', 'Email for customer or admin forgotten password', 'Forgotten Password', 'Hello <b>{USER NAME}</b>!\r\n\r\nYou or someone else asked for your login info on our site:\r\n{WEB SITE}\r\n\r\nYour Login Info:\r\n\r\nUsername: {USER NAME}\r\nPassword: {USER PASSWORD}\r\n\r\n\r\nBest regards,\r\n{WEB SITE}', 1),
(76, 'ar', 'password_changed_by_admin', 'Password changed by admin', 'Your password has been changed', 'Hello <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour password was changed by administrator of the site:\r\n{WEB SITE}\r\n\r\nHere your new login info:\r\n-\r\nUsername: {USER NAME} \r\nPassword: {USER PASSWORD}\r\n\r\n-\r\nBest regards,\r\nAdministration', 1),
(77, 'ar', 'registration_approved_by_admin', 'Email for new customer (registration was approved by admin)', 'Your registration has been approved', 'Dear <b>{FIRST NAME} {LAST NAME}!</b>\r\n\r\nCongratulations! This e-mail is to confirm that your registration at {WEB SITE} has been approved.\r\n\r\nYou can now login in to your account now.\r\n\r\nThank you for choosing {WEB SITE}.\r\n-\r\nSincerely,\r\nAdministration', 1),
(78, 'ar', 'account_deleted_by_user', 'Account removed email (by customer)', 'Your account has been removed', 'Dear {USER NAME}!\r\n\r\nYour account was removed.\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(79, 'ar', 'new_account_created_without', 'Email for new/returned customer (without account)', 'Your contact information has been accepted', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for sending us your contact information. You may now complete your booking - just follow the instructions on the checkout page.\r\n\r\nPlease remember that even you don''t have account on our site, you may always create it with easily. To do it simply follow this link and enter all needed information to create a new account: <a href="{BASE URL}index.php?customer=create_account">Create Account</a>\r\n\r\nP.S. Remember, we will never sell your name or email address.\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(80, 'ar', 'order_placed_online', 'Email for online placed orders (not paid yet)', 'Your order has been placed in our system!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for reservation request!\r\n\r\nYour order {BOOKING NUMBER} has been placed in our system and will be processed shortly.\r\n{STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\nP.S. Please keep this email for your records, as it contains an important information that you may\r\nneed.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(81, 'ar', 'order_paid', 'Email for orders paid via payment processing systems', 'Your order {BOOKING NUMBER} has been paid and received by the system!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for reservation!\r\n\r\nYour order {BOOKING NUMBER} has been completed!\r\n\r\n{BOOKING DETAILS}\r\n\r\n{PERSONAL INFORMATION}\r\n\r\n{BILLING INFORMATION}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Please keep this email for your records, as it contains an important information that you may need.\r\nP.P.S You may always check your booking status here:\r\n<a href="{BASE URL}index.php?page=check_status">Check Status</a>\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(82, 'ar', 'events_new_registration', 'Events - new member has registered (member copy)', 'You have been successfully registered to the event!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nCongratulations on registering to {EVENT}.\r\n\r\nPlease keep this email for your records, as it contains an important information that you may need.\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(83, 'ar', 'order_canceled', 'Reservation has been canceled by Customer/Administrator', 'Your order has been canceled!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order {BOOKING NUMBER} has been canceled.\r\n\r\n{BOOKING DETAILS}\r\n\r\n{REFUND INFORMATION}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(84, 'ar', 'order_refunded', 'Reservation has been refunded by administrator', 'Your order  has been refunded', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order {BOOKING NUMBER} has been refunded!\r\n\r\n{BOOKING DETAILS}\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(85, 'ar', 'order_status_changed', 'Reservation status has been changed', 'Your reservation status has been changed.', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThe status of your reservation #{BOOKING NUMBER} has been changed to {STATUS DESCRIPTION}!\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n', 1),
(86, 'ar', 'payment_error', 'Customer payment has been failed for some reason', 'Your payment has been failed', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThe payment for your booking {BOOKING NUMBER} has been failed. The reason was: {STATUS DESCRIPTION}\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(87, 'ar', 'subscription_to_newsletter', 'Newsletter - new member has subscribed (member copy)', 'You have been subscribed to the Newsletter', 'Hello!\r\n\r\nYou are receiving this email because you, or someone using this email address, subscribed to the Newsletter of {WEB SITE}\r\n\r\nIf you do not wish to receive such emails in the future, please click this link: <a href="{BASE URL}index.php?page=newsletter&task=pre_unsubscribe&email={USER EMAIL}">Unsubscribe</a>\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(88, 'ar', 'unsubscription_from_newsletter', 'Newsletter - member has unsubscribed (member copy)', 'You have been unsubscribed from the Newsletter', 'Hello!\r\n\r\nYou are receiving this email because you, or someone using this email address, unsubscribed from the Newsletter of {WEB SITE}\r\n\r\nYou can always restore your subscription, using the link below: <a href="{BASE URL}index.php?page=newsletter&task=pre_subscribe&email={USER EMAIL}">Subscribe</a>\r\n\r\n-\r\nBest Regards,\r\nAdministration', 1),
(89, 'ar', 'reservation_expired', 'Reservation has been expired', 'Your reservation has been expired!', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour order reservation has been expired.\r\n\r\n{BOOKING DETAILS}\r\n\r\nP.S. Please feel free to contact us if you have any questions.\r\n\r\n-\r\nSincerely,\r\nCustomer Support\r\n\r\n{HOTEL INFO}', 1),
(90, 'ar', 'new_review', 'Email for new review', 'You left a review', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nYour review has been set aside for the hotel {HOTEL}.\r\nYou can view the link below\r\n{REVIEW LINK}\r\n\r\n-\r\nSincerely,\r\nCustomer Support', 1),
(91, 'ar', 'test_template', 'Testing Email', 'Testing Email', 'Hello <b>{USER NAME}</b>!\r\n\r\nThis a testing email.\r\n\r\nBest regards,\r\n{WEB SITE}', 0),
(92, 'ar', 'notice_leave_review', 'Notice to leave a review', 'Please Leave a Review', 'Dear <b>{FIRST NAME} {LAST NAME}</b>!\r\n\r\nThank you for using our hotel we hope that you enjoyed it.\r\nYou can post a review about our hotel <a href="{LINK REVIEW}">here</a>\r\n\r\nEnjoy!\r\n-\r\nSincerely,\r\nCustomer Support', 1);
