(1, 1, 2, 1, '1-800-123-4567', '1-800-123-6789', 'hotelowner1@example.com', '-8', '<iframe width="100%" height="400" frameborder="0" scrolling="no" marginheight="0" marginwidth="0" src="http://maps.google.com/maps?f=q&source=s_q&hl=en&geocode=&q=Hotel+Circle+South,+San+Diego,+California,+United+States&aq=1&sll=33.981232,-84.173813&sspn=0.12868,0.307274&ie=UTF8&hq=&hnear=Hotel+Cir+S,+San+Diego,+California&ll=32.759,-117.177036&spn=0.017215,0.038409&z=14&output=embed"></iframe>', '', '', '', '', '', 'hotel_1_a2i7oas7jv6kpwqpjobx.jpg', 'hotel_1_a2i7oas7jv6kpwqpjobx_thumb.jpg', '9.0', '4', 'a:9:{i:0;s:1:"1";i:1;s:1:"4";i:2;s:1:"5";i:3;s:1:"6";i:4;s:1:"9";i:5;s:2:"10";i:6;s:2:"11";i:7;s:2:"14";i:8;s:2:"16";}', 0, 100, 20880, 1, 1),
(2, 2, 1, 1, '1-800-123-2222', '1-800-123-2223', 'info2@example.com', '-6', '<iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d2948.0965968856144!2d-71.0666208!3d42.361780599999996!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x89e3709a3c7713c5%3A0x922cf2c02c6d4e5a!2s5+Blossom+St%2C+Charles+River+Plaza+Shopping+Center%2C+Boston%2C+MA+02114!5e0!3m2!1sen!2s!4v1405938488556" width="100%" height="450" frameborder="0" style="border:0"></iframe>', '42.3600825', '-71.0588801', '', '', '', 'hotel_2_s8vxx53oepp2owuetbdk.jpg', 'hotel_2_s8vxx53oepp2owuetbdk_thumb.jpg', '1.5', '5', 'a:8:{i:0;s:1:"4";i:1;s:1:"6";i:2;s:1:"9";i:3;s:2:"11";i:4;s:2:"12";i:5;s:2:"15";i:6;s:2:"16";i:7;s:2:"17";}', 0, 2, 16052, 0, 1),
