(4, 4, 1, 2, '1111-222-333', '1111-222-333', 'info4@example.com', '1', '<iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d2625.137151835223!2d2.2926749999999996!3d48.855595!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x47e6702219eadc43%3A0xb7764685dcef7ac5!2sHotel+Pullman+Paris+Tour+Eiffel!5e0!3m2!1sen!2s!4v1406545152765" width="100%" height="450" frameborder="0" style="border:0"></iframe>', '48.8421616', '2.2927665', '', '', '', 'hotel_4_y95eex7kcox31yj5z04a.jpg', 'hotel_4_y95eex7kcox31yj5z04a_thumb.jpg', '1.5', '4', 'a:10:{i:0;s:1:"2";i:1;s:1:"5";i:2;s:1:"8";i:3;s:2:"10";i:4;s:2:"14";i:5;s:2:"16";i:6;s:2:"18";i:7;s:2:"19";i:8;s:2:"22";i:9;s:2:"25";}', 0, 4, 12628, 0, 1),
(5, 5, 1, 3, '1-800-111-222', '1-800-123-6789', 'info5@example.com', '-1', '<iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2993.3702921490367!2d2.167727000000012!3d41.387764099999956!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x12a4a2f3affec6ab%3A0x36db9a2d544faa7b!2sRambla+de+Catalunya%2C+7%2C+08007+Barcelona%2C+Spain!5e0!3m2!1sen!2s!4v1406714817812" width="100%" height="450" frameborder="0" style="border:0"></iframe>', '41.3875467', '2.1673975', '', '', '', 'hotel_-1_e66beol23nmghnb7tkwd.jpg', 'hotel_-1_e66beol23nmghnb7tkwd_thumb.jpg', '3.0', '4', 'a:10:{i:0;s:1:"3";i:1;s:1:"4";i:2;s:1:"5";i:3;s:1:"7";i:4;s:1:"9";i:5;s:2:"13";i:6;s:2:"15";i:7;s:2:"17";i:8;s:2:"18";i:9;s:2:"23";}', 0, 10, 16279, 0, 1),
