INSERT INTO `uhb289_hotels_description` (`id`, `hotel_id`, `language_id`, `name`, `address`, `name_center_point`, `description`, `preferences`) VALUES
(1, 1, 'en', 'Rotem King Villa', 'st. Garon st., 210\r\nRonston 213456', '', '<p>Step into a world of ease, luxury and Swiss hospitality at The Stamford, our 5-star deluxe hotel. Located in the heart of the city amidst world-class shopping, entertainment and the CBD. The hotel is seated at Turn 9 of the F1 race and 20 minutes away from the Airport.</p>', ''),
(2, 1, 'es', 'Rotem Hotel Villa', 'st. Garon st., 210\r\nRonston 213456', '', '<p>Entra en un mundo de comodidad, lujo y hospitalidad suiza en The Stamford, el hotel de lujo de 5 estrellas. Situado en el corazón de la ciudad en medio de compras de clase mundial, el entretenimiento y el CDB. El hotel está sentado en la curva 9 de la carrera de F1 y 20 minutos del Aeropuerto.</p>', ''),
(3, 1, 'de', 'Rotem King Villa', 'st. Garon st., 210\r\nRonston 213456', '', '<p>Treten Sie ein in eine Welt der Leichtigkeit, Luxus und Schweizer Gastfreundschaft im Stamford, unsere 5-Sterne-Deluxe-Hotel. Das Hotel liegt im Herzen der Stadt inmitten der Weltklasse Shopping, Entertainment und der CBD. Das Hotel befindet sich in Kurve 9 des F1-Rennen sitzen und 20 Minuten vom Flughafen entfernt.</p>', ''),
(4, 2, 'en', 'Wyndham Boston Hill', '5 Blossom Street, Boston, MA 02114', '', '<p>The Museum of Science and TD Bank Garden are a short distance from this downtown Boston hotel which features completely non-smoking rooms, an on-site restaurant and many modern amenities. Thoughtful amenities at the Wyndham Boston Beacon Hill include a 24-hour fitness center, a seasonal outdoor swimming pool and modern business facilities. Guests can also enjoy on-site dining at Dean''s List restaurant, which serves small plates and has an extensive drink menu.</p>\r\n<p>The Boston Wyndham Beacon Hill is near the famed Faneuil Hall and Quincy Market. Boston Common, the Hynes Convention Center and the Boston Public Gardens are also close to the hotel.</p>', 'Here you may found our hotel preferences.'),
(5, 2, 'es', 'Wyndham Boston Hill', '5 Blossom Street, Boston, MA 02114', '', '<p>El Museo de la Ciencia y TD Bank Garden están a poca distancia de este hotel del centro de Boston, que cuenta con habitaciones totalmente para no fumadores, un restaurante del hotel y todas las comodidades modernas. Entre las instalaciones del Wyndham Boston Beacon Hill incluyen un gimnasio abierto las 24 horas, una piscina exterior de temporada y modernas instalaciones de negocios. Los huéspedes también pueden disfrutar de una cena en el lugar en el restaurante Lista del Decano, que sirve platos pequeños y tiene una extensa carta de bebidas.</p>\r\n<p>El Boston Wyndham Beacon Hill se encuentra cerca del famoso Faneuil Hall y Quincy Market. Boston Common, el Centro de Convenciones Hynes y el Jardín Público de Boston también se encuentran cerca del hotel.</p>', 'Aquí usted puede encontrado nuestras preferencias de hotel.'),
(6, 2, 'de', 'Wyndham Boston Hill', '5 Blossom Street, Boston, MA 02114', '', '<p>Das Museum für Wissenschaft und TD Bank Garden sind nur eine kurze Entfernung von diesem Innenstadt von Boston, die komplett Nichtraucher-Zimmer, ein Restaurant und zahlreiche moderne Annehmlichkeiten bietet. Zu den Annehmlichkeiten im Wyndham Boston Beacon Hill gehören eine 24-Stunden-Fitnesscenter, einen saisonalen Außenpool und moderne Business-Einrichtungen. Die Gäste können auch auf ein Restaurant genießen bei Liste Restaurant Deans, die kleinen Platten serviert und eine umfangreiche Getränkekarte.</p>\r\n<p>Die Wyndham Boston Beacon Hill ist in der Nähe der berühmten Faneuil Hall und Quincy Market. Boston Common, dem Hynes Convention Center und die Boston Public Gardens sind auch in der Nähe des Hotels.</p>', 'Hier können Sie unsere Hotelpräferenzen gefunden.'),
(7, 3, 'en', 'Park Lany Hotel', '37 Central Park South, New York City, NY 10019', '', '<p>The Park Lany Hotel is a deluxe hotel with a European atmosphere, providing views of Central Park and the New York skyline. It is only a 2-minute walk from the elegant shops of 5th Avenue and the 59th Street N,Q,R subway station. Spacious and bright, the rooms at the Park Lany Hotel are fitted with oversized windows and fine sheets. Amenities include flat-screen TVs and access to the on-site fitness center.</p>\r\n<p> </p>\r\n<p>Enjoy a seasonal menu created by Jeff Cristelli at The Park Room Restaurant, or select from a wide variety of cocktails at Harry''s New York Bar. New York’s Museum of Modern Art, Radio City Music Hall, and Rockefeller Center, are all within a 10-minute walk. With the park right in front of the hotel, jogging and recreational activities are easily accessible.</p>', 'If in your dream you see a big hotel with good furniture, ahead you will have the life full of pleasure. Stay in shabby dirty hotel with the sick owner dreams to failure or receiving a sad vital lesson.'),
(8, 3, 'es', 'Park Lany Hotel', '37 Central Park South, New York City, NY 10019', '', '<p>El Parque Lany Hotel es un hotel de lujo con un ambiente europeo, ofrece vistas a Central Park y el horizonte de Nueva York. Es sólo un 2 minutos a pie de las elegantes tiendas de la 5 ª Avenida y la calle 59 N, Q, R estación de metro. Amplias y luminosas, las habitaciones del Park Lany Hotel están equipadas con ventanas de gran tamaño y las hojas finas. Las comodidades incluyen TV de pantalla plana y acceso a un gimnasio en el lugar.</p>\r\n<p> </p>\r\n<p>Disfrute de un menú de temporada creada por Jeff Cristelli en The Park Room Restaurant, o elegir entre una amplia variedad de cócteles en casa de Harry New York Bar. Museo de Arte Moderno, el Radio City Music Hall y el Rockefeller Center de Nueva York, se encuentran a 10 minutos a pie. Con el parque justo en frente del hotel, footing y actividades recreativas son fácilmente accesibles.</p>', 'Si en su sueño se ve un gran hotel con un buen mobiliario, por delante tendrá la vida llena de placer. Permanezca en mal estado sucio hotel con el dueño enfermo sueña al fracaso o al recibir una lección vital triste.'),
(9, 3, 'de', 'Park Lany Hotel', '37 Central Park South, New York City, NY 10019', '', '<p>Das Park Hotel ist ein Lany-Deluxe-Hotel mit europäischer Atmosphäre, die den Blick auf den Central Park und die Skyline von New York. Es ist nur 2 Gehminuten von den eleganten Geschäften der 5th Avenue und der 59th Street N, Q, R U-Bahn-Station. Geräumig und hell sind die Zimmer des Park Hotels Lany mit übergroßen Fenstern und Feinbleche ausgestattet. Zur Ausstattung gehören Flachbild-TV und Zugang zum hoteleigenen Fitnesscenter .</p>\r\n<p> </p>\r\n<p>Genießen Sie ein saisonales Menü von Jeff Cristelli im The Park Room Restaurant, oder aus einer Vielzahl von Cocktails in Harrys New York Bar wählen. Museum of Modern Art, die Radio City Music Hall und das Rockefeller Center in New York, sind alle innerhalb von 10 Gehminuten. Mit dem Park direkt vor dem Hotel, Jogging-und Freizeitaktivitäten sind leicht zugänglich.</p>', 'Wenn in Ihrem Traum sehen Sie ein großes Hotel mit guten Möbeln, vor Ihnen das Leben voller Freude zu haben. Bleiben Sie in schäbigen dreckiges Hotel mit dem kranken Besitzer träumt zum Scheitern oder Empfangen eines traurigen wichtige Lektion.'),
(10, 4, 'en', 'Pulman Paris Tour Eiffel', '18 Avenue De Suffren, Entrée au 21 rue Jean Rey, 15th arr. - Porte de Versailles, 75015 Paris', '', '<p>The 4-star hotel Pullman Paris Tour Eiffel is set at the foot of the Eiffel Tower and the Trocadero. The fitness room with cardio equipment, open 24 hours a day, offers unrestricted views of the Trocadero, and you can enjoy dining on the terrace at the restaurant, Frame in this place.</p>\r\n<p>Decorated in contemporary style, the bright guest rooms offer panoramic views of Paris. They includes a flat-screen TV with free access to the latest movies, an iPod dock and free Wi-Fi access. Most of the rooms have a balcony, and some also have a stunning view of the Eiffel Tower or the garden.</p>\r\n<p>The hotel''s restaurant serves Californian-style cuisine with French flavors. It has an open-plan kitchen and a stylish wine bar. A connectivity lounge featuring computers, tablets and printers is also available in the hotel.</p>\r\n<p>Pullman Paris is on the Left Bank, just a 5-minute walk from the Eiffel Tower. It is in a great location, less than half a mile from the Bir-Hakeim Metro Station (line 6), providing direct access to the Arc de Triomphe, Champs Élysées and Louvre Museum. Private parking is available on site.</p>', 'Pullman Paris is on the Left Bank, just a 5-minute walk from the Eiffel Tower. It is in a great location, less than half a mile from the Bir-Hakeim Metro Station (line 6), providing direct access to the Arc de Triomphe'),
(11, 4, 'es', 'Pulman Paris Tour Eiffel', '18 Avenue De Suffren, Entrée au 21 rue Jean Rey, 15th arr. - Porte de Versailles, 75015 Paris', '', '<p>El hotel de 4 estrellas Pullman Paris Tour Eiffel se encuentra a los pies de la Torre Eiffel y el Trocadero. La sala de fitness con equipos de cardio, abierta las 24 horas del día, ofrece vistas sin restricciones del Trocadero, y se puede disfrutar de una cena en la terraza del restaurante, Marco.</p>\r\n<p>Decorado en estilo contemporáneo, las habitaciones son luminosas y ofrecen vistas panorámicas a París. Ellos incluyen una TV de pantalla plana con acceso gratuito a las últimas películas, soporte para iPod y conexión Wi-Fi gratuita. La mayoría de las habitaciones tienen balcón, y algunos también tienen una impresionante vista de la Torre Eiffel o al jardín.</p>\r\n<p> </p>\r\n<p>El restaurante del hotel sirve cocina de estilo californiano con sabores franceses. Cuenta con una cocina de planta abierta y un elegante bar de vinos. Un salón de la conectividad que ofrece ordenadores, tablets e impresoras también está disponible en el hotel.</p>\r\n<p>Pullman Paris está en la margen izquierda del río, a sólo 5 minutos a pie de la Torre Eiffel. Se encuentra en una excelente ubicación, a menos de media milla de la estación de metro de Bir-Hakeim (línea 6), que conecta directamente con el Arco de Triunfo, los Campos Elíseos y el Museo del Louvre. Parking privado disponible en el hotel.</p>', 'Pullman Paris está en la margen izquierda del río, a sólo 5 minutos a pie de la Torre Eiffel. Se encuentra en una excelente ubicación, a menos de media milla de la estación de metro de Bir-Hakeim (línea 6), que conecta directamente con el Arco del Triunfo'),
(12, 4, 'de', 'Pulman Paris Tour Eiffel', '18 Avenue De Suffren, Entrée au 21 rue Jean Rey, 15th arr. - Porte de Versailles, 75015 Paris', '', '<p>Das 4-Sterne-Hotel Pullman Paris Tour Eiffel befindet sich am Fuße des Eiffelturm und der Trocadero gesetzt. Der Fitnessraum mit Cardio-Geräten, 24 Stunden am Tag, bietet eine uneingeschränkte Sicht des Trocadero, und Sie sich auf der Terrasse im Restaurant, Rahmen genießen können.</p>\r\n<p>Im modernen Stil eingerichteten, hellen Zimmer bieten einen Panoramablick auf Paris. Sie verfügt über einen Flachbild -TV mit freiem Zugang zu den neuesten Filmen, einer iPod-Dockingstation und kostenlosem WLAN-Zugang. Die meisten Zimmer haben einen Balkon, und einige haben auch einen atemberaubenden Blick auf den Eiffelturm oder den Garten.</p>\r\n<p>Das Hotelrestaurant serviert kalifornischen Stil Küche mit Französisch Aromen. Es verfügt über eine offene Küche und eine stilvolle Weinbar. A-Konnektivität Lounge mit Computern, Tablets und Drucker ist auch im Hotel zur Verfügung.</p>\r\n<p> </p>\r\n<p>Pullman Paris auf dem linken Ufer, nur 5 Gehminuten vom Eiffelturm entfernt. Es ist in einer großartigen Lage, weniger als eine halbe Meile von der Metro-Station Bir-Hakeim (Linie 6) und bietet direkten Zugang zum Arc de Triomphe, Champs Elysées und Louvre. Private Parkplätze stehen vor Ort zur Verfügung.</p>', 'Pullman Paris auf dem linken Ufer, nur 5 Gehminuten vom Eiffelturm entfernt. Es ist in einer großartigen Lage, weniger als eine halbe Meile von der Metro-Station Bir-Hakeim (Linie 6) und bietet direkten Zugang zum Arc de Triomphe'),
(13, 5, 'en', 'H9 Metropolitan', 'Rambla Catalunya, 7-11, L''Eixample, 08007 Barcelona', '', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi.</p>\r\n<p>Each room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom comes with a hairdryer and bathrobes.</p>\r\n<p>The H9 Metropolitan is located just 2 minutes'' walk from Paseo de Gracia Avenue, with its boutique and designer fashion stores.</p>\r\n<p>The hotel is 700 metres from Gaudi''s La Pedrera, and you can walk to Las Ramblas in 3 minutes. You can reach La Sagrada Familia in about 10 minutes by metro.</p>', 'Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi.\r\n'),
(14, 5, 'es', 'H9 Metropolitan', 'Rambla Catalunya, 7-11, L''Eixample, 08007 Barcelona', '', '<p>Cuenta con una terraza en la azotea con un bar, una piscina chill-out y un gimnasio, H10 Metropolitan se encuentra en Barcelona, ​​a 90 metros de la Plaça Catalunya. Ofrece un restaurante de tapas y WiFi gratuito.</p>\r\n<p>Todas las habitaciones cuentan con TV de pantalla plana vía satélite, aire acondicionado, cafetera y minibar. El cuarto de baño privado con secador de pelo y albornoces.</p>\r\n<p>La H9 Metropolitan se encuentra a sólo 2 minutos a pie del Paseo de Gracia, con sus boutiques y tiendas de diseñadores.</p>\r\n<p>El hotel se encuentra a 700 metros de La Pedrera de Gaudí, y puedes ir andando a Las Ramblas en 3 minutos. Se puede llegar a La Sagrada Familia en unos 10 minutos en metro.</p>', 'Cuenta con una terraza en la azotea con un bar, una piscina chill-out y un gimnasio, H10 Metropolitan se encuentra en Barcelona, ​​a 90 metros de la Plaça Catalunya. Ofrece un restaurante de tapas y WiFi gratuito. '),
(15, 5, 'de', 'H9 Metropolitan', 'Rambla Catalunya, 7-11, L''Eixample, 08007 Barcelona', '', '<p>Mit einer Dachterrasse mit Bar, Chill-out-Pool und Fitnessraum ist H10 Metropolitan in Barcelona, ​​90 m von der Plaça Catalunya. Es bietet ein Tapas-Restaurant und kostenloses WiFi.</p>\r\n<p>Jedes Zimmer verfügt über einen Flachbild -Sat-TV, Klimaanlage , Kaffeemaschine und eine Minibar. Das private Badezimmer ist mit einem Haartrockner und Bademänteln.</p>\r\n<p>Die H9 Metropolitan befindet sich nur 2 Gehminuten vom Paseo de Gracia Avenue mit ihren Boutiquen und Designer-Fashion-Stores.</p>\r\n<p>Das Hotel liegt 700 Meter von Gaudis La Pedrera, und Sie können nach Las Ramblas in 3 Minuten zu Fuß. Sie können La Sagrada Familia in etwa 10 Minuten mit der U-Bahn.</p>', 'Mit einer Dachterrasse mit Bar, Chill-out-Pool und Fitnessraum ist H10 Metropolitan in Barcelona, ​​90 m von der Plaça Catalunya. Es bietet ein Tapas-Restaurant und kostenloses WiFi. '),
(16, 6, 'en', 'Izmailovo Alpha Hotel', 'Izmailovskoye Shosse 71A, Izmailovo, 105613 Moscow, Russia', '', '<p>Part of the vast Izmailovo Hotel Complex, built for the 1980 Olympic Games, the Izmailovo Alfa is a little more expensive than its sister properties, a policy it justifies with its extensive conferencing facilities and the high standards of top room categories. Located in the north-east of Moscow, the hotel offers very fast access to the downtown by metro. <br /><br /> The hotel’s 945 rooms range from low-cost options very basic furniture and fittings to really quite luxurious rooms on the Izmailovo Alfa’s Club Floor. All rooms are covered by complimentary WiFi access. The hotel also has a modern business center with large and flexible conference halls. Equally suitable for business travelers and tourists, the Izmailovo Alfa Hotel also has a wide range of concierge services, and several bars and restaurants on site. Other services, including fitness centre, are available nearby in other parts of the Izmailovo Hotel Complex. While you should not expect particularly friendly or attentive service at the Izmailovo Alfa, staff are efficient and mostly speak good English.</p>', ''),
(17, 6, 'es', 'Izmailovo Alpha Hotel', 'Izmailovskoye Shosse 71A, Izmailovo, 105613 Moscow, Russia', '', '<p>Parte de la gran complejo Izmailovo Hotel, construido para los Juegos Olímpicos de 1980, el Izmailovo Alfa es un poco más caro que sus propiedades hermanas, una política que justifica con sus amplias instalaciones para conferencias y los altos estándares de las mejores categorías de habitaciones. Situado en el noreste de Moscú, el hotel ofrece un acceso muy rápido al centro de la ciudad en metro.</p>', ''),
(18, 6, 'de', 'Izmailovo Alpha Hotel', 'Izmailovskoye Shosse 71A, Izmailovo, 105613 Moscow, Russia', '', '<p>Teil des riesigen Izmailovo Hotel Complex, für die Olympischen Spiele 1980 gebaut, ist der Alfa Izmailovo ein wenig teurer ist als seine Schwester Eigenschaften, eine Politik es mit seinem umfangreichen Konferenzeinrichtungen und den hohen Standards der Top-Zimmer-Kategorien rechtfertigt. Das Hotel liegt im Nordosten von Moskau, bietet das Hotel einen sehr schnellen Zugriff auf die Innenstadt von der U-Bahn.</p>', ''),
(19, 7, 'en', 'Hilton Tel Aviv Hotel ', 'Independence Park, Tel Aviv, 63405, Israel', '', '<p>Set within Independence Park and providing direct access to Hilton Beach and Tel Aviv promenade, the Hilton Tel Aviv features a large outdoor salt water pool, 5 kosher restaurants and a spa. <br /> <br /> Its spacious air-conditioned rooms include a flat-screen TV and a private balcony with a sea view. The luxurious marble bathroom includes Ahava amenities and a lavish bathrobe. <br /><br /> The Tel Aviv Hilton’s spa and health club features a well-equipped fitness room and various treatments and massages. You can also relax and enjoy the sea views from the terrace with lounge chairs and umbrellas. <br /><br /> The Hilton Tel Aviv Hotel also has a 24-hour lobby restaurant, a synagogue and a hair &amp; beauty salon. Hayarkon Park, which has botanical gardens and sports facilities, is just a 10-minute walk away. Ben Gurion Airport is a 25-minute drive away. <br /><br /> Guests can choose from a range of kosher dining options, from breakfast in Café Med, to a relaxed lunch in Yakimono Sushi Bar or an evening meal in the King Solomon Restaurant.</p>', 'Set within Independence Park and providing direct access to Hilton Beach and Tel Aviv promenade, the Hilton Tel Aviv features a large outdoor salt water pool, 5 kosher restaurants and a spa. '),
(20, 7, 'es', 'Hilton Tel Aviv Hotel', 'Independence Park, Tel Aviv, 63405, Israel', '', '<p>situado en el parque Independencia y ofrece acceso directo a la playa de Hilton y el paseo marítimo de Tel Aviv, el hotel Hilton Tel Aviv cuenta con una gran piscina de agua salada al aire libre, 5 restaurantes kosher y un spa. <br /> <br /> Sus amplias habitaciones cuentan con aire acondicionado, TV de pantalla plana y un balcón privado con vistas al mar. El lujoso baño de mármol con artículos de aseo Ahava y una bata de baño de lujo. <br /> spa y club de salud <br /> El Tel Aviv Hilton incluye un gimnasio bien equipado y diversos tratamientos y masajes. También podrá relajarse y disfrutar de las vistas al mar desde la terraza con tumbonas y sombrillas. <br /> <br /> El Hilton Tel Aviv Hotel también dispone de un restaurante abierto las 24 horas, una sinagoga y un cabello &amp; amp; salón de belleza. Hayarkon Park, que cuenta con jardines botánicos e instalaciones deportivas, está a sólo 10 minutos a pie. Ben Gurion Airport se encuentra a 25 minutos en coche. <br /> <br /> Los huéspedes pueden elegir entre una gama de opciones de restaurantes kosher, desde el desayuno en el Café Med, para un almuerzo relajado en Yakimono Sushi Bar o una cena en el restaurante King Salomon. <!-- p--></p>', 'Situado en el parque Independencia y ofrece acceso directo a la playa de Hilton y el paseo marítimo de Tel Aviv, el hotel Hilton Tel Aviv cuenta con una gran piscina de agua salada al aire libre, 5 restaurantes kosher y un spa.'),
(21, 7, 'de', 'Hilton Tel Aviv Hotel', 'Independence Park, Tel Aviv, 63405, Israel', '', '<p>im Independence Park Set und bietet direkten Zugang zu Hilton Beach und Tel Aviv Promenade gelegen, bietet das Hilton Tel Aviv eine große Salzwasser-Außenpool , 5 koschere Restaurants und ein Spa. <br /> <br /> Die geräumigen klimatisierten Zimmer sind mit einem Flachbild -TV und einen privaten Balkon mit Meerblick. Das luxuriöse Marmorbad Ahava Ausstattung und eine üppige Bademantel. <br /> Spa und Health Club <br /> Tel Aviv Hilton verfügt über einen gut ausgestatteten Fitnessraum und verschiedene Anwendungen und Massagen. Sie können auch entspannen und genießen die Aussicht auf das Meer von der Terrasse mit Liegestühlen und Sonnenschirmen. <br /> <br /> Das Hilton Tel Aviv Hotel hat auch einen 24-Stunden-Lobby-Restaurant, eine Synagoge und ein Haar &amp; amp; Schönheitssalon. Hayarkon Park, der botanischen Gärten und Sportanlagen hat, liegt nur 10 Gehminuten entfernt. Ben-Gurion-Flughafen ist eine 25-minütige Autofahrt entfernt. <br /> <br /> Die Gäste können aus einer Reihe von koscheren Restaurants wählen, vom Frühstück in Café Med, zu einem entspannten Mittagessen in Yakimono Sushi Bar oder ein Abendessen im King Solomon Restaurant. <!-- p--></p>', 'Innerhalb Independence Park gesetzt und bietet direkten Zugang zu Hilton Beach und Tel Aviv Promenade gelegen, bietet das Hilton Tel Aviv eine große Salzwasser-Außenpool , 5 koschere Restaurants und ein Spa.'),
(22, 8, 'en', 'Leonardo Hotel Vienna', 'Matosengasse 6-9, 06. Marihilf, 1060 Vienna, Austria', '', '<p>Opened in July 2012, this non-smoking 4-star hotel is just 100 yards from the Mariahilfer Straße shopping street and a quarter mile from the Westbahnhof transportation hub. Central Vienna can be reached by subway in 5 minutes. <br /><br /> The modern, air-conditioned rooms at Leonardo Hotel Vienna feature a flat-screen TV, a minibar, a tea/coffee maker, and a bathroom with a hairdryer and a make-up mirror. <br /><br /> The restaurant Vitruv serves Austrian and international cuisine. Guests of the Vienna Leonardo Hotel have a business center and a 24-hour front desk. <br /><br /> The entrance to the Westbahnhof subway station is only 220 yards away. The Technical Museum and the Haus des Meeres Aquarium are both one mile away.</p>', 'Opened in July 2012, this non-smoking 4-star hotel is just 100 yards from the Mariahilfer Straße shopping street and a quarter mile from the Westbahnhof transportation hub. Central Vienna can be reached by subway in 5 minutes. \r\n'),
(23, 8, 'es', 'Leonardo Hotel Vienna', 'Matosengasse 6-9, 06. Marihilf, 1060 Vienna, Austria', '', '<p>Inaugurado en julio de 2012, este hotel de no fumadores de 4 estrellas está a sólo 100 metros de la calle comercial Mariahilfer Straße y un cuarto de milla del centro de transporte de Westbahnhof. Central Vienna se puede llegar en metro en 5 minutos.  <br /><br /> Las modernas habitaciones con aire acondicionado de Leonardo Hotel Vienna cuentan con TV de pantalla plana, minibar, cafetera / tetera y cuarto de baño con secador de pelo y espejo de aumento.  <br /><br /> El restaurante Vitruv sirve cocina austriaca e internacional. Los huéspedes del Vienna Leonardo Hotel disponen de un centro de negocios y servicio de recepción las 24 horas.  <br /><br /> La entrada a la estación de metro de Westbahnhof está a sólo 220 metros de distancia. El Museo de la Técnica y la Haus des Meeres Acuario están a una milla de distancia.</p>', 'Inaugurado en julio de 2012, este hotel de no fumadores de 4 estrellas está a sólo 100 metros de la calle comercial Mariahilfer Straße y un cuarto de milla del centro de transporte de Westbahnhof. Central Vienna se puede llegar en metro en 5 minutos. '),
(24, 8, 'de', 'Leonardo Hotel Vienna', 'Matosengasse 6-9, 06. Marihilf, 1060 Vienna, Austria', '', '<p>Im Juli 2012 eröffnet wurde, ist das Nichtraucher-4-Sterne-Hotel, nur 100 Meter von der Einkaufsmeile Mariahilfer Straße und ein Viertel Meile vom Verkehrsknotenpunkt Westbahnhof. Zentrum von Wien kann der U-Bahn in 5 Minuten zu erreichen.  <br /><br /> Die modernen, klimatisierten Zimmer im Leonardo Hotel Vienna verfügen über einen Flachbild -TV, eine Minibar, einen Tee / Kaffeekocher und ein Badezimmer mit Haartrockner und Schminkspiegel.  <br /><br /> Das Restaurant Vitruv serviert österreichische und internationale Küche. Gäste des Leonardo Hotel Vienna haben ein Business-Center und eine 24-Stunden-Rezeption.  <br /><br /> Der Eingang zur U-Bahnstation Westbahnhof ist nur 220 Meter entfernt. Das Technische Museum und das Haus des Meeres Aquarium sind beide eine Meile entfernt.</p>', 'Im Juli 2012 eröffnet wurde, ist das Nichtraucher-4-Sterne-Hotel, nur 100 Meter von der Einkaufsmeile Mariahilfer Straße und ein Viertel Meile vom Verkehrsknotenpunkt Westbahnhof. Zentrum von Wien kann der U-Bahn in 5 Minuten zu erreichen. '),
(25, 9, 'en', 'Exe Puerta Castilla', 'Paseo de la Castellana, 187, Tetuán, 22046 Madrid, Spain', '', '<p>Just 2 Metro Stops from Real Madrid''s Santiago Bernabéu Stadium, this hotel is located next to the Kio Towers on Paseo de la Castellana. It features free Wi-Fi, a spa and a free gym. <br /><br /> The bright, air-conditioned rooms at the Exe Puerta Castilla have flat-screen satellite TVs. There are ironing facilities and a suit press. The private bathrooms have a hairdryer and exclusive amenities. Room service is available. <br /><br /> The hotel spa includes a Turkish bath, sauna and hot tub. It is available for an additional fee. <br /><br /> The Puerta Castilla is next to Plaza de Castilla Metro Station. On-site parking is available for an extra fee, and car rental is available at the tour desk. The hotel has a 24-hour front desk.</p>', 'Just 2 Metro Stops from Real Madrid''s Santiago Bernabéu Stadium, this hotel is located next to the Kio Towers on Paseo de la Castellana. It features free Wi-Fi, a spa and a free gym.'),
(26, 9, 'es', 'Exe Puerta Castilla', 'Paseo de la Castellana, 187, Tetuán, 22046 Madrid, Spain', '', '<p>A tan sólo 2 paradas en metro del estadio Santiago Bernabéu del Real Madrid, este hotel está situado junto a las Torres Kio, en el Paseo de la Castellana. Cuenta con conexión Wi-Fi gratuita, un spa y un gimnasio gratuito. <br /><br /> Las luminosas habitaciones con aire acondicionado del Exe Puerta Castilla disponen de TV vía satélite de pantalla plana. Hay utensilios de planchado y un traje de prensa. Los baños tienen secador de pelo y artículos de aseo exclusivos. El servicio de habitaciones está disponible. <br /><br /> El spa del hotel cuenta con baño turco, sauna y bañera de hidromasaje. Está disponible por un cargo adicional. <br /><br /> La Puerta Castilla está al lado de la estación de metro de Plaza de Castilla. El aparcamiento está disponible por un suplemento, y de alquiler de coches está disponible en el mostrador de información turística. El hotel cuenta con una recepción abierta las 24 horas.</p>', 'A tan sólo 2 paradas en metro del estadio Santiago Bernabéu del Real Madrid, este hotel está situado junto a las Torres Kio, en el Paseo de la Castellana. Cuenta con conexión Wi-Fi gratuita, un spa y un gimnasio gratuito.'),
(27, 9, 'de', 'Exe Puerta Castilla', 'Paseo de la Castellana, 187, Tetuán, 22046 Madrid, Spain', '', '<p>Nur 2 Haltestellen von Real Madrids Santiago-Bernabéu-Stadion, das Hotel befindet sich neben den Kio-Türmen, an der Paseo de la Castellana. Es verfügt über kostenfreies WLAN, ein Spa und einen kostenlosen Fitnessraum. <br /><br /> Die hellen, klimatisierten Zimmer im Exe Puerta Castilla verfügen über Flachbild-Sat-TV. Es gibt Bügeleisen und eine Hosenpresse. Die privaten Badezimmer verfügen über einen Haartrockner und exklusiven Annehmlichkeiten. Der Zimmerservice steht zur Verfügung. <br /><br /> Das hoteleigene Spa umfasst ein Türkisches Bad, eine Sauna und einen Whirlpool. Es ist für eine zusätzliche Gebühr zur Verfügung. <br /><br /> Das Puerta Castilla liegt neben dem U-Bahnhof Plaza de Castilla. Parken auf dem Gelände ist für eine zusätzliche Gebühr zur Verfügung, und eine Autovermietung ist an der Tour Desk zur Verfügung. Das Hotel verfügt über eine 24-Stunden-Rezeption.</p>', 'Nur 2 Haltestellen von Real Madrids Santiago-Bernabéu-Stadion, das Hotel befindet sich neben den Kio-Türmen, an der Paseo de la Castellana. Es verfügt über kostenfreies WLAN, ein Spa und einen kostenlosen Fitnessraum.'),
(28, 10, 'en', 'Hotel Turia', 'Profesor Betran Baguena, 2, 47009 Valencia, Spain', '', '<p>Hotel Turia is next to Valencia Bus Station, and just under a quarter of a mile from Turia Metro Station. Set across the Turia Park from the Botanical Gardens, it is a 20-minute walk from the cathedral. <br /><br /> All air-conditioned rooms at the Turia Hotel have a TV and most feature a private balcony. There is a safe, and the private bathroom includes a hairdryer. <br /><br /> Nuevo Centro Shopping Center and El Corte Inglés Department Store are across from the hotel. Excellent public transportation makes it easy to reach City of Arts and Sciences, airport and Convention Centre. <br /><br /> The Turia has a bar, and guests can relax on the hotel terrace. <br /><br /> Free Wi-Fi is available throughout. Car rental is provided, and there is also on-site parking available. The hotel has a tour desk and a 24-hour front desk.</p>', 'Hotel Turia is next to Valencia Bus Station, and just under a quarter of a mile from Turia Metro Station. Set across the Turia Park from the Botanical Gardens, it is a 20-minute walk from the cathedral.\r\n\r\nAll air-conditioned rooms at the Turia Hotel have a TV and most feature a private balcony. There is a safe, and the private bathroom includes a hairdryer.'),
(29, 10, 'es', 'Hotel Turia', 'Profesor Betran Baguena, 2, 47009 Valencia, Spain', '', '<p>Hotel Turia está al lado de la estación de autobuses de Valencia, y un poco menos de un cuarto de milla de la estación de metro Turia. Establecer a través del Parque Turia desde el Jardín Botánico, que está a 20 minutos a pie de la catedral. <br /><br /> Todas las habitaciones con aire acondicionado del Hotel Turia tienen TV y la mayoría disponen de balcón privado. Hay una caja fuerte y baño privado con secador de pelo. <br /><br /> Nuevo Centro Shopping Center y El Corte Inglés están al otro lado del hotel. Excelente transporte público hace que sea fácil llegar a la Ciudad de las Artes y las Ciencias, el aeropuerto y el centro de convenciones. <br /><br /> El Turia cuenta con un bar, y los huéspedes pueden relajarse en la terraza del hotel. <br /><br /> Hay conexión Wi-Fi gratuita en todo. Alquiler de coches es siempre, y también hay aparcamiento en el lugar disponible. El hotel cuenta con un mostrador de información turística y servicio de recepción las 24 horas.</p>', 'Hotel Turia está al lado de la estación de autobuses de Valencia, y un poco menos de un cuarto de milla de la estación de metro Turia. Establecer a través del Parque Turia desde el Jardín Botánico, que está a 20 minutos a pie de la catedral.\r\n\r\nTodas las habitaciones con aire acondicionado del Hotel Turia tienen TV y la mayoría disponen de balcón privado. Hay una caja fuerte y baño privado con secador de pelo.'),
(30, 10, 'de', 'Hotel Turia', 'Profesor Betran Baguena, 2, 47009 Valencia, Spain', '', '<p>Hotel Turia befindet sich neben dem Busbahnhof von Valencia und knapp ein Viertel der eine Meile von der U-Bahnstation Turia. Nahe dem Turia Park und dem Botanischen Garten wohnen Sie hier einen 20-minütigen Spaziergang vom Dom entfernt. <br /><br /> Die klimatisierten Zimmer im Hotel Turia bieten alle einen TV und die meisten verfügen über einen eigenen Balkon. Es gibt einen Safe und ein eigenes Bad mit Haartrockner. <br /><br /> Nuevo Centro Shopping Center und El Corte Inglés Kaufhaus sind gegenüber dem Hotel. Exzellente öffentliche Verkehrsmittel macht es einfach, Stadt der Künste und Wissenschaften, den Flughafen und das Kongresszentrum erreichen. <br /><br /> Die Turia verfügt über eine Bar, und die Gäste können auf der Terrasse entspannen. <br /><br /> Kostenloses W-LAN im gesamten Hotel. Eine Autovermietung ist vorgesehen, und es gibt auch Parkplätze am Hotel zur Verfügung. Das Hotel verfügt über einen Tourenschalter und eine 24-Stunden-Rezeption.</p>', 'Hotel Turia befindet sich neben dem Busbahnhof von Valencia und knapp ein Viertel der eine Meile von der U-Bahnstation Turia. Nahe dem Turia Park und dem Botanischen Garten wohnen Sie hier einen 20-minütigen Spaziergang vom Dom entfernt.\r\n\r\nDie klimatisierten Zimmer im Hotel Turia bieten alle einen TV und die meisten verfügen über einen eigenen Balkon. Es gibt einen Safe und ein eigenes Bad mit Haartrockner.'),
(31, 11, 'en', 'Ukraine Hotel', 'Institutskaya Street 4, Kiev, 01001, Ukraine', '', '<p>On Independence Square in the heart of Kiev, this hotel offers air conditioned rooms and suites with elegant décor. It is a 3-minute walk from the Maidan Nezalezhnosti and Kreschatik Metro Stations.</p>\r\n<p>In-room facilities at the Ukraine Hotel include satellite TV and a refrigerator. Your bathroom includes free toiletries and perfumes. Guests enjoy views of the Kreschatyk Street and the surrounding area.</p>\r\n<p>A large breakfast buffet is available at the Ukraine Hotel, and 24-hour room service is offered. Ukrainian and European cuisine is served for lunch and dinner. Live music is sometimes played here.</p>\r\n<p>The hotel features a beauty salon, sauna and massage facilities. A private laundry service is also available.</p>\r\n<p>Hotel Ukraine is a 10-minute walk from Mariyinsky Park and the St. Sofia Cathedral. Secure parking is available on site.</p>', 'On Independence Square in the heart of Kiev, this hotel offers air conditioned rooms and suites with elegant décor. It is a 3-minute walk from the Maidan Nezalezhnosti and Kreschatik Metro Stations.'),
(32, 11, 'es', 'Ucrania Hotel', 'Institutskaya Street 4, Kiev, 01001, Ucrania', '', '<p>En la Plaza de la Independencia, en el corazón de Kiev, este hotel ofrece habitaciones y suites con una decoración elegante con aire acondicionado. Se encuentra a 3 minutos a pie de la estación de metro Maidan Nezalezhnosti y Khreshchatyk.</p>\r\n<p>Los servicios de habitación en el Ucrania Hotel incluyen TV vía satélite y nevera. Su cuarto de baño con artículos de aseo y perfumes libres. Los huéspedes disfrutan de vistas a la calle Kreschatyk y sus alrededores.</p>\r\n<p>Un abundante desayuno buffet se sirve en el hotel de Ucrania, y servicio de habitaciones 24 horas a su disposición. Cocina ucraniana y europea, se sirve para el almuerzo y la cena. La música en vivo es a veces jugado aquí.</p>\r\n<p>El hotel dispone de un salón de belleza, sauna y servicio de masajes. El servicio de lavandería privada también está disponible.</p>\r\n<p>Hotel Ucrania se encuentra a 10 minutos a pie de Mariyinsky Park y la Catedral de Santa Sofía. Aparcamiento vigilado disponible en el sitio.</p>', 'En la Plaza de la Independencia, en el corazón de Kiev, este hotel ofrece habitaciones y suites con una decoración elegante con aire acondicionado. Se encuentra a 3 minutos a pie de la estación de metro Maidan Nezalezhnosti y Khreshchatyk.'),
(33, 11, 'de', 'Hotel Ukraine', 'Institutskaya Street 4, Kiew, 01001, Ukraine', '', '<p>Auf dem Platz der Unabhängigkeit im Herzen von Kiew bietet dieses Hotel klimatisierte Zimmer und Suiten mit eleganter Ausstattung. Es ist ein 3-Minuten-Spaziergang vom Maidan Nezalezhnosti und Kreschatik U-Bahnhöfe.</p>\r\n<p>In-Ausstattung der Zimmer im Hotel Ukraine gehören Sat-TV und einen Kühlschrank. Ihr Bad ist mit kostenlosen Pflegeprodukten und Parfüms. Genießen Sie den Blick von der Straße Kreschatyk und die Umgebung.</p>\r\n<p>Ein reichhaltiges Frühstücksbuffet steht im Hotel Ukraine, und der 24-Stunden-Zimmerservice wird angeboten. Ukrainische und europäische Küche zum Mittag-und Abendessen serviert. Live-Musik wird gespielt: mal hier.</p>\r\n<p>Das Hotel verfügt über einen Schönheitssalon, eine Sauna und Massageeinrichtungen. Ein privates Wäscheservice ist ebenfalls verfügbar.</p>\r\n<p>Ukraine Hotel liegt 10 Gehminuten vom Mariinski-Park und der Kathedrale St. Sofia. Sichere Parkplätze auf dem Gelände.</p>', 'Auf dem Platz der Unabhängigkeit im Herzen von Kiew bietet dieses Hotel klimatisierte Zimmer und Suiten mit eleganter Ausstattung. Es ist ein 3-Minuten-Spaziergang vom Maidan Nezalezhnosti und Kreschatik U-Bahnhöfe.'),
(34, 12, 'en', 'YMCA Three Arches Hotel', '26 King David Street, Jerusalem, 91002, Israel', '', '<p>In the heart of Jerusalem, the YMCA Three Arches Hotel probably has the best location in town. Opposite the famous King David Hotel, it is a 10-minute walk from the Old City.  Most attractions of the city can be explored easily by foot from the hotel. This unique, interesting and historical building was completed in 1933. It has beautiful public areas with arches and lush gardens.  The restaurant serves non-kosher meals throughout the day, and during the summer months guests can enjoy a meal or a drink on the beautiful terrace.  Rooms are clean and basic in design and all are non-smoking. They include cable TV, air condition, telephone and a bathtub or shower. Internet is available for a free throughout the hotel and parking is available free of charge on site.</p>', 'In the heart of Jerusalem, the YMCA Three Arches Hotel probably has the best location in town. Opposite the famous King David Hotel, it is a 10-minute walk from the Old City.\r\n'),
(35, 12, 'es', 'YMCA Tres Arches Hotel', '26 King David Street, Jerusalem, 91002, Israel', '', '<p>En el corazón de Jerusalén, el YMCA Three Arches Hotel tiene probablemente la mejor ubicación en la ciudad. Frente al famoso King David Hotel, está a 10 minutos a pie de la ciudad vieja.  La mayoría de los atractivos de la ciudad se pueden explorar fácilmente a pie desde el hotel. Este edificio singular, interesante e histórico se construyó en 1933. Presenta unas hermosas zonas comunes con arcos y exuberantes jardines.  El restaurante sirve comidas no kosher durante todo el día, y durante los meses de verano los huéspedes pueden disfrutar de una comida o una bebida en la terraza.  Las habitaciones son limpias y de diseño sencillo; son para no fumadores. Incluyen TV por cable, aire acondicionado, teléfono y bañera o ducha. Internet está disponible por un gratuito en todo el hotel y aparcamiento está disponible de forma gratuita en el sitio.</p>', 'Im Herzen von Jerusalem bietet das YMCA Three Arches Hotel wahrscheinlich die beste Lage in der Stadt. Gegenüber des berühmten King David Hotel, es ist ein 10-minütigen Spaziergang von der Altstadt entfernt.'),
(36, 12, 'de', 'YMCA Three Arches Hotel', '26 King David Street, Jerusalem, 91002, Israel', '', '<p>Im Herzen von Jerusalem bietet das YMCA Three Arches Hotel wahrscheinlich die beste Lage in der Stadt. Gegenüber des berühmten King David Hotel, es ist ein 10-minütigen Spaziergang von der Altstadt entfernt.  Die meisten Sehenswürdigkeiten der Stadt sind bequem zu Fuß vom Hotel aus erkundet werden. Diese einzigartige, interessante und historische Gebäude wurde im Jahr 1933 abgeschlossen Es hat schöne öffentliche Bereiche mit Bögen und üppige Gärten.  Das Restaurant bietet nicht-koschere Mahlzeiten über den Tag, und in den Sommermonaten können die Gäste eine Mahlzeit oder ein Getränk auf der schönen Terrasse genießen.  Die Zimmer sind sauber und schlicht gestaltet und alle sind Nichtraucherzimmer. Sie verfügen über Kabel-TV, Klimaanlage, Telefon und Badewanne oder Dusche. Internet ist im gesamten Hotel kostenlos zur Verfügung für ein und das Parken ist kostenfrei vor Ort zur Verfügung.</p>', 'En el corazón de Jerusalén, el YMCA Three Arches Hotel tiene probablemente la mejor ubicación en la ciudad. Frente al famoso King David Hotel, está a 10 minutos a pie de la ciudad vieja.'),
(37, 13, 'en', 'InterContinental NY T.Sq.', '302 West 44th Street, Midtown West, New York City, NY 10036, United States of America', '', '<p>Towering 36 stories above the city, the Intercontinental Times Square provides guests with front row seats to stunning views of New York’s impressive skyline and the Hudson River. It is in the Broadway Theater District. <br /><br /> Intercontinental New York Times Square features spacious rooms with a well-lit work desk and a sofa bed. Each unit includes a satellite flat-screen TV, coffeemaker and a minibar. The modern bathrooms have a hairdryer. <br /><br /> The hotel’s Marketplace provides meals on-the-go, including pastries, snacks and coffee. Ca Va Brasserie reflects New York City’s dynamic and international gourmet scene, serving seasonal French-inspired cuisine. The restaurant offers guests a variety of unique options, from the relaxing atmosphere of Ca Va''s Fireside lounge serving specialty cocktails, to the more formal and intimate main dining room where guests can enjoy breakfast, lunch, or dinner. <br /><br /> The Intercontinental provides a 24-hour gym for those wanting to maintain their work-out routine. Located on the third floor with views of 44th Street, it features Stairmasters, Lifecycles and treadmills. Free weights are also available. <br /><br /> This New York Intercontinental is a block from Times Square and less than a mile from Central Park. Port Authority Metro Station is just a 3-minute walk away.</p>', 'Towering 36 stories above the city, the Intercontinental Times Square provides guests with front row seats to stunning views of New York’s impressive skyline and the Hudson River. It is in the Broadway Theater District. '),
(38, 13, 'es', 'InterContinental NY T.Sq.', '302 West 44th Street, Midtown West, New York City, NY 10036, United States of America', '', '<p>Elevándose 36 pisos por encima de la ciudad, el Intercontinental Times Square ofrece a sus huéspedes con asientos de primera fila para unas vistas impresionantes de la impresionante ciudad de Nueva York y el río Hudson. Se encuentra en el distrito de los teatros de Broadway. <br /><br /> Intercontinental New York Times Square dispone de amplias habitaciones con un escritorio bien iluminado y un sofá cama. Cada unidad cuenta con TV de pantalla plana vía satélite, cafetera y minibar. Los modernos baños tienen secador de pelo. <br /><br /> El hotel ofrece comidas del mercado on-the-go, que incluye pastas, bocadillos y café. Ca Va Brasserie refleja escena gourmet dinámico e internacional de la ciudad de Nueva York, que sirve cocina de inspiración francesa de temporada. El restaurante ofrece a sus clientes una variedad de opciones únicas, de la atmósfera relajante de Fireside Lounge sirve cócteles especiales de Ca Va, para el comedor principal, más formal e íntimo donde los huéspedes pueden disfrutar del desayuno, el almuerzo o la cena. <br /><br /> El Intercontinental ofrece un gimnasio abierto las 24 horas para aquellos que quieran mantener su rutina de ejercicio. Ubicado en el tercer piso con vistas a la calle 44, que cuenta con escaladoras, bicicletas y cintas de correr. Las pesas libres están también disponibles. <br /><br /> Esta Nueva York Intercontinental es una calle de Times Square ya menos de un kilómetro y medio de Central Park. La estación de metro de la Autoridad Portuaria está a sólo 3 minutos a pie.</p>', 'Elevándose 36 pisos por encima de la ciudad, el Intercontinental Times Square ofrece a sus huéspedes con asientos de primera fila para unas vistas impresionantes de la impresionante ciudad de Nueva York y el río Hudson. Se encuentra en el distrito de los teatros de Broadway. '),
(39, 13, 'de', 'InterContinental NY T.Sq.', '302 West 44th Street, Midtown West, New York City, NY 10036, United States of America', '', '<p>Flammendes 36 Stockwerke über der Stadt, bietet das Intercontinental Times Square Gäste mit der ersten Reihe für einen atemberaubenden Blick auf New York die beeindruckende Skyline und den Hudson River. Es ist in der Broadway entfernt. <br /><br /> Intercontinental New York Times Square bietet geräumige Zimmer mit einem gut beleuchteten Schreibtisch und einem Schlafsofa. Jede Einheit verfügt über Sat-Flachbild-TV, eine Kaffeemaschine und eine Minibar. Die modernen Badezimmer verfügen über einen Haartrockner. <br /><br /> Im hoteleigenen Marktplatz bietet Mahlzeiten auf-the-go, mit Gebäck, Snacks und Kaffee. Ca Va Brasserie reflektiert New York Citys dynamische und internationale Gourmet-Szene, mit saisonalen Französisch inspirierte Küche. Das Restaurant bietet seinen Gästen eine Vielzahl von einzigartigen Optionen, von der entspannten Atmosphäre des Ca Va Fireside Lounge serviert Cocktails, zu der mehr formalen und intimen Speisesaal, wo die Gäste Frühstück, Mittagessen oder Abendessen. <br /><br /> Das Intercontinental verfügt über eine 24-Stunden-Fitnessraum für diejenigen, die ihre Arbeit-out-Routine aufrecht zu erhalten. Das Hotel liegt im dritten Stock mit Blick auf 44th Street, erwartet Sie mit Steppern, Lebenszyklen und Laufbänder. Freie Gewichte sind ebenfalls erhältlich. <br /><br /> Dieses New Yorker Intercontinental ist ein Block vom Times Square und weniger als eine Meile vom Central Park entfernt. Der U-Bahnhof Port Authority ist nur einen 3-minütigen Spaziergang entfernt.</p>', 'Flammendes 36 Stockwerke über der Stadt, bietet das Intercontinental Times Square Gäste mit der ersten Reihe für einen atemberaubenden Blick auf New York die beeindruckende Skyline und den Hudson River. Es ist in der Broadway entfernt. '),
(40, 14, 'en', 'Villa Bella Vista', 'Paseo 114 N° 356, 7165 Villa Gesell, Argentina', '', '<p>Offering an outdoor swimming pool and a buffet restaurant, Hotel Bella Vista is located in Villa Gesell, 100 metres from the beach Free Wi-Fi access is available and Villa Gesell Natural Reserve is 50 metres away. <br /><br /> Rooms here will provide you with a TV and cable channels. Featuring a shower, private bathrooms also come with towels. You can enjoy a garden view from all the rooms. Extras include a fan. <br /><br /> At Hotel Bella Vista you will find a 24-hour front desk, a garden and BBQ facilities. Other facilities offered include a games room, luggage storage and a children''s playground. <br /><br /> Santa Teresita Airport is 84 km away. The property offers free parking.</p>', 'Offering an outdoor swimming pool and a buffet restaurant, Hotel Bella Vista is located in Villa Gesell, 100 metres from the beach Free Wi-Fi access is available and Villa Gesell Natural Reserve is 50 metres away. '),
(41, 14, 'es', 'Villa Bella Vista', 'Paseo 114 N° 356, 7165 Villa Gesell, Argentina', '', '<p>Ofrece una piscina al aire libre y un restaurante bufé, Hotel Bella Vista se encuentra en Villa Gesell, está disponible a 100 metros de la playa de conexión Wi-Fi gratuita y Villa Gesell Reserva Natural está a 50 metros de distancia. <br /><br /> Las habitaciones le proporcionará con TV y canales por cable. Con ducha, baño privado también vienen con toallas. Usted puede disfrutar de una vista al jardín desde todas las habitaciones. Los extras incluyen un ventilador. <br /><br /> En el Hotel Bella Vista se encuentra una recepción abierta las 24 horas, un jardín y una zona de barbacoa. Otras instalaciones ofrecidas incluyen una sala de juegos, sala de equipajes y un parque infantil. <br /><br /> Aeropuerto de Santa Teresita se encuentra a 84 km. El establecimiento ofrece aparcamiento gratuito.</p>', 'Ofrece una piscina al aire libre y un restaurante bufé, Hotel Bella Vista se encuentra en Villa Gesell, está disponible a 100 metros de la playa de conexión Wi-Fi gratuita y Villa Gesell Reserva Natural está a 50 metros de distancia. '),
(42, 14, 'de', 'Villa Bella Vista', 'Paseo 114 N° 356, 7165 Villa Gesell, Argentina', '', '<p>Mit einem Außenpool und ein Buffet-Restaurant, das Hotel Bella Vista in Villa Gesell, liegt nur 100 Meter vom Strand entfernt kostenloses WLAN zur Verfügung und Villa Gesell Naturschutzgebiet ist 50 Meter entfernt. <br /><br /> Die Zimmer werden Sie mit einem TV und Kabel-TV bieten. Mit Dusche, Bad auch mit Handtüchern zu kommen. Sie können einen Blick auf den Garten von allen Zimmern genießen. Extras gehören ein Ventilator. <br /><br /> Im Hotel Bella Vista finden Sie eine 24-Stunden-Rezeption, einen Garten und einen Grillplatz finden. Zu den weiteren Einrichtungen gehören ein Spielzimmer, eine Gepäckaufbewahrung und ein Kinderspielplatz. <br /><br /> Santa Teresita Airport ist 84 km entfernt. Das Hotel bietet kostenlose Parkplätze.</p>', 'Mit einem Außenpool und ein Buffet-Restaurant, das Hotel Bella Vista in Villa Gesell, liegt nur 100 Meter vom Strand entfernt kostenloses WLAN zur Verfügung und Villa Gesell Naturschutzgebiet ist 50 Meter entfernt.');
INSERT INTO `uhb289_hotels_description` (`id`, `hotel_id`, `language_id`, `name`, `address`, `name_center_point`, `description`, `preferences`) VALUES
(43, 15, 'en', 'Islanda Privacy', '158/9 Phangmueng Sai Kor rd. Patong, Kathu, Phuket, 83150 Patong Beach, Thailand', '', '<p>Located in Patong Beach, Islanda Privacy offers a la carte restaurant. Free Wi-Fi access is available for guests to use. <br /><br /> Rooms at this hotel are air conditioned and provide a flat-screen TV, a balcony, and a refrigerator. The private bathroom features a shower, a hair dryer and free toiletries. <br /><br /> Islanda Privacy has a 24-hour front desk, a shared lounge and offers a tour desk. Laundry and daily maid service is available. The property has free private parking. <br /><br /> The hotel is 1.1 km from Patong''s nightlife area, Bangla Road. Jungceylon Shopping Centre is 800 metres away and Phuket International Airport is 25 km away.</p>', 'Located in Patong Beach, Islanda Privacy offers a la carte restaurant. Free Wi-Fi access is available for guests to use. \r\n'),
(44, 15, 'es', 'Islanda Privacy', '158/9 Phangmueng Sai Kor rd. Patong, Kathu, Phuket, 83150 Patong Beach, Thailand', '', '<p>Situado en la playa de Patong, Islanda Privacidad cuenta con un restaurante a la carta. Hay conexión Wi-Fi gratuita disponible para los huéspedes. <br /><br /> Las habitaciones de este hotel disponen de aire acondicionado y disponen de TV de pantalla plana, balcón y nevera. El baño privado cuenta con ducha, secador de pelo y artículos de aseo gratuitos. <br /><br /> Islanda Privacidad tiene una recepción abierta las 24 horas, un salón común y ofrece un mostrador de información turística. Servicio de lavandería y servicio de limpieza diario está disponible. El establecimiento dispone de aparcamiento privado gratuito. <br /><br /> El hotel está a 1,1 km de la zona de ocio nocturno de Patong, Bangla Road. Centro comercial Jungceylon se encuentra a 800 metros de distancia y el aeropuerto internacional de Phuket se encuentra a 25 km.</p>', 'Situado en la playa de Patong, Islanda Privacidad cuenta con un restaurante a la carta. Hay conexión Wi-Fi gratuita disponible para los huéspedes.\r\n<br><br>\r\nLas habitaciones de este hotel disponen de aire acondicionado y disponen de TV de pantalla plana, balcón y nevera. El baño privado cuenta con ducha, secador de pelo y artículos de aseo gratuitos.\r\n'),
(45, 15, 'de', 'Islanda Privacy', '158/9 Phangmueng Sai Kor rd. Patong, Kathu, Phuket, 83150 Patong Beach, Thailand', '', '<p>Das Hotel liegt in Patong Beach, Islanda Privatsphäre bietet A-la-carte-Restaurant. Kostenloser WLAN-Zugang ist für die Gäste zu bedienen. <br /><br /> Die Zimmer in diesem Hotel sind klimatisiert und verfügen über einen Flachbild -TV, einen Balkon und einen Kühlschrank. Das private Badezimmer verfügt über eine Dusche, einen Haartrockner und kostenlose Pflegeprodukte. <br /><br /> Islanda Datenschutz verfügt über eine 24-Stunden-Rezeption, einen Gemeinschaftsraum und bietet einen Tourenschalter. Wäsche- und Zimmerservice zur Verfügung. Das Anwesen verfügt über einen kostenfreien Parkplatz. <br /><br /> Das Hotel befindet sich 1,1 km vom Nachtleben von Patong, Bangla Road. Einkaufszentrum Jungceylon entfernt liegt 800 Meter entfernt und der internationale Flughafen Phuket ist 25 km entfernt.</p>', 'Das Hotel liegt in Patong Beach, Islanda Privatsphäre bietet A-la-carte-Restaurant. Kostenloser WLAN-Zugang ist für die Gäste zu bedienen. \r\n'),
(46, 16, 'en', 'FlamY Hotel & Casino', '2545 Las Vegas Boulevar, Las Vegas', '', '<p>This resort on the Las Vegas Strip features a Caribbean-style pool and wildlife habitat. It features a spa, 77,000-square foot casino and Margaritaville restaurant, along with spacious rooms.  Flamingo Las Vegas Hotel &amp; Casino features a state-of-the-art gym. The outdoor pool includes waterfalls, a water slide and adults-only area. The casino has slots and table games.  Every spacious room at the Flamingo Hotel is furnished with a desk, sitting area and entertainment center with cable TV. Each room also includes a safe.  Guests at Flamingo Hotel &amp; Casino can choose from authentic Japanese dishes at Hamada of Japan or fine steaks and seafood at the classic Steakhouse 46. Hand-crafted beers and gourmet coffee are also available.  McCarran International Airport is 3 miles from the Flamingo Casino. Guests are steps from the Las Vegas Monorail that provides transportation services to local area entertainment.</p>', 'This resort on the Las Vegas Strip features a Caribbean-style pool and wildlife habitat. It features a spa, 77,000-square foot casino and Margaritaville restaurant, along with spacious rooms.\r\n'),
(47, 16, 'es', 'FlamY Hotel & Casino', '2545 Las Vegas Boulevar, Las Vegas', '', '<p>Este complejo situado en el Strip de Las Vegas cuenta con una piscina de estilo caribeño y el hábitat de la fauna. Cuenta con un spa, un casino de 77.000 m² y un restaurante Margaritaville, junto con amplias habitaciones. Flamingo Las Vegas Hotel &amp; amp; Casino cuenta con un gimnasio de última generación. La piscina al aire libre incluye cascadas, un tobogán de agua y solo para adultos del área. El casino cuenta con máquinas tragamonedas y juegos de mesa. Las amplias habitaciones del Hotel Flamingo cuentan con un escritorio, zona y centro de entretenimiento de estar con TV por cable. También incluyen una caja fuerte. Los huéspedes del Flamingo Hotel &amp; amp; Casino pueden elegir entre platos japoneses auténticos en Hamada of Japan o deleitarse con los filetes y mariscos en los clásicos Churrasquería 46. de cervezas artesanales y café gourmet también están disponibles. El aeropuerto internacional McCarran está a 3 km del Casino Flamingo. Los huéspedes son pasos del monorraíl de Las Vegas que ofrece servicios de transporte a la zona de entretenimiento local. <!-- P--></p>', 'Este complejo situado en el Strip de Las Vegas cuenta con una piscina de estilo caribeño y el hábitat de la fauna. Cuenta con un spa, un casino de 77.000 m² y un restaurante Margaritaville, junto con amplias habitaciones.'),
(48, 16, 'de', 'FlamY Hotel & Casino', '2545 Las Vegas Boulevar, Las Vegas', '', '<p>Dieses Resort am Las Vegas Strip verfügt über einen Pool in karibischem Stil sowie einem Naturpark. Es verfügt über einen Wellnessbereich, 77.000 m² großen Casino und Margaritaville Restaurant und geräumige Zimmer. Flamingo Las Vegas Hotel &amp; amp; Casino verfügt über eine state-of-the-art Fitnessraum. Der Außenpool mit Wasserfällen, eine Wasserrutsche und Bereiche nur für Erwachsene. Das Casino hat Slots und Tischspiele. Jedes der geräumigen Zimmer im Flamingo Hotel ist mit einem Schreibtisch ausgestattet, Sitzecke und Entertainment-Center mit Kabel-TV. Jedes Zimmer verfügt zudem über einen Safe. Als Gäste im Flamingo Hotel &amp; amp; Casino kann von authentische japanische Gerichte im Hamada of Japan oder feine Steaks und Meeresfrüchte im klassischen Steakhouse 46. auf hausgemachte Biere und Gourmet-Kaffee zu wählen sind ebenfalls erhältlich. McCarran International Airport ist 3 Meilen vom Flamingo Casino. Nur wenige Schritte von der Las Vegas Monorail, die Transportdienstleistungen für regionaler Unterhaltung. <!-- P--></p>', 'Dieses Resort am Las Vegas Strip bietet einen Pool in karibischem Stil sowie einem Naturpark. Es verfügt über einen Wellnessbereich, 77.000 m² großen Casino und Margaritaville Restaurant und geräumige Zimmer.'),
(49, 17, 'en', 'Bandara Suites Silom', '75/3 Saladaeng Road, Silom, Bangrak, Bang Rak, 10500 Bangkok, Thailand', '', '<p>In Silom District, Bandara Suites offers rooms and suites with a flat-screen TV and free Wi-Fi. It features 2 dining options, 2 swimming pools and a spa. Free Wi-Fi is available throughout. In one of Bangkok City’s shopping, dining and entertainment districts, Bandara Suites is a 10-minute walk from the Silom MRT Station. <br /><br /> Each room and suite at the Bandara Bangkok has a minibar, tea/coffee maker and electronic safe. Attached bathrooms include a shower and bathtub. Suites include a full kitchen. Guests enjoy a welcome drink upon arrival. Recreation facilities include a fitness center, an indoor hot tub, and sauna rooms. Free parking is available. <br /><br /> Janpanese cuisine and saké is served at Touka Restaurant where there is an open kitchen. The restaurant is open from 5 pm-11 pm. Bang Rak is a great choice for travelers interested in Temples, Culture and Sightseeing.</p>', 'In Silom District, Bandara Suites offers rooms and suites with a flat-screen TV and free Wi-Fi. It features 2 dining options, 2 swimming pools and a spa. Free Wi-Fi is available throughout. In one of Bangkok City’s shopping, dining and entertainment districts, Bandara Suites is a 10-minute walk from the Silom MRT Station. \r\n'),
(50, 17, 'es', 'Bandara Suites Silom', '75/3 Saladaeng Road, Silom, Bangrak, Bang Rak, 10500 Bangkok, Thailand', '', '<p>En el barrio de Silom, Bandara Suites ofrece habitaciones y suites con TV de pantalla plana y conexión Wi-Fi gratuita. Cuenta con 2 restaurantes, 2 piscinas y un spa. Hay conexión Wi-Fi gratuita en todo. En una de las tiendas, restaurantes y entretenimiento distritos de la ciudad de Bangkok, Bandara Suites se encuentra a 10 minutos a pie de la estación de MRT de Silom. <br /><br /> Todas las habitaciones y suites del Bandara Bangkok tiene un mini bar, cafetera / tetera y caja fuerte electrónica. Los baños anexos incluyen una ducha y bañera. Las suites cuentan con una cocina completa. Los huéspedes disfrutan de una copa de bienvenida a su llegada. Las instalaciones recreativas incluyen un gimnasio, un jacuzzi interior y sauna. Hay aparcamiento gratuito disponible. <br /><br /> Cocina japonesa y sake se sirve al Touka restaurante donde hay una cocina abierta. El restaurante está abierto de 17:00-23:00. Bang Rak es una gran opción para los viajeros interesados en los templos, Cultura y Turismo.</p>', 'En el barrio de Silom, Bandara Suites ofrece habitaciones y suites con TV de pantalla plana y conexión Wi-Fi gratuita. Cuenta con 2 restaurantes, 2 piscinas y un spa. Hay conexión Wi-Fi gratuita en todo. En una de las tiendas, restaurantes y entretenimiento distritos de la ciudad de Bangkok, Bandara Suites se encuentra a 10 minutos a pie de la estación de MRT de Silom.'),
(51, 17, 'de', 'Bandara Suites Silom', '75/3 Saladaeng Road, Silom, Bangrak, Bang Rak, 10500 Bangkok, Thailand', '', '<p>Im Stadtteil Silom bietet das Bandara Suites Zimmer und Suiten mit einem Flachbild-TV und kostenfreiem WLAN. Es verfügt über 2 Restaurants, 2 Pools und einen Wellnessbereich. Kostenloses W-LAN im gesamten Hotel. In einem der Geschäfte, Restaurants und Unterhaltungsviertel Bangkoks Stadtteil ist Bandara Suites nur 10 Gehminuten vom MRT-Bahnhof Silom. <br /><br /> Alle Zimmer und Suiten im Bandara Bangkok hat eine Minibar, Tee- / Kaffeekocher und einen elektronischen Safe. Die angrenzenden Badezimmer verfügen über eine Dusche und eine Badewanne. Die Suiten verfügen über eine voll ausgestattete Küche. Freuen Sie sich auf ein Begrüßungsgetränk bei der Ankunft. Freizeiteinrichtungen gehören ein Fitnesscenter, einen Innenwhirlpool und Sauna. Kostenlose Parkplätze stehen zur Verfügung. <br /><br /> Japanische Küche und Sake am Touka Restaurant serviert, wo es eine offene Küche. Das Restaurant ist täglich von 17.00 Uhr bis 23.00 Uhr. Bang Rak ist eine gute Wahl für Reisende mit Interesse an Tempel, Kultur und Sightseeing.</p>', 'Im Stadtteil Silom bietet das Bandara Suites Zimmer und Suiten mit einem Flachbild-TV und kostenfreiem WLAN. Es verfügt über 2 Restaurants, 2 Pools und einen Wellnessbereich. Kostenloses W-LAN im gesamten Hotel. In einem der Geschäfte, Restaurants und Unterhaltungsviertel Bangkoks Stadtteil ist Bandara Suites nur 10 Gehminuten vom MRT-Bahnhof Silom. \r\n'),
(52, 1, 'ar', 'Rotem King Villa', 'st. Garon st., 210\r\nRonston 213456', '', '<p>Step into a world of ease, luxury and Swiss hospitality at The Stamford, our 5-star deluxe hotel. Located in the heart of the city amidst world-class shopping, entertainment and the CBD. The hotel is seated at Turn 9 of the F1 race and 20 minutes away from the Airport.</p>', ''),
(53, 2, 'ar', 'Wyndham Boston Hill', '5 Blossom Street, Boston, MA 02114', '', '<p>The Museum of Science and TD Bank Garden are a short distance from this downtown Boston hotel which features completely non-smoking rooms, an on-site restaurant and many modern amenities. Thoughtful amenities at the Wyndham Boston Beacon Hill include a 24-hour fitness center, a seasonal outdoor swimming pool and modern business facilities. Guests can also enjoy on-site dining at Dean''s List restaurant, which serves small plates and has an extensive drink menu.</p>\r\n<p>The Boston Wyndham Beacon Hill is near the famed Faneuil Hall and Quincy Market. Boston Common, the Hynes Convention Center and the Boston Public Gardens are also close to the hotel.</p>', 'Here you may found our hotel preferences.'),
(54, 3, 'ar', 'Park Lany Hotel', '37 Central Park South, New York City, NY 10019', '', '<p>The Park Lany Hotel is a deluxe hotel with a European atmosphere, providing views of Central Park and the New York skyline. It is only a 2-minute walk from the elegant shops of 5th Avenue and the 59th Street N,Q,R subway station. Spacious and bright, the rooms at the Park Lany Hotel are fitted with oversized windows and fine sheets. Amenities include flat-screen TVs and access to the on-site fitness center.</p>\r\n<p> </p>\r\n<p>Enjoy a seasonal menu created by Jeff Cristelli at The Park Room Restaurant, or select from a wide variety of cocktails at Harry''s New York Bar. New York’s Museum of Modern Art, Radio City Music Hall, and Rockefeller Center, are all within a 10-minute walk. With the park right in front of the hotel, jogging and recreational activities are easily accessible.</p>', 'If in your dream you see a big hotel with good furniture, ahead you will have the life full of pleasure. Stay in shabby dirty hotel with the sick owner dreams to failure or receiving a sad vital lesson.'),
(55, 4, 'ar', 'Pulman Paris Tour Eiffel', '18 Avenue De Suffren, Entrée au 21 rue Jean Rey, 15th arr. - Porte de Versailles, 75015 Paris', '', '<p>The 4-star hotel Pullman Paris Tour Eiffel is set at the foot of the Eiffel Tower and the Trocadero. The fitness room with cardio equipment, open 24 hours a day, offers unrestricted views of the Trocadero, and you can enjoy dining on the terrace at the restaurant, Frame in this place.</p>\r\n<p>Decorated in contemporary style, the bright guest rooms offer panoramic views of Paris. They includes a flat-screen TV with free access to the latest movies, an iPod dock and free Wi-Fi access. Most of the rooms have a balcony, and some also have a stunning view of the Eiffel Tower or the garden.</p>\r\n<p>The hotel''s restaurant serves Californian-style cuisine with French flavors. It has an open-plan kitchen and a stylish wine bar. A connectivity lounge featuring computers, tablets and printers is also available in the hotel.</p>\r\n<p>Pullman Paris is on the Left Bank, just a 5-minute walk from the Eiffel Tower. It is in a great location, less than half a mile from the Bir-Hakeim Metro Station (line 6), providing direct access to the Arc de Triomphe, Champs Élysées and Louvre Museum. Private parking is available on site.</p>', 'Pullman Paris is on the Left Bank, just a 5-minute walk from the Eiffel Tower. It is in a great location, less than half a mile from the Bir-Hakeim Metro Station (line 6), providing direct access to the Arc de Triomphe'),
(56, 5, 'ar', 'H9 Metropolitan', 'Rambla Catalunya, 7-11, L''Eixample, 08007 Barcelona', '', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi.</p>\r\n<p>Each room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom comes with a hairdryer and bathrobes.</p>\r\n<p>The H9 Metropolitan is located just 2 minutes'' walk from Paseo de Gracia Avenue, with its boutique and designer fashion stores.</p>\r\n<p>The hotel is 700 metres from Gaudi''s La Pedrera, and you can walk to Las Ramblas in 3 minutes. You can reach La Sagrada Familia in about 10 minutes by metro.</p>', 'Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi.\r\n'),
(57, 6, 'ar', 'Izmailovo Alpha Hotel', 'Izmailovskoye Shosse 71A, Izmailovo, 105613 Moscow, Russia', '', '<p>Part of the vast Izmailovo Hotel Complex, built for the 1980 Olympic Games, the Izmailovo Alfa is a little more expensive than its sister properties, a policy it justifies with its extensive conferencing facilities and the high standards of top room categories. Located in the north-east of Moscow, the hotel offers very fast access to the downtown by metro. <br /><br /> The hotel’s 945 rooms range from low-cost options very basic furniture and fittings to really quite luxurious rooms on the Izmailovo Alfa’s Club Floor. All rooms are covered by complimentary WiFi access. The hotel also has a modern business center with large and flexible conference halls. Equally suitable for business travelers and tourists, the Izmailovo Alfa Hotel also has a wide range of concierge services, and several bars and restaurants on site. Other services, including fitness centre, are available nearby in other parts of the Izmailovo Hotel Complex. While you should not expect particularly friendly or attentive service at the Izmailovo Alfa, staff are efficient and mostly speak good English.</p>', ''),
(58, 7, 'ar', 'Hilton Tel Aviv Hotel ', 'Independence Park, Tel Aviv, 63405, Israel', '', '<p>Set within Independence Park and providing direct access to Hilton Beach and Tel Aviv promenade, the Hilton Tel Aviv features a large outdoor salt water pool, 5 kosher restaurants and a spa. <br /> <br /> Its spacious air-conditioned rooms include a flat-screen TV and a private balcony with a sea view. The luxurious marble bathroom includes Ahava amenities and a lavish bathrobe. <br /><br /> The Tel Aviv Hilton’s spa and health club features a well-equipped fitness room and various treatments and massages. You can also relax and enjoy the sea views from the terrace with lounge chairs and umbrellas. <br /><br /> The Hilton Tel Aviv Hotel also has a 24-hour lobby restaurant, a synagogue and a hair &amp; beauty salon. Hayarkon Park, which has botanical gardens and sports facilities, is just a 10-minute walk away. Ben Gurion Airport is a 25-minute drive away. <br /><br /> Guests can choose from a range of kosher dining options, from breakfast in Café Med, to a relaxed lunch in Yakimono Sushi Bar or an evening meal in the King Solomon Restaurant.</p>', 'Set within Independence Park and providing direct access to Hilton Beach and Tel Aviv promenade, the Hilton Tel Aviv features a large outdoor salt water pool, 5 kosher restaurants and a spa. '),
(59, 8, 'ar', 'Leonardo Hotel Vienna', 'Matosengasse 6-9, 06. Marihilf, 1060 Vienna, Austria', '', '<p>Opened in July 2012, this non-smoking 4-star hotel is just 100 yards from the Mariahilfer Straße shopping street and a quarter mile from the Westbahnhof transportation hub. Central Vienna can be reached by subway in 5 minutes. <br /><br /> The modern, air-conditioned rooms at Leonardo Hotel Vienna feature a flat-screen TV, a minibar, a tea/coffee maker, and a bathroom with a hairdryer and a make-up mirror. <br /><br /> The restaurant Vitruv serves Austrian and international cuisine. Guests of the Vienna Leonardo Hotel have a business center and a 24-hour front desk. <br /><br /> The entrance to the Westbahnhof subway station is only 220 yards away. The Technical Museum and the Haus des Meeres Aquarium are both one mile away.</p>', 'Opened in July 2012, this non-smoking 4-star hotel is just 100 yards from the Mariahilfer Straße shopping street and a quarter mile from the Westbahnhof transportation hub. Central Vienna can be reached by subway in 5 minutes. \r\n'),
(60, 9, 'ar', 'Exe Puerta Castilla', 'Paseo de la Castellana, 187, Tetuán, 22046 Madrid, Spain', '', '<p>Just 2 Metro Stops from Real Madrid''s Santiago Bernabéu Stadium, this hotel is located next to the Kio Towers on Paseo de la Castellana. It features free Wi-Fi, a spa and a free gym. <br /><br /> The bright, air-conditioned rooms at the Exe Puerta Castilla have flat-screen satellite TVs. There are ironing facilities and a suit press. The private bathrooms have a hairdryer and exclusive amenities. Room service is available. <br /><br /> The hotel spa includes a Turkish bath, sauna and hot tub. It is available for an additional fee. <br /><br /> The Puerta Castilla is next to Plaza de Castilla Metro Station. On-site parking is available for an extra fee, and car rental is available at the tour desk. The hotel has a 24-hour front desk.</p>', 'Just 2 Metro Stops from Real Madrid''s Santiago Bernabéu Stadium, this hotel is located next to the Kio Towers on Paseo de la Castellana. It features free Wi-Fi, a spa and a free gym.'),
(61, 10, 'ar', 'Hotel Turia', 'Profesor Betran Baguena, 2, 47009 Valencia, Spain', '', '<p>Hotel Turia is next to Valencia Bus Station, and just under a quarter of a mile from Turia Metro Station. Set across the Turia Park from the Botanical Gardens, it is a 20-minute walk from the cathedral. <br /><br /> All air-conditioned rooms at the Turia Hotel have a TV and most feature a private balcony. There is a safe, and the private bathroom includes a hairdryer. <br /><br /> Nuevo Centro Shopping Center and El Corte Inglés Department Store are across from the hotel. Excellent public transportation makes it easy to reach City of Arts and Sciences, airport and Convention Centre. <br /><br /> The Turia has a bar, and guests can relax on the hotel terrace. <br /><br /> Free Wi-Fi is available throughout. Car rental is provided, and there is also on-site parking available. The hotel has a tour desk and a 24-hour front desk.</p>', 'Hotel Turia is next to Valencia Bus Station, and just under a quarter of a mile from Turia Metro Station. Set across the Turia Park from the Botanical Gardens, it is a 20-minute walk from the cathedral.\r\n\r\nAll air-conditioned rooms at the Turia Hotel have a TV and most feature a private balcony. There is a safe, and the private bathroom includes a hairdryer.'),
(62, 11, 'ar', 'Ukraine Hotel', 'Institutskaya Street 4, Kiev, 01001, Ukraine', '', '<p>On Independence Square in the heart of Kiev, this hotel offers air conditioned rooms and suites with elegant décor. It is a 3-minute walk from the Maidan Nezalezhnosti and Kreschatik Metro Stations.</p>\r\n<p>In-room facilities at the Ukraine Hotel include satellite TV and a refrigerator. Your bathroom includes free toiletries and perfumes. Guests enjoy views of the Kreschatyk Street and the surrounding area.</p>\r\n<p>A large breakfast buffet is available at the Ukraine Hotel, and 24-hour room service is offered. Ukrainian and European cuisine is served for lunch and dinner. Live music is sometimes played here.</p>\r\n<p>The hotel features a beauty salon, sauna and massage facilities. A private laundry service is also available.</p>\r\n<p>Hotel Ukraine is a 10-minute walk from Mariyinsky Park and the St. Sofia Cathedral. Secure parking is available on site.</p>', 'On Independence Square in the heart of Kiev, this hotel offers air conditioned rooms and suites with elegant décor. It is a 3-minute walk from the Maidan Nezalezhnosti and Kreschatik Metro Stations.'),
(63, 12, 'ar', 'YMCA Three Arches Hotel', '26 King David Street, Jerusalem, 91002, Israel', '', '<p>In the heart of Jerusalem, the YMCA Three Arches Hotel probably has the best location in town. Opposite the famous King David Hotel, it is a 10-minute walk from the Old City.  Most attractions of the city can be explored easily by foot from the hotel. This unique, interesting and historical building was completed in 1933. It has beautiful public areas with arches and lush gardens.  The restaurant serves non-kosher meals throughout the day, and during the summer months guests can enjoy a meal or a drink on the beautiful terrace.  Rooms are clean and basic in design and all are non-smoking. They include cable TV, air condition, telephone and a bathtub or shower. Internet is available for a free throughout the hotel and parking is available free of charge on site.</p>', 'In the heart of Jerusalem, the YMCA Three Arches Hotel probably has the best location in town. Opposite the famous King David Hotel, it is a 10-minute walk from the Old City.\r\n'),
(64, 13, 'ar', 'InterContinental NY T.Sq.', '302 West 44th Street, Midtown West, New York City, NY 10036, United States of America', '', '<p>Towering 36 stories above the city, the Intercontinental Times Square provides guests with front row seats to stunning views of New York’s impressive skyline and the Hudson River. It is in the Broadway Theater District. <br /><br /> Intercontinental New York Times Square features spacious rooms with a well-lit work desk and a sofa bed. Each unit includes a satellite flat-screen TV, coffeemaker and a minibar. The modern bathrooms have a hairdryer. <br /><br /> The hotel’s Marketplace provides meals on-the-go, including pastries, snacks and coffee. Ca Va Brasserie reflects New York City’s dynamic and international gourmet scene, serving seasonal French-inspired cuisine. The restaurant offers guests a variety of unique options, from the relaxing atmosphere of Ca Va''s Fireside lounge serving specialty cocktails, to the more formal and intimate main dining room where guests can enjoy breakfast, lunch, or dinner. <br /><br /> The Intercontinental provides a 24-hour gym for those wanting to maintain their work-out routine. Located on the third floor with views of 44th Street, it features Stairmasters, Lifecycles and treadmills. Free weights are also available. <br /><br /> This New York Intercontinental is a block from Times Square and less than a mile from Central Park. Port Authority Metro Station is just a 3-minute walk away.</p>', 'Towering 36 stories above the city, the Intercontinental Times Square provides guests with front row seats to stunning views of New York’s impressive skyline and the Hudson River. It is in the Broadway Theater District. '),
(65, 14, 'ar', 'Villa Bella Vista', 'Paseo 114 N° 356, 7165 Villa Gesell, Argentina', '', '<p>Offering an outdoor swimming pool and a buffet restaurant, Hotel Bella Vista is located in Villa Gesell, 100 metres from the beach Free Wi-Fi access is available and Villa Gesell Natural Reserve is 50 metres away. <br /><br /> Rooms here will provide you with a TV and cable channels. Featuring a shower, private bathrooms also come with towels. You can enjoy a garden view from all the rooms. Extras include a fan. <br /><br /> At Hotel Bella Vista you will find a 24-hour front desk, a garden and BBQ facilities. Other facilities offered include a games room, luggage storage and a children''s playground. <br /><br /> Santa Teresita Airport is 84 km away. The property offers free parking.</p>', 'Offering an outdoor swimming pool and a buffet restaurant, Hotel Bella Vista is located in Villa Gesell, 100 metres from the beach Free Wi-Fi access is available and Villa Gesell Natural Reserve is 50 metres away. '),
(66, 15, 'ar', 'Islanda Privacy', '158/9 Phangmueng Sai Kor rd. Patong, Kathu, Phuket, 83150 Patong Beach, Thailand', '', '<p>Located in Patong Beach, Islanda Privacy offers a la carte restaurant. Free Wi-Fi access is available for guests to use. <br /><br /> Rooms at this hotel are air conditioned and provide a flat-screen TV, a balcony, and a refrigerator. The private bathroom features a shower, a hair dryer and free toiletries. <br /><br /> Islanda Privacy has a 24-hour front desk, a shared lounge and offers a tour desk. Laundry and daily maid service is available. The property has free private parking. <br /><br /> The hotel is 1.1 km from Patong''s nightlife area, Bangla Road. Jungceylon Shopping Centre is 800 metres away and Phuket International Airport is 25 km away.</p>', 'Located in Patong Beach, Islanda Privacy offers a la carte restaurant. Free Wi-Fi access is available for guests to use. \r\n'),
(67, 16, 'ar', 'FlamY Hotel & Casino', '2545 Las Vegas Boulevar, Las Vegas', '', '<p>This resort on the Las Vegas Strip features a Caribbean-style pool and wildlife habitat. It features a spa, 77,000-square foot casino and Margaritaville restaurant, along with spacious rooms.  Flamingo Las Vegas Hotel &amp; Casino features a state-of-the-art gym. The outdoor pool includes waterfalls, a water slide and adults-only area. The casino has slots and table games.  Every spacious room at the Flamingo Hotel is furnished with a desk, sitting area and entertainment center with cable TV. Each room also includes a safe.  Guests at Flamingo Hotel &amp; Casino can choose from authentic Japanese dishes at Hamada of Japan or fine steaks and seafood at the classic Steakhouse 46. Hand-crafted beers and gourmet coffee are also available.  McCarran International Airport is 3 miles from the Flamingo Casino. Guests are steps from the Las Vegas Monorail that provides transportation services to local area entertainment.</p>', 'This resort on the Las Vegas Strip features a Caribbean-style pool and wildlife habitat. It features a spa, 77,000-square foot casino and Margaritaville restaurant, along with spacious rooms.\r\n'),
(68, 17, 'ar', 'Bandara Suites Silom', '75/3 Saladaeng Road, Silom, Bangrak, Bang Rak, 10500 Bangkok, Thailand', '', '<p>In Silom District, Bandara Suites offers rooms and suites with a flat-screen TV and free Wi-Fi. It features 2 dining options, 2 swimming pools and a spa. Free Wi-Fi is available throughout. In one of Bangkok City’s shopping, dining and entertainment districts, Bandara Suites is a 10-minute walk from the Silom MRT Station. <br /><br /> Each room and suite at the Bandara Bangkok has a minibar, tea/coffee maker and electronic safe. Attached bathrooms include a shower and bathtub. Suites include a full kitchen. Guests enjoy a welcome drink upon arrival. Recreation facilities include a fitness center, an indoor hot tub, and sauna rooms. Free parking is available. <br /><br /> Janpanese cuisine and saké is served at Touka Restaurant where there is an open kitchen. The restaurant is open from 5 pm-11 pm. Bang Rak is a great choice for travelers interested in Temples, Culture and Sightseeing.</p>', 'In Silom District, Bandara Suites offers rooms and suites with a flat-screen TV and free Wi-Fi. It features 2 dining options, 2 swimming pools and a spa. Free Wi-Fi is available throughout. In one of Bangkok City’s shopping, dining and entertainment districts, Bandara Suites is a 10-minute walk from the Silom MRT Station. \r\n'),
(69, 18, 'en', 'Family Apartments', '', '12th Street Beach (Miami Beach), Miami, FL 33139', '<p>12th Street Beach is located at 1200 S. Linn White Drive (12th Street at Lake Michigan on Northerly Island) and is nestled just south of Adler Planetarium on Chicago’s Museum Campus in Burnham Park.  Beach goers can enjoy food and beverages from Del Campos - offering a Mexican menu along with hot dogs. The beach house offers restrooms.  There is a non-motorized boat launch available at the beach and distance swimming is located parallel to shore at boat line.  Paid parking lot along with limited street parking is available. This beach has an accessible beach walk.</p>\r\n<p> </p>\r\n<p>Distance swimming is available parallel to shore at boat line. 12th Street Beach dates to the 1920s. In 1909, renowned architect Daniel Burnham envisioned a new park composed of several man-made islands between Jackson Park and Grant Park. Northerly Island was the only island that was actually built.</p>', ''),
(70, 18, 'ee', 'Family Apartments', '', '12th Street Beach (Miami Beach), Miami, FL 33139', '<p>12th Street Beach is located at 1200 S. Linn White Drive (12th Street at Lake Michigan on Northerly Island) and is nestled just south of Adler Planetarium on Chicago’s Museum Campus in Burnham Park.  Beach goers can enjoy food and beverages from Del Campos - offering a Mexican menu along with hot dogs. The beach house offers restrooms.  There is a non-motorized boat launch available at the beach and distance swimming is located parallel to shore at boat line.  Paid parking lot along with limited street parking is available. This beach has an accessible beach walk.</p>\r\n<p> </p>\r\n<p>Distance swimming is available parallel to shore at boat line. 12th Street Beach dates to the 1920s. In 1909, renowned architect Daniel Burnham envisioned a new park composed of several man-made islands between Jackson Park and Grant Park. Northerly Island was the only island that was actually built.</p>', ''),
(71, 18, 'de', 'Family Apartments', '', '12th Street Beach (Miami Beach), Miami, FL 33139', '<p>12th Street Beach is located at 1200 S. Linn White Drive (12th Street at Lake Michigan on Northerly Island) and is nestled just south of Adler Planetarium on Chicago’s Museum Campus in Burnham Park.  Beach goers can enjoy food and beverages from Del Campos - offering a Mexican menu along with hot dogs. The beach house offers restrooms.  There is a non-motorized boat launch available at the beach and distance swimming is located parallel to shore at boat line.  Paid parking lot along with limited street parking is available. This beach has an accessible beach walk.</p>\r\n<p> </p>\r\n<p>Distance swimming is available parallel to shore at boat line. 12th Street Beach dates to the 1920s. In 1909, renowned architect Daniel Burnham envisioned a new park composed of several man-made islands between Jackson Park and Grant Park. Northerly Island was the only island that was actually built.</p>', ''),
(72, 18, 'ar', 'Family Apartments', '', '12th Street Beach (Miami Beach), Miami, FL 33139', '<p>12th Street Beach is located at 1200 S. Linn White Drive (12th Street at Lake Michigan on Northerly Island) and is nestled just south of Adler Planetarium on Chicago’s Museum Campus in Burnham Park.  Beach goers can enjoy food and beverages from Del Campos - offering a Mexican menu along with hot dogs. The beach house offers restrooms.  There is a non-motorized boat launch available at the beach and distance swimming is located parallel to shore at boat line.  Paid parking lot along with limited street parking is available. This beach has an accessible beach walk.</p>\r\n<p> </p>\r\n<p>Distance swimming is available parallel to shore at boat line. 12th Street Beach dates to the 1920s. In 1909, renowned architect Daniel Burnham envisioned a new park composed of several man-made islands between Jackson Park and Grant Park. Northerly Island was the only island that was actually built.</p>', '');
