INSERT INTO `uhb289_news` (`id`, `news_code`, `language_id`, `type`, `header_text`, `body_text`, `date_created`, `is_active`) VALUES
(1, 'txj17hkwau', 'en', 'news', 'New version 2.5.9 of uHotelBooking has been released', '<p>New version 2.5.9 of uHotelBooking has been released and available now for downloading. There are many improvements and new features added you will like. This version may be installed as a new version or updated, if you have the previous version already installed. All recent changes can be viewed <a href="https://www.hotel-booking-script.com/changelog">here</a>.</p>', '2018-01-02 22:00:31', 1),
(2, 'txj17hkwau', 'es', 'news', 'Nueva versión 2.5.9 of uHotelBooking ha sido puesto en libertad.', '<p>Nueva versión 2.5.9 of uHotelBooking ha sido liberado y disponible para su descarga. Hay muchas mejoras y nuevas características añadidas que te guste. Esta versión se puede instalar como una versión nueva o actualizada, si usted tiene la versión anterior already instalado. Todos los cambios recientes se pueden ver <a href="https://www.hotel-booking-script.com/changelog">aquí</a>.</p>', '2016-11-21 19:42:12', 1),
(3, 'txj17hkwau', 'de', 'news', 'Neue Version 2.5.9 of uHotelBooking ist veröffentlicht worden', '<p>Neue Version 2.5.9 of uHotelBooking ist erschienen und ab sofort zum Download bereit. Es gibt viele Verbesserungen und neue Funktionen hinzugefügt werden Sie mögen. Diese Version kann als eine neue Version installiert oder aktualisiert werden, wenn Sie über die vorherige Version already installiert. Alle Änderungen können <a href="https://www.hotel-booking-script.com/changelog">hiere</a> eingesehen werden.</p>', '2016-11-21 19:42:33', 1),
(4, 'h25m4t0p9l', 'en', 'last_minute', 'Hot Deal for H9 Metropolitan - Hurry Up! Only 3 rooms left!', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi. Hurry Up! Only 3 rooms left!</p>', '2016-10-21 19:15:32', 1),
(5, 'h25m4t0p9l', 'es', 'last_minute', 'Hot Deal for H9 Metropolitan - Hurry Up! Only 3 rooms left!', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi. Hurry Up! Only 3 rooms left!</p>', '2016-10-21 19:15:32', 1),
(6, 'h25m4t0p9l', 'de', 'last_minute', 'Hot Deal for H9 Metropolitan - Hurry Up! Only 3 rooms left!', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi. Hurry Up! Only 3 rooms left!</p>', '2016-10-21 19:15:32', 1),
(7, 'txj17hkwau', 'ar', 'news', 'New version 2.5.9 of uHotelBooking has been released', '<p>New version 2.5.9 of uHotelBooking has been released and available now for downloading. There are many improvements and new features added you will like. This version may be installed as a new version or updated, if you have the previous version already installed. All recent changes can be viewed <a href="https://www.hotel-booking-script.com/changelog">here</a>.</p>', '2016-11-21 19:39:45', 1),
(8, 'h25m4t0p9l', 'ar', 'last_minute', 'Hot Deal for H9 Metropolitan - Hurry Up! Only 3 rooms left!', '<p>Featuring a rooftop terrace with a bar, chill-out pool and gym, H10 Metropolitan is located in Barcelona, 90 metres from Plaça Catalunya. It offers a tapas restaurant and free WiFi. Hurry Up! Only 3 rooms left!</p>', '2016-10-21 19:15:32', 1);
