INSERT INTO `uhb289_pages` (`id`, `page_code`, `language_id`, `content_type`, `link_url`, `link_target`, `page_key`, `page_title`, `page_text`, `menu_id`, `menu_link`, `tag_title`, `tag_keywords`, `tag_description`, `comments_allowed`, `date_created`, `date_updated`, `finish_publishing`, `is_home`, `is_removed`, `is_published`, `is_system_page`, `system_page`, `show_in_search`, `status_changed`, `access_level`, `priority_order`) VALUES
(1, 'rpo5bahloy', 'en', 'article', '', '_self', 'uHotelBooking-is-happy-to-welcome-you', 'uHotelBooking is happy to welcome you!', '<p><img class="img-indent" src="images/upload/img1.png" border="0" alt="" align="left" /></p>\r\n<p>Come alone or bring your family with you, stay here for a night or for weeks, stay here while on business trip or at some kind of conference - either way our hotel is the best possible variant.</p>\r\n<p>Our site makes it simple to book your next hotel stay. Whether you''re traveling for business or pleasure, we provide you with some of the best hotel deals around. Discover cheap rates on rooms near the places you like, tucked away in the mountains, in the heart of the city, or scattered in the countryside. With our site, your hotel reservation options are endless.</p>', 0, '', 'uHotelBooking', 'php hotel site, hotel online booking site', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2017-02-03 17:11:01', NULL, 1, 0, 1, 0, '', 1, '2010-04-24 16:55:05', 'public', 0),
(2, 'rpo5bahloy', 'es', 'article', '', '_self', 'uHotelBooking-se-complace-en-darle-la', 'uHotelBooking se complace en darle la bienvenida!', '<p><img class="img-indent" src="images/upload/img1.png" border="0" alt="" align="left" /></p>\r\n<p>Venga solo o traer a su familia con usted, quédese aquí por una noche o por semana, estancia aquí en viaje de negocios o en algún tipo de conferencia - en cualquier caso, nuestro hotel es la mejor variante posible.</p>\r\n<p>ONuestro sitio hace que sea sencillo para reservar su estadía en el hotel. Ya sea que viaje por negocios o por placer, le ofrecemos algunas de las mejores ofertas de hoteles en los alrededores. Descubre tarifas económicas en habitaciones cerca de los lugares que le gusten, escondido en las montañas, en el corazón de la ciudad, o dispersas en el campo. Con nuestro sitio, las opciones de reservas de hotel son infinitas.</p>', 0, '', 'uHotelBooking', 'php sitio del hotel, sitio de reserva de hotel en línea', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2017-02-03 17:12:48', NULL, 1, 0, 1, 0, '', 1, '2010-04-24 16:55:12', 'public', 0),
(3, 'rpo5bahloy', 'de', 'article', '', '_self', 'uHotelBooking-ist-glücklich-Sie-zu-empfangen', 'uHotelBooking ist glücklich, Sie zu empfangen!', '<p><img class="img-indent" src="images/upload/img1.png" border="0" alt="" align="left" /></p>\r\n<p>Kommen Sie alleine oder bringen Sie Ihre Familie mit Ihnen, bleiben Sie hier für eine Nacht oder für Wochen, bleiben hier während einer Geschäftsreise oder bei irgendeiner Art von Konferenz - so oder so unser Hotel die beste Variante ist.</p>\r\n<p>Unsere Website macht es einfach, Ihren nächsten Hotelaufenthalt zu buchen. Ob Sie geschäftlich oder privat unterwegs sind, stellen wir Ihnen einige der besten Hotelangebote um. Entdecken Sie günstige Raten für Zimmer in der Nähe der Orte, die Sie mögen, versteckt in den Bergen entfernt, im Herzen der Stadt, oder in der Landschaft verstreut. Mit unserer Website, sind Ihre Reservierungsmöglichkeiten endlos.</p>', 0, '', 'uHotelBooking', 'php Hotel Website, Hotel online buchen Website', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2017-02-03 17:13:30', NULL, 1, 0, 1, 0, '', 1, '2010-04-24 16:55:05', 'public', 0),
(4, '99fnhie8in', 'en', 'article', '', '_self', 'Installation', 'Installation', '<p>Software requirements: PHP 5.0 or later version.</p>\r\n<p>A new installation of uHotelBooking is a very straight forward process:</p>\r\n<p><strong>Step 1</strong>. Uncompressing downloaded file.<br />-<br /> Uncompress the uHotelBooking version 4.x.x script archive. The archive will create<br /> a directory called "uHotelBooking_2xx"<br /><br /><br /><strong>Step 2</strong>. Uploading files.<br />-<br /> Upload content of this folder (all files and directories it includes) to your <br /> document root (public_html, www, httpdocs etc.) or your booking script directory using FTP.<br /> Pay attention to DON''T use the capital letters in the name of the folder (for Linux users).</p>\r\n<p>public_html/<br /> or<br /> public_html/{hotel-site directory}/<br /> <br /> Rename default.htaccess into .htaccess if you need to add PHP5 handler.</p>\r\n<p><br /><strong>Step 3</strong>. Creating database.<br />-<br /> Using your hosting Control Panel, phpMyAdmin or another tool, create your database<br /> and user, and assign that user to the database. Write down the name of the<br /> database, username, and password for the site installation procedure.</p>\r\n<p><br /><strong>Step 4</strong>. Running install.php file.<br />-<br /> Now you can run install.php file. To do this, open a browser and type in Address Bar</p>\r\n<p>http://{www.example.com}/install.php<br /> or<br /> http://{www.example.com}/{hotel-site directory}/install.php</p>\r\n<p>Follow instructions on the screen. You will be asked to enter: database host,<br /> database name, username and password. Also you need to enter admin username and<br /> admin password, that will be used to get access to administration area of the<br /> site.</p>\r\n<p><br /><strong>Step 5</strong>. Setting up access permissions.<br />-<br /> Check access permissions to images/uploads/. You need to have 755 permissions <br /> to this folder.</p>\r\n<p><br /><strong>Step 6</strong>. Deleting install.php file.<br />-<br /> After successful installation you will get an appropriate message and warning to<br /> remove install.php file. For security reasons, please delete install file<br /> immediately.</p>\r\n<p><br />Congratulations, you now have uHotelBooking installed!</p>', 1, 'Installation', 'Installation of uHotelBooking', 'php hotel site, hotel online booking site', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2014-11-21 19:18:35', NULL, 0, 0, 1, 0, '', 1, '2012-04-23 20:08:59', 'public', 0),
(5, '99fnhie8in', 'es', 'article', '', '_self', 'Instalación', 'Instalación', '<p>Requisitos de software: PHP 5.0 o una versión posterior.</p>\r\n<p>Una nueva instalación de uHotelBooking es un proceso muy sencillo:</p>\r\n<p><strong>Paso 1</strong>. Descomprimir el archivo descargado.</p>\r\n<p>Descomprimir el archivo uHotelBooking versión 4.xx secuencia de comandos. El archivo se creará un directorio llamado "uHotelBooking_2xx".<br /><br /><strong>Paso 2</strong>. Carga de archivos.<br /><br />Subir el contenido de esta carpeta (todos los archivos y directorios que incluye) a la raíz del documento (www public_html, httpdocs etc) o el directorio de secuencias de comandos de reserva a través de FTP. Preste atención a NO usar las letras mayúsculas en el nombre de la carpeta (para usuarios de Linux).</p>\r\n<p>public_html/<br /> or<br /> public_html/{hotel-site directorio}/<br /> <br /> Cambiar el nombre de default.htaccess en. htaccess si es necesario agregar controlador de PHP5.</p>\r\n<p><br /><strong>Paso 3</strong>. Creación de base de datos.<br /><br />Usando su Panel de Control, phpMyAdmin o cualquier otra herramienta, crear su base de datos y el usuario, y asignar a ese usuario a la base de datos. Anote el nombre de la base de datos, nombre de usuario y una contraseña para el procedimiento de instalación del sitio.</p>\r\n<p><br />Paso 4. Ejecutar el archivo install.php.<br /><br />Ahora puedes ejecutar el archivo install.php. Para ello, abra un navegador y escriba en la barra de direcciones</p>\r\n<p>http://{www.example.com}/install.php<br /> or<br /> http://{www.example.com}/{hotel-site directorio}/install.php</p>\r\n<p>Siga las instrucciones en la pantalla. Se le pedirá que introduzca: base de datos de host, nombre de base de datos, nombre de usuario y contraseña. También es necesario introducir nombre de usuario y contraseña de administrador, que se utilizará para tener acceso al área de administración del sitio.</p>\r\n<p><br /><strong>Paso 5</strong>. Configuración de permisos de acceso.<br /><br />Compruebe los permisos de acceso a las images/uploads/. Usted necesita tener 755 permisos a esta carpeta.</p>\r\n<p><br /><strong>Paso 6</strong>. Borrar el archivo install.php.<br /><br />Después de la instalación aparecerá un mensaje apropiado y alerta a eliminar el archivo install.php. Por razones de seguridad, por favor elimine el archivo de instalación de inmediato.</p>\r\n<p><br />Felicitaciones, ahora tiene uHotelBooking Instalado!</p>', 2, 'Instalación', 'uHotelBooking', 'php sitio del hotel, sitio de reserva de hotel en línea', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2014-11-21 19:18:45', NULL, 0, 0, 1, 0, '', 1, NULL, 'public', 0),
(6, '99fnhie8in', 'de', 'article', '', '_self', 'Installation', 'Installation', '<p>Software-Anforderungen: PHP 5.0 oder höher Version.</p>\r\n<p>Eine neue Installation von uHotelBooking ist ein sehr geradlinig Prozess:</p>\r\n<p><strong><span style="text-decoration: underline;">Schritt 1</span></strong>. Dekomprimieren heruntergeladene Datei.<br /><br />Entpacken Sie das uHotelBooking Version 4.xx Skript-Archiv. Das Archivwirderstellt ein Verzeichnis namens "uHotelBooking_2xx".<br /><br /><br /><strong><span style="text-decoration: underline;">Schritt 2</span></strong>. Hochladen von Dateien.<br /><br />Hochladen Inhalt dieses Ordners (alle Dateien und Verzeichnisse es umfasst), um Ihre Document-Root (public_html, www, httpdocs usw.) oder Ihre Reservierung Skript direkt per FTP. Achten Sie auf Don''t Gebrauch die Großbuchstaben im Namen des Ordners (für Linux-Anwender).</p>\r\n<p>public_html/<br /> or<br /> public_html/{hotel-site Verzeichnis}/<br /> <br />Benennen Sie in default.htaccess. htaccess, wenn Sie PHP5 Handler hinzufügen müssen.</p>\r\n<p><br /><strong>Schritt 3</strong>. Erstellen Datenbank.<br /><br />Mit Ihrem Hosting Control Panel, phpMyAdmin oder ein anderes Tool, erstellen Sie Ihre Datenbank und Benutzer, und weisen Sie die Benutzer auf die Datenbank. Notieren Sie den Namen des Datenbank, den Benutzernamen und das Kennwort für den Einbau vor Ort Verfahren.</p>\r\n<p><br /><span style="text-decoration: underline;"><strong>Schritt 4</strong></span>. Running install.php Datei..<br /><br />Jetzt können Sie install.php Datei. Dazu öffnen Sie einen Browser und geben Sie Adresse Bar</p>\r\n<p>http://{www.example.com}/install.php<br /> or<br /> http://{www.example.com}/{hotel-site Verzeichnis}/install.php</p>\r\n<p>Befolgen Sie die Anweisungen auf dem Bildschirm. Sie werden aufgefordert, einzugeben: Datenbank-Host,<br />Datenbankname, Benutzername und Passwort. Darüber hinaus müssen Sie Benutzernamen admin und    geben Sie Admin-Passwort, mit denen der Zugriff auf Administrationsbereich der erhalten werden Website.</p>\r\n<p><br /><span style="text-decoration: underline;"><strong>Schritt 5</strong></span>. Einrichten von Zugriffsberechtigungen.<br /><br />Überprüfen Sie die Zugriffsberechtigungen auf images/uploads/. Sie müssen zu 755 Berechtigungen für diesen Ordner haben.</p>\r\n<p><br /><span style="text-decoration: underline;"><strong>Schritt 6</strong></span>. Löschen install.php.<br /><br />Nach erfolgreicher Installation erhalten Sie eine entsprechende Meldung und Warnung an install.php Datei zu entfernen. Aus Sicherheitsgründen bitte löschen Installationsdatei sofort.</p>\r\n<p><br />Herzlichen Glückwunsch, Sie haben jetzt uHotelBooking Installiert!</p>', 3, 'Installation', 'Installation', 'php Hotel Website, Hotel online buchen Website', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2014-11-21 19:18:58', NULL, 0, 0, 1, 0, '', 1, NULL, 'public', 0),
