(13, '87ghtyfd5t', 'en', 'article', '', '_self', 'We-offer-several-kinds-of-rooms', 'We offer several kinds of rooms', 'We offer several kinds of rooms and apartments, in various sizes and  price ranges; single rooms in shared kitchens and studio, couples and  family apartments (1 or 2 bedroom). Many apartments are accessible for  wheelchair users.<br>{module:rooms}', 0, 'Rooms', 'Rooms', 'php hotel site, hotel online booking site', 'Check different rooms in our hotel', 0, '2011-05-01 11:16:22', '2014-11-19 19:06:56', NULL, 0, 0, 1, 1, 'rooms', 1, NULL, 'public', 0),
(14, '87ghtyfd5t', 'es', 'article', '', '_self', 'Ofrecemos-varios-tipos-de-habitaciones', 'Ofrecemos varios tipos de habitaciones', '<p>Ofrecemos varios tipos de habitaciones y apartamentos, en diversos tamaños y precios; habitaciones individuales en cocinas compartidas y estudio, parejas y apartamentos de la familia (1 o 2 dormitorios). Muchos de los apartamentos son accesibles para usuarios de sillas de ruedas.<br />{module:rooms}</p>', 0, 'Salas', 'Ofrecemos varios tipos de habitaciones', 'php sitio del hotel, sitio de reserva de hotel en línea', 'Compruebe distintas habitaciones de nuestro hotel', 0, '2011-05-01 11:16:22', '2017-12-27 20:27:02', NULL, 0, 0, 1, 1, 'rooms', 1, NULL, 'public', 0),
(15, '87ghtyfd5t', 'de', 'article', '', '_self', 'Zimmer', 'Zimmer', 'Wir bieten verschiedene Arten von Zimmern und Apartments in verschiedenen Größen und Preisklassen ; Einzelzimmer in Gemeinschaftsküchen und Studio, Paare und Familien-Appartements (1 oder 2 Schlafzimmer). Viele Wohnungen sind für Rollstuhlfahrer zugänglich.<br>{module:rooms}', 0, 'Zimmer', 'Zimmer', 'php Hotel Website, Hotel online buchen Website', 'Prüfen Sie verschiedene Zimmer in unserem Hotel', 0, '2011-05-01 11:16:22', '2014-11-21 19:22:25', NULL, 0, 0, 1, 1, 'rooms', 1, NULL, 'public', 0),
(16, '45tfrtbfg8', 'en', 'article', '', '_self', 'Today’s-featured-menu-item', 'Today’s featured menu item', '<p><img style="margin-right: 7px;" src="images/upload/restaurant_dishes.jpg" border="0" alt="" vspace="5" align="left" /></p>\r\n<h3 class="extra-wrap">Foie gras!</h3>\r\n<div class="extra-wrap">\r\n<ul class="list2">\r\n<li>Nice and tasty! </li>\r\n<li>Made from French ingredients! </li>\r\n<li>Cooked by Italian chef! </li>\r\n<li>Awarded by world’s assosiation of chef! </li>\r\n<li>Proved to be good for your health!</li>\r\n</ul>\r\n</div>\r\n<div><strong class="txt2">AS LOW AS €19!</strong></div>\r\n<p><br /><br /><br /><br /></p>\r\n<h3><br />Menu/Specials</h3>\r\n<div class="extra-wrap">\r\n<ul>\r\n<li>LYNAGH’S BEER CHEESE <br />Our own recipe, made with Guinness Stout served w/ carrots, celery &amp; crackers. -- $4.99 </li>\r\n<li>SALSA <br />TAME OR FLAME Homemade salsa served with tortilla chips. The TAME is HOT!!! -- $2.99 </li>\r\n<li>SPINACH ARTICHOKE DIP <br />Served with tortilla chips. -- $6.49 </li>\r\n<li>DOC BILL''S PUB PRETZELS <br />Two jumbo pretzels deep fried and served with hot homemade beer cheese. -- $5.49 </li>\r\n<li>ULTIMATE IRISH <br />Take the Irish Nacho, add red onions and our famous chili. -- $9.99 </li>\r\n<li>SPICY QUESO BEEF DIP <br />Ground beef, queso, Mexican spices, jalapenos, and sour cream. That’s gotta be good! -- $6.49 </li>\r\n<li>DELUXE NACHOS <br />Tortillas smothered with chili, cheese, lettuce tomatoes, jalapenos &amp; sour cream.</li>\r\n</ul>\r\n</div>', 0, 'Restaurant', 'Restaurant', 'php hotel site, hotel online booking site', 'Today’s featured menu item', 0, '2011-05-01 11:16:22', '2014-11-12 14:04:55', NULL, 0, 0, 1, 1, 'restaurant', 1, NULL, 'public', 2),
(17, '45tfrtbfg8', 'es', 'article', '', '_self', 'Elemento-de-menú-aparece-hoy', 'Elemento de menú aparece hoy', '<p><img src="images/upload/restaurant_dishes.jpg" border="0" alt="" hspace="5" vspace="5" align="left" /></p>\r\n<div class="extra-wrap">\r\n<h5>Foie gras!</h5>\r\n<ul class="list2">\r\n<li>Niza y sabroso! </li>\r\n<li>Elaborado con ingredientes francés! </li>\r\n<li>Cocinados por el chef italiano! </li>\r\n<li>Demuestran ser buenos para tu salud!</li>\r\n</ul>\r\n<div class="aligncenter"><strong class="txt2">Más bajo de €19!</strong></div>\r\n</div>\r\n<p> </p>\r\n<h3><br /><br /><br /></h3>\r\n<h3>Menú / Especiales</h3>\r\n<div class="extra-wrap">\r\n<ul>\r\n<li>LYNAGH’S BEER CHEESE <br />Our own recipe, made with Guinness Stout served w/ carrots, celery &amp; crackers. -- $4.99 </li>\r\n<li>SALSA <br />TAME OR FLAME Homemade salsa served with tortilla chips. The TAME is HOT!!! -- $2.99 </li>\r\n<li>SPINACH ARTICHOKE DIP <br />Served with tortilla chips. -- $6.49 </li>\r\n<li>DOC BILL''S PUB PRETZELS <br />Two jumbo pretzels deep fried and served with hot homemade beer cheese. -- $5.49 </li>\r\n<li>ULTIMATE IRISH <br />Take the Irish Nacho, add red onions and our famous chili. -- $9.99 </li>\r\n<li>SPICY QUESO BEEF DIP <br />Ground beef, queso, Mexican spices, jalapenos, and sour cream. That’s gotta be good! -- $6.49 </li>\r\n<li>DELUXE NACHOS <br />Tortillas smothered with chili, cheese, lettuce tomatoes, jalapenos &amp; sour cream.</li>\r\n</ul>\r\n</div>', 0, 'Restaurante', 'Restaurante', 'php sitio del hotel, sitio de reserva de hotel en línea', 'Elemento de menú aparece hoy', 0, '2011-05-01 11:16:22', '2014-11-12 14:00:54', NULL, 0, 0, 1, 1, 'restaurant', 1, NULL, 'public', 2),
(18, '45tfrtbfg8', 'de', 'article', '', '_self', 'Restaurant', 'Restaurant', '<p><img style="margin-right: 7px;" src="images/upload/restaurant_dishes.jpg" border="0" alt="" vspace="5" align="left" /></p>\r\n<h3 class="extra-wrap">Stopfleber!</h3>\r\n<div class="extra-wrap">\r\n<ul class="list2">\r\n<li>Nizza und lecker!<br />Aus Französisch Zutaten!<br />Gekochtes vom italienischen Küchenchef!<br />Ausgezeichnet vom weltweit Hauptverbandes der Chef!<br />Erwies sich als gut für Ihre Gesundheit!</li>\r\n</ul>\r\n</div>\r\n<div><strong class="txt2">so niedrig wie 19 €!</strong></div>\r\n<p><br /><br /><br /><br /></p>\r\n<h3>Menü/Specials</h3>\r\n<div class="extra-wrap">\r\n<ul>\r\n<li>Lynagh Bier KÄSE<br />Unser eigenes Rezept, mit Guinness Stout gemacht serviert w/Karotten, Sellerie &amp; Cracker. - $4,99 </li>\r\n<li>SALSA<br />TAME oder Flamme Hausgemachte Salsa serviert mit Tortilla Chips. Die TAME ist heiß! - $2,99 </li>\r\n<li>SPINAT ARTISCHOCKE DIP<br />Serviert mit Tortilla Chips. - $6,49 </li>\r\n<li>DOC BILL''s Pub PRETZELS<br />Zwei Jumbo-Brezeln gebacken und serviert mit heißer hausgemachtes Bier Käse. - $5,49 </li>\r\n<li>ULTIMATE IRISH<br />Nehmen Sie die irischen Nacho, roten Zwiebeln hinzufügen und unser berühmtes Chili. - $9.99 </li>\r\n<li>SPICY QUESO BEEF DIP<br />Hackfleisch, queso, mexikanische Gewürze, Jalapenos und Sauerrahm. Das musst gut sein! - $6,49 </li>\r\n<li>DELUXE NACHOS<br />Tortillas mit Chili, Käse, Salat Tomaten, Jalapenos &amp; Sauerrahm erstickt.</li>\r\n</ul>\r\n</div>', 0, 'Restaurant', 'Restaurant', 'php Hotel Website, Hotel online buchen Website', 'Die heutige vorgestellten Menüeintrag', 0, '2011-05-01 11:16:22', '2014-11-21 19:22:56', NULL, 0, 0, 1, 1, 'restaurant', 1, NULL, 'public', 2),
