(30, 'q8mv7zrzmo', 'de', 'article', '', '_self', 'Schreiben-Sie-uns', 'Schreiben Sie uns', '<p>{module:contact_us}</p>', 0, 'Kontakt', 'Schreiben Sie uns', 'php Hotel Website, Hotel online buchen Website', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2014-11-21 19:23:52', NULL, 0, 0, 1, 1, 'contact_us', 1, NULL, 'public', 5),
(31, 'rpo5bahloy', 'ar', 'article', '', '_self', 'uHotelBooking-is-happy-to-welcome-you', 'uHotelBooking is happy to welcome you!', '<p><img class="img-indent" src="images/upload/img1.png" border="0" alt="" align="left" /></p>\r\n<p>Come alone or bring your family with you, stay here for a night or for weeks, stay here while on business trip or at some kind of conference - either way our hotel is the best possible variant.</p>\r\n<p>Our site makes it simple to book your next hotel stay. Whether you''re traveling for business or pleasure, we provide you with some of the best hotel deals around. Discover cheap rates on rooms near the places you like, tucked away in the mountains, in the heart of the city, or scattered in the countryside. With our site, your hotel reservation options are endless.</p>', 0, '', 'uHotelBooking', 'php hotel site, hotel online booking site', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2017-02-03 17:11:01', NULL, 1, 0, 1, 0, '', 1, '2010-04-24 16:55:05', 'public', 0),
(32, '99fnhie8in', 'ar', 'article', '', '_self', 'Installation', 'Installation', '<p>Software requirements: PHP 5.0 or later version.</p>\r\n<p>A new installation of uHotelBooking is a very straight forward process:</p>\r\n<p><strong>Step 1</strong>. Uncompressing downloaded file.<br />-<br /> Uncompress the uHotelBooking version 4.x.x script archive. The archive will create<br /> a directory called "uHotelBooking_2xx"<br /><br /><br /><strong>Step 2</strong>. Uploading files.<br />-<br /> Upload content of this folder (all files and directories it includes) to your <br /> document root (public_html, www, httpdocs etc.) or your booking script directory using FTP.<br /> Pay attention to DON''T use the capital letters in the name of the folder (for Linux users).</p>\r\n<p>public_html/<br /> or<br /> public_html/{hotel-site directory}/<br /> <br /> Rename default.htaccess into .htaccess if you need to add PHP5 handler.</p>\r\n<p><br /><strong>Step 3</strong>. Creating database.<br />-<br /> Using your hosting Control Panel, phpMyAdmin or another tool, create your database<br /> and user, and assign that user to the database. Write down the name of the<br /> database, username, and password for the site installation procedure.</p>\r\n<p><br /><strong>Step 4</strong>. Running install.php file.<br />-<br /> Now you can run install.php file. To do this, open a browser and type in Address Bar</p>\r\n<p>http://{www.example.com}/install.php<br /> or<br /> http://{www.example.com}/{hotel-site directory}/install.php</p>\r\n<p>Follow instructions on the screen. You will be asked to enter: database host,<br /> database name, username and password. Also you need to enter admin username and<br /> admin password, that will be used to get access to administration area of the<br /> site.</p>\r\n<p><br /><strong>Step 5</strong>. Setting up access permissions.<br />-<br /> Check access permissions to images/uploads/. You need to have 755 permissions <br /> to this folder.</p>\r\n<p><br /><strong>Step 6</strong>. Deleting install.php file.<br />-<br /> After successful installation you will get an appropriate message and warning to<br /> remove install.php file. For security reasons, please delete install file<br /> immediately.</p>\r\n<p><br />Congratulations, you now have uHotelBooking installed!</p>', 1, 'Installation', 'Installation of uHotelBooking', 'php hotel site, hotel online booking site', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2014-11-21 19:18:35', NULL, 0, 0, 1, 0, '', 1, '2012-04-23 20:08:59', 'public', 0),
(33, 'afd4vgf5yt', 'ar', 'article', '', '_self', 'صالة-عرض', 'صالة عرض', '<p>{module:gallery}</p>', 0, 'صالة عرض', 'Gallery', 'php hotel site, hotel online booking site', 'View our video and image galleries', 0, '2011-05-01 11:16:22', '2017-12-27 20:16:55', NULL, 0, 0, 1, 1, 'gallery', 1, NULL, 'public', 1),
(34, 'op8uy67ydd', 'ar', 'article', '', '_self', 'الشهادات', 'الشهادات', '<p>{module:testimonials}</p>', 0, 'الشهادات', 'Testimonials', 'php hotel site, hotel online booking site', 'What our clients are saying', 0, '2011-05-01 11:16:22', '2017-12-27 20:17:37', NULL, 0, 0, 1, 1, 'testimonials', 1, NULL, 'public', 3),
(35, '87ghtyfd5t', 'ar', 'article', '', '_self', 'نحن-نقدم-العديد-من-أنواع-الغرف', 'نحن نقدم العديد من أنواع الغرف', '<p>We offer several kinds of rooms and apartments, in various sizes and  price ranges; single rooms in shared kitchens and studio, couples and  family apartments (1 or 2 bedroom). Many apartments are accessible for  wheelchair users.<br />{module:rooms}</p>', 0, 'غرف', 'Rooms', 'php hotel site, hotel online booking site', 'Check different rooms in our hotel', 0, '2011-05-01 11:16:22', '2017-12-27 20:16:33', NULL, 0, 0, 1, 1, 'rooms', 1, NULL, 'public', 0),
(36, '45tfrtbfg8', 'ar', 'article', '', '_self', 'اليوم-عنصر-القائمة-واردة', 'اليوم عنصر القائمة واردة', '<p><img style="margin-right: 7px;" src="images/upload/restaurant_dishes.jpg" border="0" alt="" vspace="5" align="left" /></p>\r\n<h3 class="extra-wrap">Foie gras!</h3>\r\n<div class="extra-wrap">\r\n<ul class="list2">\r\n<li>Nice and tasty! </li>\r\n<li>Made from French ingredients! </li>\r\n<li>Cooked by Italian chef! </li>\r\n<li>Awarded by world’s assosiation of chef! </li>\r\n<li>Proved to be good for your health!</li>\r\n</ul>\r\n</div>\r\n<div><strong class="txt2">AS LOW AS €19!</strong></div>\r\n<p><br /><br /><br /><br /></p>\r\n<h3><br />Menu/Specials</h3>\r\n<div class="extra-wrap">\r\n<ul>\r\n<li>LYNAGH’S BEER CHEESE <br />Our own recipe, made with Guinness Stout served w/ carrots, celery &amp; crackers. -- $4.99 </li>\r\n<li>SALSA <br />TAME OR FLAME Homemade salsa served with tortilla chips. The TAME is HOT!!! -- $2.99 </li>\r\n<li>SPINACH ARTICHOKE DIP <br />Served with tortilla chips. -- $6.49 </li>\r\n<li>DOC BILL''S PUB PRETZELS <br />Two jumbo pretzels deep fried and served with hot homemade beer cheese. -- $5.49 </li>\r\n<li>ULTIMATE IRISH <br />Take the Irish Nacho, add red onions and our famous chili. -- $9.99 </li>\r\n<li>SPICY QUESO BEEF DIP <br />Ground beef, queso, Mexican spices, jalapenos, and sour cream. That’s gotta be good! -- $6.49 </li>\r\n<li>DELUXE NACHOS <br />Tortillas smothered with chili, cheese, lettuce tomatoes, jalapenos &amp; sour cream.</li>\r\n</ul>\r\n</div>', 0, 'مطعم', 'Restaurant', 'php hotel site, hotel online booking site', 'Today’s featured menu item', 0, '2011-05-01 11:16:22', '2017-12-27 20:17:22', NULL, 0, 0, 1, 1, 'restaurant', 1, NULL, 'public', 2),
(37, 's3d4fder56', 'ar', 'article', '', '_self', 'معلومات-عنا', 'معلومات عنا', '<p>{module:about_us}</p>', 0, 'معلومات عنا', 'About Us', 'php hotel site, hotel online booking site', 'uHotelBooking', 0, '2011-05-01 11:16:22', '2017-12-27 20:17:58', NULL, 0, 0, 1, 1, 'about_us', 1, NULL, 'public', 4),
