INSERT INTO `uhb289_reviews` (`id`, `hotel_id`, `customer_id`, `title`, `positive_comments`, `negative_comments`, `rating_cleanliness`, `rating_room_comfort`, `rating_location`, `rating_service`, `rating_sleep_quality`, `rating_price`, `evaluation`, `travel_type`, `passenger_type`, `image_file_1`, `image_file_1_thumb`, `image_file_2`, `image_file_2_thumb`, `image_file_3`, `image_file_3_thumb`, `date_created`, `is_active`, `priority_order`) VALUES
(1, 1, 1, 'Great experience', 'Nice large hotel located on the Red Sea. The breakfast buffet is GREAT! Good location, good beach, good facilities. Staff was more or less friendly, with some exceptions. Nice breakfasts.', 'Noisy at evenings, especially when lots of people arrive. The hotel facilities are outdated. When the hotel is heavily booked it becomes too crowded everywhere and not nice to be.', 2.0, 3.0, 4.0, 4.1, 4.2, 4.0, 4, 2, 0, '', '', '', '', '', '', '2014-01-02 12:03:00', 1, 0),
(2, 1, 2, 'I liked it very much!', 'It is close to everything but if you go in the lower season the pool won''t be ready even though the temperature was quiet high already.', 'Your front staff was wonderful, i believe her name was Moran, please thank her from us.', 4.4, 2.3, 3.0, 5.0, 4.0, 4.0, 5, 2, 0, '', '', '', '', '', '', '2014-01-04 13:04:00', 1, 1),
(3, 1, 3, 'Excellent hotel, very good!', 'The view from our balcony in room # 409, was terrific. It was centrally located to everything on and around the port area. Wonderful service and everything was very clean.', 'The breakfast was below average, although not bad. If back in this town we would stay there again.', 4.0, 5.0, 4.1, 4.3, 4.0, 3.0, 3, 2, 0, '', '', '', '', '', '', '2014-01-04 15:04:00', 1, 2),
(4, 1, 4, 'Great experience', 'Excellent hotel, friendly staff would def go there again. Breakfast is from 7:00 until 12:00, which is Great. Breakfast is really good and worth the cost.', '', 4.1, 3.2, 4.0, 4.0, 5.0, 4.0, 4, 2, 0, '', '', '', '', '', '', '2014-01-05 12:05:00', 1, 3),
(5, 2, 1, 'Super, great experience', 'Rooms clean tidy and serviced daily. Pool stunning.', 'Nice location, but the hotel is so old...', 3.2, 4.2, 4.0, 2.5, 5.0, 4.0, 3, 2, 0, '', '', '', '', '', '', '2014-01-06 16:05:00', 1, 4),
(6, 3, 2, 'Not bad, not bad..!', 'Cleanness is so-so, but I guess it is standard for this place. The apartment is very small for its money.', 'P-e-r-f-e-c-t location.', 2.4, 3.3, 3.4, 3.5, 2.1, 3.4, 5, 2, 0, '', '', '', '', '', '', '2014-02-03 13:01:22', 1, 1),
(7, 4, 3, 'Excellent', 'Location and great customer service. Place is very pleasant and accommodating. I would come again.', 'The breakfast was below average, although not bad. If back in this town we would stay there again.', 2.3, 4.5, 2.3, 3.3, 4.3, 3.0, 3, 2, 0, '', '', '', '', '', '', '2014-04-04 15:06:00', 1, 2),
(8, 5, 4, 'Great experience', 'Excellent hotel, friendly staff would def go there again. Breakfast is from 7:00 until 12:00, which is Great. Breakfast is really good and worth the cost.', '', 4.1, 3.2, 4.0, 4.0, 5.0, 4.0, 4, 2, 0, '', '', '', '', '', '', '2014-01-05 12:05:00', 1, 3),
(9, 6, 1, 'Great experience', 'Nice large hotel located on the Red Sea. The breakfast buffet is GREAT! Good location, good beach, good facilities. Staff was more or less friendly, with some exceptions. Nice breakfasts.', 'Noisy at evenings, especially when lots of people arrive. The hotel facilities are outdated. When the hotel is heavily booked it becomes too crowded everywhere and not nice to be.', 2.0, 3.0, 4.0, 4.1, 4.2, 4.0, 4, 2, 0, '', '', '', '', '', '', '2014-01-02 12:03:00', 1, 0);
