INSERT INTO `uhb289_rooms_description` (`id`, `room_id`, `language_id`, `room_type`, `room_short_description`, `room_long_description`) VALUES
(1, 1, 'en', 'Single', '<p>Rooms measuring 15 m² equipped with all the details expected of a superior 4 star hotel. Services: Wake up call service, Customer service, Laundry service and express laundry, Concierge service, Pillow menu.</p>', '<p><strong>Description:</strong><br />Rooms measuring 15 m² equipped with all the details expected of a superior 4 star hotel.</p>\r\n<p><strong>Services: </strong>\r\n<ul class="services">\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul></p>'),
(2, 1, 'es', 'Single', '<p>Habitaciones de unos 15 m², equipada con todos los detalles de un 4 estrellas superior Hotel. Servicios: Servicio despertador servicio, Servicio al cliente, Servicio de lavandería y lavandería express.</p>', '<p><strong>Descripción:</strong><br /> Habitaciones de unos 15 m², equipada con todos los detalles de un 4 estrellas superior Hotel.</p>\r\n<p><strong>Servicios:</strong><ul class="services">\r\n<li>Servicio despertador servicio</li>\r\n<li>Servicio al cliente</li>\r\n<li>Servicio de lavandería y lavandería express</li>\r\n<li>Conserjería de servicios</li>\r\n<li>Carta de almohadas</li>\r\n</ul></p>'),
(3, 1, 'de', 'Single', '<p>Zimmer 15 m² Messung mit allen Details eines 4-Sterne-Superior-Hotel erwartet. Dienstleistungen: Weckdienst, Customer Service, Wäsche-Service und Express-Wäsche-, Concierge-Service, Auswahl an Kissen.</p>', '<p><strong>Beschreibung:</strong><br /> Zimmer 15 m² Messung mit allen Details eines 4-Sterne-Superior-Hotel erwartet.</p>\r\n<p><strong>Dienstleistungen:</strong>\r\n<ul class="services">\r\n<li>Weckdienst</li>\r\n<li>Kundendienst</li>\r\n<li>Wäscherei-Service und Express-Wäsche</li>\r\n<li>Conciergeservice Service</li>\r\n<li>Kissenmenü</li>\r\n</ul></p>'),
(4, 2, 'en', 'Double', '<p>Modern and functional rooms measuring approximately 20-25 m² equipped with all the details expected of the hotel. The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres ideal for sports teams.</p>', '<p><strong>Description</strong>:<br />Modern and functional rooms measuring approximately 20-25 m² equipped with all the details expected of the hotel. <br /><br />The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 meters ideal for sports teams and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).<br /><br /><strong>Services</strong>:\r\n<ul class="services">\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul></p>'),
(5, 2, 'es', 'Double', '<p>Habitaciones modernas y funcionales de aproximadamente 20-25 m&sup2; equipadas con todos los detalles del hotel. Las habitaciones tienen una cama king o queen size o dos camas individuales, adem&aacute;s de camas de 1 por 2,2 metros ideal para equipos deportivos.</p>', '<p><strong>Descripción </strong>:<br />\r\nHabitaciones modernas y funcionales de aproximadamente 20-25 m² equipadas con todos los detalles del hotel.\r\n<br /><br />\r\nLas habitaciones tienen una cama king o queen size o dos camas individuales, además de camas de 1 por 2,2 metros ideal para equipos deportivos y puntos de vista de las calles de los patios interiores tranquila (Solicitud de disponibilidad a la llegada al hotel).\r\n<br /><br />\r\n<strong>Servicios</strong>:\r\n<ul class="services">\r\n<li>Servicio despertador servicio</li>\r\n<li>Servicio al cliente</li>\r\n<li>Servicio de lavandería y lavandería express</li>\r\n<li>Conserjería de servicios</li>\r\n<li>Carta de almohadas</li>\r\n</ul></p>'),
(6, 2, 'de', 'Double', '<p>Moderne und funktionale Zimmer Messung ca. 20-25 m&sup2; mit allen Details des Hotel erwartet. Die Zimmer verf&uuml;gen &uuml;ber ein King oder Queen-Size-Bett oder zwei Einzelbetten, zus&auml;tzlich zu Betten Messung ideal f&uuml;r Sport-Teams.</p>', '<p><strong>Beschreibung</strong>:<br />\r\nModerne und funktionale Zimmer Messung ca. 20-25 m² mit allen Details des Hotel erwartet.\r\n<br /><br />\r\nDie Zimmer verfügen über ein King oder Queen-Size-Bett oder zwei Einzelbetten, zusätzlich zu Betten der Größe von 1 um 2,2 Meter ideal für Sport-Teams und Blick auf den Straßen der ruhigen Innenhöfen (Anfrage Verfügbarkeit bei Ankunft im Hotel).\r\n<br /><br />\r\n<strong>Dienstleistungen</strong>:\r\n<ul class="services">\r\n<li>Weckdienst</li>\r\n<li>Kundendienst</li>\r\n<li>Wäscherei-Service und Express-Wäsche</li>\r\n<li>Conciergeservice Service</li>\r\n<li>Kissenmenü</li>\r\n</ul></p>'),
(7, 3, 'en', 'Superior', '<p>Spacious rooms with exquisite decor, measuring approximately 25-30 m&sup2; and equipped with all the details expected of the hotel hotel. The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres.</p>', '<p><strong>Description</strong>:\r\n<br />\r\nSpacious rooms with exquisite decor, measuring approximately 25-30 m² and equipped with all the details expected of the hotel hotel.\r\n<br /><br />\r\nThe rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres ideal for sports teams and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).\r\n<br /><br />\r\n<strong>Services</strong>:\r\n<ul class="services">\r\n<li>24 hour room service</li>\r\n<li>Wake up call service</li>\r\n<li>Serviexpress customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul>\r\n</p>'),
(8, 3, 'es', 'Superior', '<p>Amplias habitaciones con una decoraci&oacute;n exquisita, de 25-30 m&sup2; equipadas con todos los detalles del hotel hotel. Las habitaciones tienen una cama king o queen size o dos camas individuales, adem&aacute;s de camas de 1 por 2,2 metros.</p>', '<p><strong>Descripción</strong>:\r\n<br />\r\nAmplias habitaciones con una decoración exquisita, de 25-30 m² equipadas con todos los detalles del hotel hotel.\r\n<br /><br />\r\nLas habitaciones tienen una cama king o queen size o dos camas individuales, además de camas de 1 por 2,2 metros ideal para equipos deportivos y puntos de vista de las calles de los patios interiores tranquila (Solicitud de disponibilidad a la llegada al hotel).\r\n<br /><br />\r\n<strong>Servicios</strong>:\r\n<ul class="services">\r\n<li>24 horas de servicio sala de</li>\r\n<li>Servicio despertador servicio</li>\r\n<li>"Serviexpress" de servicio al cliente</li>\r\n<li>Servicio de lavandería y lavandería express</li>\r\n<li>Conserjería de servicios</li>\r\n<li>Carta de almohadas</li>\r\n</ul>\r\n</p>'),
(9, 3, 'de', 'Superior', '<p>Spacious rooms with exquisite decor, measuring approximately 25-30 m&sup2; and equipped with all the details expected of the hotel hotel. The rooms have a king or queen size bed or two single beds.</p>', '<p><strong>Beschreibung</strong>:\r\n<br />\r\nGeräumige Zimmer mit exquisiter Ausstattung, Mess ca. 25-30 m² und mit allen Details des Hotels Hotel erwartet.\r\n<br /><br />\r\nDie Zimmer verfügen über ein King oder Queen-Size-Bett oder zwei Einzelbetten, zusätzlich zu Betten der Größe von 1 um 2,2 Meter ideal für Sport-Teams und Blick auf den Straßen der ruhigen Innenhöfen (Anfrage Verfügbarkeit bei Ankunft im Hotel).\r\n<br /><br />\r\n<strong>Dienstleistungen</strong>:\r\n<ul class="services">\r\n<li>24 Stunden Zimmer-Service</li>\r\n<li>Weckdienst</li>\r\n<li>"Serviexpress" Dienst am Kunden</li>\r\n<li>Wäscherei-Service und Express-Wäsche</li>\r\n<li>Conciergeservice Service</li>\r\n<li>Kissenmenü</li>\r\n</ul>\r\n</p>'),
(10, 4, 'en', 'Luxury', '<p>Spacious rooms with exquisite decor measuring approximately 25-30 m&sup2; and equipped with all the details expected of a superior 4 star Hotel. The rooms have a king or queen size bed or two single beds, and views of the streets.</p>', '<p><strong>Description</strong>:\r\n<br />\r\nSpacious rooms with exquisite decor measuring approximately 25-30 m² and equipped with all the details expected of a superior 4 star Hotel.\r\n<br /><br />\r\nThe rooms have a king or queen size bed or two single beds, and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).\r\n<br /><br />\r\n<strong>Services</strong>:\r\n<br />\r\n<ul class="services">\r\n<li>Private reception located on the 6th floor</li>\r\n<li>Welcome courtesy replaced daily</li>\r\n<li>Buffet breakfast in private room between 7am and 11am</li>\r\n<li>Free Open Bar available on the Luxury Service floor, from 16:30 to 22:30</li>\r\n<li>24 hour room service</li>\r\n<li>10% discount on lunches and dinners at our Diábolo restaurant, after consultation and booking at the Royal Service reception and subject to availability</li>\r\n<li>Free 30 minute use per stay of computers in the Business Centre (hall), including printer and 25 photocopies</li>\r\n<li>Free 8 minute Ultra Violet Ray session per stay</li>\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n<li>Turn down service</li>\r\n</ul>\r\n* The Luxury Service is closed from Friday at 12:00 until Sunday at 15:00.\r\n</p>'),
(11, 4, 'es', 'Luxury', '<p>Amplias habitaciones con una decoraci&oacute;n exquisita de 25-30 m&sup2; y est&aacute;n equipadas con todos los detalles de un 4 estrellas superior Hotel. Las habitaciones tienen una cama king o queen size o dos camas individuales.</p>', '<p><strong>Descripción</strong>:\r\n<br />\r\nAmplias habitaciones con una decoración exquisita de 25-30 m² y están equipadas con todos los detalles de un 4 estrellas superior Hotel.\r\n<br /><br />\r\nLas habitaciones tienen una cama king o queen size o dos camas individuales, y vistas de las calles de los patios interiores tranquila (Solicitud de disponibilidad a la llegada al hotel).\r\n<br /><br />\r\n<strong>Servicios</strong>:\r\n<br />\r\n<ul class="services">\r\n<li>Recepción privada situada en la planta sexta</li>\r\n<li>Bienvenido cortesía reposición diaria</li>\r\n<li>Desayuno Buffet en habitación privada 07 a.m.-11 a.m.</li>\r\n<li>Libre Open Bar se encuentra en la planta noble de servicio, 16:30-22:30</li>\r\n<li>24 horas de servicio sala de</li>\r\n<li>10% de descuento en almuerzos y cenas en nuestro restaurante Diábolo, previa consulta y reserva en la recepción de Servicio Real y sujeto a disponibilidad</li>\r\n<li>Libre uso de 30 minutos por estancia de los ordenadores en el Centro de Negocios (vestíbulo), incluyendo impresoras y fotocopias de los 25</li>\r\n<li>Libre 8 minutos Ultra Violeta Ray período de sesiones por estancia</li>\r\n<li>Servicio despertador servicio</li>\r\n<li>Servicio al cliente</li>\r\n<li>Servicio de lavandería y lavandería express</li>\r\n<li>Conserjería de servicios</li>\r\n<li>Carta de almohadas</li>\r\n<li>Ponga Servicio de cobertura</li>\r\n</ul>\r\n* El servicio de lujo está cerrado desde el viernes hasta el domingo a las 12:00 a las 15:00.\r\n</p>'),
(12, 4, 'de', 'Luxury', '<p>Ger&auml;umige Zimmer mit exquisiter Ausstattung messung ca. 25-30 m&sup2; gro&szlig; und mit Allen Details eines 4-Sterne-Superior-Hotel expected. Die Zimmer verf&uuml;gen &Uuml;ber Ein K&ouml;nig Oder Queen-Size-Bett und Blick Auf Die Strassen.</p>', '<p><strong>Beschreibung</strong>:\r\n<br />\r\nGeräumige Zimmer mit exquisiter Ausstattung Messung ca. 25-30 m² groß und mit allen Details eines 4-Sterne-Superior-Hotel Meliá Hotel erwartet.\r\n<br /><br />\r\nDie Zimmer verfügen über ein King oder Queen-Size-Bett oder zwei Einzelbetten und Blick auf den Straßen der ruhigen Innenhöfen (Anfrage Verfügbarkeit bei Ankunft im Hotel).\r\n<br /><br />\r\n<strong>Dienstleistungen</strong>:\r\n<br />\r\n<ul class="services">\r\n<li>Private Empfang auf der 6. Etage Willkommen Höflichkeit ersetzt täglich</li>\r\n<li>Buffet Frühstück im privaten Raum 7.00 bis 11.00 Uhr</li>\r\n<li>Kostenlose Open Bar auf dem Luxus-Service Stock, von 16.30 bis 22.30 Uhr</li>\r\n<li>24 Stunden Zimmer-Service</li>\r\n<li>10% Rabatt auf Mittag-und Abendessen in unserem Restaurant Diabolo, nach Absprache und Reservierung im Royal Service Rezeption und je nach Verfügbarkeit</li>\r\n<li>Kostenlose 30 Minuten Nutzung pro Aufenthalt von Computern im Business Center (Halle), einschließlich Drucker und 25 Kopien</li>\r\n<li>Freie 8 Minuten Ultra Violet Ray-Sitzung pro Aufenthalt</li>\r\n<li>Weckdienst</li>\r\n<li>Kundendienst</li>\r\n<li>Wäscherei-Service und Express-Wäsche</li>\r\n<li>Conciergeservice Service</li>\r\n<li>Kissenmenü</li>\r\n<li>Schalten Down-Service</li>\r\n</ul>\r\n* El servicio de lujo está cerrado desde el viernes hasta el domingo a las 12:00 a las 15:00.\r\n</p>'),
(13, 5, 'en', 'Standard Room', '<p>Relax in our standard room, complete with two queen size beds, customized furniture, gel-infused pillow top mattresses topped with luxurious duvets and duvet covers clean for every guest.</p>', '<p>Relax in our standard room, complete with two queen size beds, customized furniture, gel-infused pillow top mattresses topped with luxurious duvets and duvet covers clean for every guest, flat screen TV, mini-fridge, executive desk, wireless internet, all tastefully decorated with climate control at your fingertips. Exercise in our state of the art fitness facility, swim in our heated indoor swimming pool or relax in our sauna, all free of cost for our guests.</p>'),
(14, 5, 'es', 'Habitación Estándar', '<p>Relájese en nuestra habitación estándar, con dos camas queen size, muebles a medida, colchones con acolchado de gel con infusión cubierto con edredones de lujo y fundas nórdicas limpia para todos los huéspedes.</p>', '<p>Relájese en nuestra habitación estándar, con dos camas queen size, muebles a medida, colchones con acolchado de gel con infusión cubierto con edredones de lujo y fundas nórdicas limpia para todos los huéspedes, TV pantalla plana, mini-nevera, escritorio ejecutivo, internet inalámbrico, todo con buen gusto decorado con climatizador a su alcance. Ejercicio en nuestro estado del arte gimnasio, nadar en la piscina cubierta climatizada o relajarse en la sauna, todo sin costo para nuestros huéspedes.</p>'),
(15, 5, 'de', 'Standard Zimmer', '<p>Entspannen Sie in unserem Standard-Zimmer, komplett mit zwei Queen-Size-Betten, individuelle Möbel, gekrönt Gel-infundiert Matratzen mit Bettdecken und Bettbezüge sauber für jeden Gast.</p>', '<p>Entspannen Sie in unserem Standard-Zimmer, komplett mit zwei Queen-Size-Betten, individuelle Möbel, gekrönt Gel-infundiert Matratzen mit Bettdecken und Bettbezüge sauber für jeden Gast, Flachbild-TV, Mini-Kühlschrank, Executive Schreibtisch, Wireless Internet, alle geschmackvoll Klimaanlagen an Ihren Fingerspitzen verziert. Übung in unserem Stand der Technik: Fitnessmöglichkeiten, schwimmen im beheizten Innenpool oder entspannen Sie in unserer Sauna, alle kostenlos für unsere Gäste.</p>'),
(16, 6, 'en', 'Double Room with Two Double Beds', '<p>A standard hotel room is an elongated hotel room designed for two people, though some standard doubles can accommodate up to four. The standard double hotel room is available at many full-service hotels, with the exclusion of facilities that house only suites or extended-stay guests.</p>', '<p>A standard hotel room is an elongated hotel room designed for two people, though some standard doubles can accommodate up to four. The standard double hotel room is available at many full-service hotels, with the exclusion of facilities that house only suites or extended-stay guests. The standard double room is ideal for a brief stay of up to a few days. It doesn''t contain a kitchen, so guests can''t cook their own meals.</p>'),
(17, 6, 'es', 'Habitación Doble con dos camas dobles', '<p>Una habitación de hotel estándar es una habitación de hotel alargada diseñada para dos personas, aunque algunas habitaciones dobles estándar tienen capacidad para hasta cuatro personas. La habitación de hotel estándar doble está disponible en muchos hoteles de servicio completo, con la exclusión de las instalaciones que albergan sólo suites o huéspedes de estadías prolongadas.</p>', '<p>Una habitación de hotel estándar es una habitación de hotel alargada diseñada para dos personas, aunque algunas habitaciones dobles estándar tienen capacidad para hasta cuatro personas. La habitación de hotel estándar doble está disponible en muchos hoteles de servicio completo, con la exclusión de las instalaciones que albergan sólo suites o huéspedes de estadías prolongadas. La habitación doble estándar es ideal para una breve estancia de hasta unos pocos días. No contiene una cocina, así que los huéspedes no pueden cocinar sus propias comidas.</p>'),
(18, 6, 'de', 'Double Room with Two Double BedsDoppelzimmer mit zwei Doppelbetten', '<p>Ein Standard-Hotelzimmer ist eine längliche Hotelzimmer für zwei Personen ausgelegt, auch wenn einige Standard-Doppelzimmer für bis zu vier Personen. Die Standard-Doppelhotelzimmer ist in vielen Hotels mit umfassendem Service zur Verfügung, mit Ausnahme von Einrichtungen, die nur Suiten oder längere Aufenthalte Gäste beherbergen.</p>', '<p>Ein Standard-Hotelzimmer ist eine längliche Hotelzimmer für zwei Personen ausgelegt, auch wenn einige Standard-Doppelzimmer für bis zu vier Personen. Die Standard-Doppelhotelzimmer ist in vielen Hotels mit umfassendem Service zur Verfügung, mit Ausnahme von Einrichtungen, die nur Suiten oder längere Aufenthalte Gäste beherbergen. Die Standard-Doppelzimmer ist ideal für einen kurzen Aufenthalt von bis zu wenigen Tagen. Es enthält nicht eine Küche, so können die Gäste ihre eigenen Mahlzeiten nicht kochen.</p>'),
(19, 7, 'en', 'Junior Suite', '<p>Our spacious Junior hotel Suites are 460 square feet (43 square meters) featuring floor-to-ceiling windows overlooking Manhattan from our New York City hotel suites. Junior Suites offer luxurious king beds, 55-inch flat-panel HDTV with Blu-ray player and iPod docking station, marble baths, and a large walk-in closet.</p>', '<p>Our spacious Junior hotel Suites are 460 square feet (43 square meters) featuring floor-to-ceiling windows overlooking Manhattan from our New York City hotel suites. Junior Suites offer luxurious king beds, 55-inch flat-panel HDTV with Blu-ray player and iPod docking station, marble baths, and a large walk-in closet.<br /> For your comfort and convenience, most also include a fully equipped European-style kitchen with appliances by Sub-Zero, and a sitting area with a twin-size sofa bed. All of our New York hotel guests enjoy full access to our health club and spa.</p>'),
(20, 7, 'es', 'Junior Suite', '<p>Nuestro hotel espaciosas Junior Suites son de 460 pies cuadrados (43 metros cuadrados) con ventanas de piso a techo y vistas a Manhattan desde nuestras suites de hotel de Nueva York. Las Junior Suites ofrecen lujosas camas king, de 55 pulgadas HDTV de pantalla plana con reproductor de Blu-ray y soporte para iPod, baños de mármol y un amplio walk-in closet.</p>', '<p>Nuestro hotel espaciosas Junior Suites son de 460 pies cuadrados (43 metros cuadrados) con ventanas de piso a techo y vistas a Manhattan desde nuestras suites de hotel de Nueva York. Las Junior Suites ofrecen lujosas camas king, de 55 pulgadas HDTV de pantalla plana con reproductor de Blu-ray y soporte para iPod, baños de mármol y un amplio walk-in closet.</p>\r\n<p>Para su comodidad y conveniencia, la mayoría también incluyen una cocina de estilo europeo, totalmente equipada con electrodomésticos de Sub-Zero, y una zona de estar con un sofá cama doble de tamaño. Todos los huéspedes del hotel de Nueva York de un acceso completo a nuestro club de salud y spa.</p>'),
(21, 7, 'de', 'Junior Suite', '<p>Unsere geräumigen Junior-Hotel-Suiten sind 460 Quadratmeter (43 qm) mit vom Boden bis zur Decke reichenden Fenster mit Blick auf Manhattan aus unserer Hotelsuiten in New York. Junior Suiten bieten luxuriöse Kingsize-Betten, 55-Zoll-Flachbildfernseher mit Blu-ray-Player und iPod-Dockingstation, Marmorbäder und einen großen begehbaren Kleiderschrank.</p>', '<p>Unsere geräumigen Junior-Hotel-Suiten sind 460 Quadratmeter (43 qm) mit vom Boden bis zur Decke reichenden Fenster mit Blick auf Manhattan aus unserer Hotelsuiten in New York. Junior Suiten bieten luxuriöse Kingsize-Betten, 55-Zoll-Flachbildfernseher mit Blu-ray-Player und iPod-Dockingstation, Marmorbäder und einen großen begehbaren Kleiderschrank.</p>\r\n<p>Für Ihren Komfort und Bequemlichkeit sind die meisten auch eine voll ausgestattete europäischen Stil Küche mit Geräten von Sub-Zero und einen Sitzbereich mit einem Doppelschlafsofa. Alle unsere Hotelgäste New York genießen Sie vollen Zugang zu unserem Health Club und Spa.</p>'),
(22, 8, 'en', 'Executive Double Room', '<p>Stunning Executive Double bedrooms provide the perfect setting in the heart of NY. Exclusive features you won’t find in Double Cumberland Guest rooms include luxurious bathrobes and slippers, complimentary mineral water and full access to the Guoman Club Lounge with complimentary newspapers and refreshments available all day.</p>', '<p>Stunning Executive Double bedrooms provide the perfect setting in the heart of NY. Exclusive features you won’t find in Double Cumberland Guest rooms include luxurious bathrobes and slippers, complimentary mineral water and full access to the Guoman Club Lounge with complimentary newspapers and refreshments available all day.</p>\r\n<p>As you would expect from Guoman, all our 50 Executive Double bedrooms also benefit from fast, complimentary BT Wi-fi and entertainment at your fingertips with a 32-inch LCD TV. You’ll appreciate extra space to unwind and recharge for the day ahead with beautifully designed bathrooms featuring walk-in power showers and mist-free mirrors. Welcome details that provide an oasis of calm in the centre of London.</p>'),
(23, 8, 'es', 'Executive Double Room', '<p>Impresionantes habitaciones dobles ejecutivas son el escenario perfecto en el corazón de Londres. Las características exclusivas que no encontrará en las habitaciones Doble Cumberland habitaciones incluyen albornoces y zapatillas de lujo, agua mineral de cortesía y acceso completo a la Guoman Club Lounge, con periódicos gratuitos y refrescos disponibles durante todo el día.</p>', '<p>Impresionantes habitaciones dobles ejecutivas son el escenario perfecto en el corazón. Las características exclusivas que no encontrará en las habitaciones Doble Cumberland habitaciones incluyen albornoces y zapatillas de lujo, agua mineral de cortesía y acceso completo a la Guoman Club Lounge, con periódicos gratuitos y refrescos disponibles durante todo el día.</p>\r\n<p>Como era de esperar de Guoman, todas nuestras 50 habitaciones dobles ejecutivas también se benefician de la rápida, conexión BT Wi-fi y el entretenimiento a tu alcance con un televisor LCD de 32 pulgadas. Usted apreciará el espacio extra para relajarse y recargar para el día siguiente, con baños de bonito diseño con duchas a presión ras de suelo y espejos antivaho. Detalles de bienvenida que proporcionan un oasis de calma en el centro de Londres.</p>'),
(24, 8, 'de', 'Executive Double Room', '<p>Atemberaubende Executive Doppelzimmer bieten die perfekte Lage im Herzen von New York. Exklusive Funktionen, die Sie nicht in Doppel Cumberland Zimmer zu finden sind luxuriöse Bademäntel und Hausschuhe, Mineralwasser und vollen Zugriff auf die Guoman Club-Lounge mit kostenlosen Zeitungen und Erfrischungen den ganzen Tag.</p>', '<p>Atemberaubende Executive Doppelzimmer bieten die perfekte Lage im Herzen von New York. Exklusive Funktionen, die Sie nicht in Doppel Cumberland Zimmer zu finden sind luxuriöse Bademäntel und Hausschuhe, Mineralwasser und vollen Zugriff auf die Guoman Club-Lounge mit kostenlosen Zeitungen und Erfrischungen den ganzen Tag.</p>\r\n<p>Wie Sie aus Guoman erwarten, alle unsere 50 Executive Doppelzimmer auch schnelle, kostenlose BT Wi-Fi-und Unterhaltungs an Ihren Fingerspitzen mit einem 32-Zoll-LCD-TV profitieren. Sie werden mehr Platz um sich zu entspannen und neue Kräfte für den kommenden Tag mit wunderschön gestaltete Bäder mit begehbarer Massageduschen und beschlagfreien Spiegel zu schätzen wissen. Willkommen Details, die eine Oase der Ruhe im Zentrum von London zu liefern.</p>'),
(25, 9, 'en', 'Junior Suite', '<p>These comfortable suites are ideal for guests looking for a little extra space. Featuring sumptuous carpets and gold silk curtains throughout, the large living area has a three-seater sofa, choice of beautifully upholstered armchairs and a dark wood coffee table, making it the perfect space for working, entertaining or relaxing. The bedroom area is a private retreat with king beds and large windows. Fashioned from black and white marble, bathrooms feature chequered floors and abstract artwork.</p>', '<p>These comfortable suites are ideal for guests looking for a little extra space. Featuring sumptuous carpets and gold silk curtains throughout, the large living area has a three-seater sofa, choice of beautifully upholstered armchairs and a dark wood coffee table, making it the perfect space for working, entertaining or relaxing. The bedroom area is a private retreat with king beds and large windows. Fashioned from black and white marble, bathrooms feature chequered floors and abstract artwork.</p>'),
(26, 9, 'es', 'Junior Suite', '<p>Estas cómodas suites son ideales para aquellos que buscan un poco más de espacio. Con suntuosas alfombras y cortinas de seda de oro por todas partes, la gran sala de estar cuenta con un sofá de tres plazas, la elección de las butacas bellamente tapizadas y una mesa de centro de madera oscura, por lo que es el espacio perfecto para trabajar, entretenerse o relajarse.</p>', '<p>Estas cómodas suites son ideales para aquellos que buscan un poco más de espacio. Con suntuosas alfombras y cortinas de seda de oro por todas partes, la gran sala de estar cuenta con un sofá de tres plazas, la elección de las butacas bellamente tapizadas y una mesa de centro de madera oscura, por lo que es el espacio perfecto para trabajar, entretenerse o relajarse. La zona del dormitorio es un refugio privado con camas king y grandes ventanales. Hecha de mármol blanco y negro, cuartos de baño cuentan con suelos de cuadros y obras de arte abstracto.</p>'),
(27, 9, 'de', 'Junior Suite', '<p>Die komfortablen Suiten sind ideal für Gäste, die etwas mehr Platz. Mit üppigen Teppichen und Seidenvorhängen Gold im gesamten, hat der große Wohnbereich einen Drei-Sitzer-Sofa, die Wahl der schön Polstersessel und eine dunkle Holzcouchtisch, so dass es die perfekte Platz zum Arbeiten, Unterhaltung und Entspannung.</p>', '<p>Die komfortablen Suiten sind ideal für Gäste, die etwas mehr Platz. Mit üppigen Teppichen und Seidenvorhängen Gold im gesamten, hat der große Wohnbereich einen Drei-Sitzer-Sofa, die Wahl der schön Polstersessel und eine dunkle Holzcouchtisch, so dass es die perfekte Platz zum Arbeiten, Unterhaltung und Entspannung. Das Schlafzimmer ist ein privater Rückzugsort mit Kingsize-Betten und großen Fenstern. Aus schwarzem und weißem Marmor gestaltet, die Badezimmer sind mit karierten Etagen und abstrakte Kunstwerke.</p>'),
(28, 10, 'en', 'Super Deluxe', '<p>Our Superior Rooms feature a Double bed or 2 Single beds as required by our guests, we also offer zip and link beds.  The size of the room varies from 17 to 20 Sq. Meters.  Below is a list of room features and amenities that adorn the room to make your stay more enjoyable.</p>', '<p>Our Superior Rooms feature a Double bed or 2 Single beds as required by our guests, we also offer zip and link beds.  The size of the room varies from 17 to 20 Sq. Meters.  Below is a list of room features and amenities that adorn the room to make your stay more enjoyable.</p>'),
(29, 10, 'es', 'Super Deluxe', '<p>Nuestras habitaciones de categoría superior cuentan con una cama doble o 2 camas individuales como requerido por nuestros clientes, también ofrecemos zip y enlace camas. El tamaño de la habitación varía del 17 al 20 Pies. Metros. A continuación se muestra una lista de las características de la habitación y las comodidades que adornan la sala para hacer su estancia más agradable.</p>', '<p>Nuestras habitaciones de categoría superior cuentan con una cama doble o 2 camas individuales como requerido por nuestros clientes, también ofrecemos zip y enlace camas. El tamaño de la habitación varía del 17 al 20 Pies. Metros. A continuación se muestra una lista de las características de la habitación y las comodidades que adornan la sala para hacer su estancia más agradable.</p>'),
(30, 10, 'de', 'Super Deluxe', '<p>Unser Superior-Zimmer verfügen über ein Doppelbett oder 2 Einzelbetten, wie unsere Gäste erforderlich ist, bieten wir auch Reißverschluss zu verbinden. Die Größe der Zimmer variiert von 17 bis 20 Quadrat. Meter. Unten ist eine Liste der Zimmerausstattung und Annehmlichkeiten, die den Raum um Ihren Aufenthalt noch angenehmer zu gestalten schmücken.</p>', '<p>Unser Superior-Zimmer verfügen über ein Doppelbett oder 2 Einzelbetten, wie unsere Gäste erforderlich ist, bieten wir auch Reißverschluss zu verbinden. Die Größe der Zimmer variiert von 17 bis 20 Quadrat. Meter. Unten ist eine Liste der Zimmerausstattung und Annehmlichkeiten, die den Raum um Ihren Aufenthalt noch angenehmer zu gestalten schmücken.</p>'),
(31, 11, 'en', 'Standard Double Room', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or etc.</p>', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or shower, Telephone, Radio, Satellite channels, Laptop safe, Flat-screen TV, Minibar, Coffee machine, Wake-up service, Alarm clock, Towels, Linens  Free WiFi is available in all rooms.</p>'),
(32, 11, 'es', 'Standard Double Room', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or etc.</p>', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or shower, Telephone, Radio, Satellite channels, Laptop safe, Flat-screen TV, Minibar, Coffee machine, Wake-up service, Alarm clock, Towels, Linens  Free WiFi is available in all rooms.</p>'),
(33, 11, 'de', 'Standard Double Room', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or etc.</p>', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or shower, Telephone, Radio, Satellite channels, Laptop safe, Flat-screen TV, Minibar, Coffee machine, Wake-up service, Alarm clock, Towels, Linens  Free WiFi is available in all rooms.</p>'),
(34, 12, 'en', 'Basic Double Room', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby.</p>', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby and our highly accessible transport options will get you into the heart of our city within minutes!</p>\r\n<p>Don''t forget to download and print your complimentary holiday packing list from the right-hand side!</p>'),
(35, 12, 'es', 'Basic Double Room', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby.</p>', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby and our highly accessible transport options will get you into the heart of our city within minutes!</p>\r\n<p>Don''t forget to download and print your complimentary holiday packing list from the right-hand side!</p>'),
(36, 12, 'de', 'Basic Double Room', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby.</p>', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby and our highly accessible transport options will get you into the heart of our city within minutes!</p>\r\n<p>Don''t forget to download and print your complimentary holiday packing list from the right-hand side!</p>'),
(37, 13, 'en', 'Business Twin Room', '<p>The large windows in these generously spacious 26 square metre rooms  provide a sense of openness and executive charm. Designed with a sense  of exacting details to meet the combined productive and relaxation needs  of guests travelling on business.</p>', '<p>The large windows in these generously spacious 26 square metre rooms  provide a sense of openness and executive charm. Designed with a sense  of exacting details to meet the combined productive and relaxation needs  of guests travelling on business, each room is furnished with a large  desk and LAN access, and easy chairs to just unwind. The layout though  simple, exudes a sense of freshness and cleanliness.</p>'),
(38, 13, 'es', 'Business Twin Room', '<p>Los grandes ventanales de la síntesis generosamente espaciosas 26 habitaciones metros cuadrados proporcionan un sentido de apertura y el encanto ejecutivo. Diseñado con un sentido de exigir detalles para satisfacer las necesidades productivas y de relajación combinadas de los huéspedes que viajan por negocios.</p>', '<p>Los grandes ventanales de la síntesis generosamente espaciosas 26 habitaciones metros cuadrados proporcionan un sentido de apertura y el encanto ejecutivo. Diseñado con un sentido de exigir detalles para satisfacer las necesidades productivas y de relajación combinadas de los huéspedes que viajan por negocios, cada habitación está equipada con un amplio escritorio y acceso a internet, y sillones para simplemente relajarse. El diseño, aunque simple, emana una sensación de frescura y limpieza.</p>'),
(39, 13, 'de', 'Business Twin Room', '<p>Die großen Fenster in Original-großzügig in geräumigen 26 Quadratmeter Zimmer bieten ein Gefühl der Offenheit und Executive Charme. Entworfen mit einem Gefühl der anspruchsvollen Details, um die kombinierten produktiv und Entspannung Bedürfnisse von Geschäftsreisenden gerecht zu werden, ist jedes Zimmer ausgestattet mit einem großen Schreibtisch und LAN-Zugang..</p>', '<p>Die großen Fenster in Original-großzügig in geräumigen 26 Quadratmeter Zimmer bieten ein Gefühl der Offenheit und Executive Charme. Entworfen mit einem Gefühl der anspruchsvollen Details, um die kombinierten produktiv und Entspannung Bedürfnisse von Geschäftsreisenden gerecht zu werden, ist jedes Zimmer ausgestattet mit einem großen Schreibtisch und LAN-Zugang und Sessel nur entspannen. Die einfachste Layout aber strahlt ein Gefühl von Frische und Sauberkeit.</p>'),
(40, 14, 'en', 'Suite', '<p>A suite in a hotel or other public accommodation denotes a class of accommodations with more space than a typical hotel room.</p>', '<p>A suite in a hotel or other public accommodation denotes a class of accommodations with more space than a typical hotel room.  In luxury or upscale accommodations, such as Ritz Carlton, Marriott, or Embassy Suites, key features may include multiple rooms. Many independent properties have one or more honeymoon suites, and sometimes the best accommodation at a high-end hotel is called the presidential suite or royal suite.</p>'),
(41, 14, 'es', 'Siguiente', '<p>Una suite en un hotel u otro alojamiento público denota una clase de alojamientos con más espacio que una típica habitación de hotel.</p>', '<p>Una suite en un hotel u otro alojamiento público denota una clase de alojamientos con más espacio que una típica habitación de hotel. En lujo o alojamiento de lujo, como el Ritz Carlton, Marriot, o Embassy Suites, características clave pueden incluir múltiples habitaciones. Muchas de las propiedades independientes tienen una o más suites de luna de miel, ya veces el mejor alojamiento en un hotel de gama alta se llama la suite presidencial o suite real.</p>'),
(42, 14, 'de', 'Folgende', '<p>Eine Suite in einem Hotel oder einer anderen öffentlichen Unterkunft bezeichnet eine Klasse von Unterkünften mit mehr Platz als ein typisches Hotelzimmer.</p>', '<p>Eine Suite in einem Hotel oder einer anderen öffentlichen Unterkunft bezeichnet eine Klasse von Unterkünften mit mehr Platz als ein typisches Hotelzimmer. In Luxus oder gehobene Ausstattung, wie Ritz Carlton, Marriott oder Embassy Suites, können Hauptmerkmale mehrere Räume umfassen. Viele unabhängige Eigenschaften eine oder mehrere Honeymoon-Suiten, und manchmal die beste Unterkunft zu einem High-End-Hotel wird als Präsidenten-Suite oder Royal Suite.</p>'),
(43, 15, 'en', 'Grand Sea View Room', '<p>Welcome to this contemporary room offering an amazing sea view, a balcony, work area and marble bathroom. Catch up on work at the desk or check your emails with complimentary internet access.</p>', '<p>Welcome to this contemporary room offering an amazing sea view, a balcony, work area and marble bathroom. Catch up on work at the desk or check your emails with complimentary internet access. Special touches include daily newspapers delivery upon request and welcome amenities.</p>'),
(44, 15, 'es', 'Grand Sea View Room', '<p>Bienvenido a esta habitación contemporánea que ofrece una increíble vista al mar, balcón, área de trabajo y baño de mármol. Trabaje cómodamente en el escritorio o revise su correo electrónico con acceso a internet gratuito.</p>', '<p>Bienvenido a esta habitación contemporánea que ofrece una increíble vista al mar, balcón, área de trabajo y baño de mármol. Trabaje cómodamente en el escritorio o revise su correo electrónico con acceso a internet gratuito. Los detalles especiales incluyen periódicos entrega diaria bajo petición y atención de bienvenida.</p>'),
(45, 15, 'de', 'Grand Sea View Room', '<p>Willkommen in diesem modernen Zimmer bietet einen traumhaften Blick aufs Meer, einen Balkon, einen Arbeitsbereich und ein Marmorbad. Erledigen Sie Ihre Arbeit am Schreibtisch oder surfen Sie mit kostenlosem Internetzugang.</p>', '<p>Willkommen in diesem modernen Zimmer bietet einen traumhaften Blick aufs Meer, einen Balkon, einen Arbeitsbereich und ein Marmorbad. Erledigen Sie Ihre Arbeit am Schreibtisch oder surfen Sie mit kostenlosem Internetzugang. Extras wie Tageszeitungen Lieferung auf Anfrage und Willkommensgruß.</p>'),
(46, 16, 'en', 'Family studio sea view', '<p>Studios have a walk in Shower &amp; separate bathtub, king-size or twin beds, individually controlled air conditioning / heating, satellite TV with pay movies, complimentary WiFi &amp; broadband internet connection, safe, mini-bar, coffee &amp; tea making facilities, baby monitoring service via the telephone.</p>', '<p>Studios have a walk in Shower &amp; separate bathtub, king-size or twin beds, individually controlled air conditioning / heating, satellite TV with pay movies, complimentary WiFi &amp; broadband internet connection, safe, mini-bar, coffee &amp; tea making facilities, baby monitoring service via the telephone.</p>\r\n<p>All rooms have balcony (Beach Studios have either balcony or terrace) with one table and two chairs and boast panoramic views of the blue Mediterranean Sea.</p>'),
(47, 16, 'es', 'Familia estudio vistas mar', '<p>Los estudios tienen un pie en la ducha &amp; amp; bañera separada, king-size o dos camas, aire acondicionado / calefacción con control individual, TV vía satélite con películas de pago, WiFi gratuito &amp; amp; conexión a Internet de banda ancha, caja fuerte, mini-bar, café &amp; amp; tetera, servicio de vigilancia del bebé a través del teléfono. <!-- p--></p>', '<p>Los estudios tienen un pie en la ducha &amp; amp; bañera separada, king-size o dos camas, aire acondicionado / calefacción con control individual, TV vía satélite con películas de pago, WiFi gratuito &amp; amp; conexión a Internet de banda ancha, caja fuerte, mini-bar, café &amp; amp; tetera, servicio de vigilancia del bebé a través del teléfono. <!-- p--></p>\r\n<p>Todas las habitaciones tienen balcón (Estudios de playa tienen balcón o terraza) con una mesa y dos sillas, y ofrecen vistas panorámicas al mar Mediterráneo. <!-- p--></p>'),
(48, 16, 'de', 'Familienstudio mit Meerblick', '<p>Die Studios verfügen über eine begehbare Dusche &amp; amp; separate Badewanne, ein Kingsize-oder zwei Einzelbetten, eine individuell regulierbare Klimaanlage / Heizung, Sat-TV mit Pay-TV, kostenlosem WiFi &amp; amp; Breitband-Internetverbindung, Safe, Minibar, Kaffee &amp; amp; Teekocher, Babyüberwachungsdienst über das Telefon. <!-- p--></p>', '<p>Die Studios verfügen über eine begehbare Dusche &amp; amp; separate Badewanne, ein Kingsize-oder zwei Einzelbetten, eine individuell regulierbare Klimaanlage / Heizung, Sat-TV mit Pay-TV, kostenlosem WiFi &amp; amp; Breitband-Internetverbindung, Safe, Minibar, Kaffee &amp; amp; Teekocher, Babyüberwachungsdienst über das Telefon. <!-- p--></p>\r\n<p>Alle Zimmer verfügen über Balkon (Beach Studios haben entweder Balkon oder Terrasse) mit einem Tisch und zwei Stühlen und bieten Panoramablick auf das blaue Mittelmeer. <!-- p--></p>'),
(49, 17, 'en', 'Superior Double Room', '<p>Classically beautiful and individually designed rooms from 20 sqm/215 sqf. All rooms contain a comfortable seating area and a modern workplace with a desk and comfy king-size bed. Some rooms have a fantastic waterfront view of the Royal Palace and Gasmla Stand, our old town.</p>', '<p>Sometimes you need a little more space. We offer a number of larger suites that can be expanded to up to five rooms by adding beautifully decorated parlours. The parlours come in two sizes – grand and grandiose.</p>\r\n<p>Classically beautiful and individually designed rooms from 20 sqm/215 sqf. All rooms contain a comfortable seating area and a modern workplace with a desk and comfy king-size bed. Some rooms have a fantastic waterfront view of the Royal Palace and Gasmla Stand, our old town.</p>'),
(50, 17, 'es', 'Habitación Doble Superior', '<p>Salas de belleza clásica e individualmente diseñada a partir de 20 metros cuadrados / 215 pies cuadrados. Todas las habitaciones cuentan con una cómoda zona de estar y un lugar de trabajo moderno con un escritorio y una cama king-size cómoda. Algunas habitaciones tienen vista al mar fantástica del Palacio Real y Gasmla Stand, nuestro casco antiguo.</p>', '<p>A veces se necesita un poco más de espacio. Ofrecemos una serie de suites más grandes que se pueden ampliar a un máximo de cinco habitaciones añadiendo salones bellamente decoradas. Los salones vienen en dos tamaños -. Grande y grandioso <!-- p--></p>\r\n<p>salas de belleza clásica y diseño individual de 20 metros cuadrados / 215 pies cuadrados. Todas las habitaciones cuentan con una cómoda zona de estar y un lugar de trabajo moderno con un escritorio y una cama king-size cómoda. Algunas habitaciones tienen vista al mar fantástica del Palacio Real y Gasmla Stand, nuestra vieja ciudad. <!-- P--></p>'),
(51, 17, 'de', 'Superior Doppelzimmer', '<p>Klassisch schön und individuell von 20 qm / 215 sqf gestaltete Zimmer. Alle Zimmer verfügen über eine gemütliche Sitzecke und ein modernes Arbeitsplatz mit Schreibtisch und bequemen King-Size-Bett. Einige Zimmer verfügen über einen fantastischen Blick über das Wasser auf den Königspalast und Gasmla Stand unserer Altstadt.</p>', '<p>Manchmal braucht man etwas mehr Platz. Wir bieten eine Reihe von größeren Suiten, die bis zu fünf Räume, indem schön dekorierten Stuben erweitert werden kann. Die Stuben sind in zwei Größen -. Grand und grandiose <!-- p--></p>\r\n<p>Klassisch schön und individuell eingerichtete Zimmer von 20 qm / 215 sqf. Alle Zimmer verfügen über eine gemütliche Sitzecke und ein modernes Arbeitsplatz mit Schreibtisch und bequemen King-Size-Bett. Einige Zimmer verfügen über einen fantastischen Blick über das Wasser auf den Königspalast und Gasmla Stand unserer Altstadt. <!-- P--></p>'),
(52, 18, 'en', 'Family Room', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>\r\n<p>All suites have a stunning waterfront view of the Royal Palace and Gamla Stan, Stockholm’s old town. The suites and parlours can be combined and fully tailored to meet your wishes and requirements. You can also hire an entire floor or two. Just get in touch and we’ll make the arrangements.</p>'),
(53, 18, 'es', 'Family Room', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>\r\n<p>All suites have a stunning waterfront view of the Royal Palace and Gamla Stan, Stockholm’s old town. The suites and parlours can be combined and fully tailored to meet your wishes and requirements. You can also hire an entire floor or two. Just get in touch and we’ll make the arrangements.</p>'),
(54, 18, 'de', 'Family Room', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>\r\n<p>All suites have a stunning waterfront view of the Royal Palace and Gamla Stan, Stockholm’s old town. The suites and parlours can be combined and fully tailored to meet your wishes and requirements. You can also hire an entire floor or two. Just get in touch and we’ll make the arrangements.</p>'),
(55, 19, 'en', 'Comfort Double or Twin Room', '<p>Stay and relax in our modern and spacious double or twin room perfectly suited for business style. All the rooms have authentic and distinctive design, a comfortable king size or twin bed, armchairs with coffee table and an integral desk for ease of work.  The rooms are intended to accommodate one, maximum two persons.</p>', '<p>Stay and relax in our modern and spacious double or twin room perfectly suited for business style. All the rooms have authentic and distinctive design, a comfortable king size or twin bed, armchairs with coffee table and an integral desk for ease of work.  The rooms are intended to accommodate one, maximum two persons.</p>');
INSERT INTO `uhb289_rooms_description` (`id`, `room_id`, `language_id`, `room_type`, `room_short_description`, `room_long_description`) VALUES
(56, 19, 'es', 'Confort Habitación Doble', '<p>En Casa y relajarse en nuestra habitación doble o dos camas individuales modernas y espaciosas perfectamente adecuado para el estilo de negocios. Todas las habitaciones disponen de auténtico y distintivo diseño, una cómoda cama extra grande o dos camas, sillones con mesa de centro y un escritorio integral para facilitar su trabajo. Las habitaciones están destinadas a alojar a uno, máximo dos personas. <!-- P--></p>', '<p>En Casa y relajarse en nuestra habitación doble o dos camas individuales modernas y espaciosas perfectamente adecuado para el estilo de negocios. Todas las habitaciones disponen de auténtico y distintivo diseño, una cómoda cama extra grande o dos camas, sillones con mesa de centro y un escritorio integral para facilitar su trabajo. Las habitaciones están destinadas a alojar a uno, máximo dos personas. <!-- P--></p>'),
(57, 19, 'de', 'Komfort Doppel- oder Zweibettzimmer', '<p>Wohnen und entspannen Sie in unserem modernen und geräumigen Doppel- oder Zweibettzimmer für Business-Stil geeignet. Alle Zimmer verfügen über authentische und unverwechselbare Design, ein komfortables Kingsize-oder zwei Einzelbetten, Sessel mit Couchtisch und einem integrierten Schreibtisch für einfache Arbeit. Die Zimmer sollen eine, maximal zwei Personen. <!-- P--></p>', '<p>Wohnen und entspannen Sie in unserem modernen und geräumigen Doppel- oder Zweibettzimmer für Business-Stil geeignet. Alle Zimmer verfügen über authentische und unverwechselbare Design, ein komfortables Kingsize-oder zwei Einzelbetten, Sessel mit Couchtisch und einem integrierten Schreibtisch für einfache Arbeit. Die Zimmer sollen eine, maximal zwei Personen. <!-- P--></p>'),
(58, 20, 'en', 'Junior Suite', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower.</p>', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower, Ren toiletries, bathrobes, slippers, self controlled air-conditioning unit and opening windows. We provide complimentary Wi-Fi and Water. All of our Suites have been newly refurbished in soothing pastille colours creating a relaxing luxurious space.  Can sleep up to 3 with an extra bed.</p>'),
(59, 20, 'es', 'Junior Suite', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower.</p>', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower, Ren toiletries, bathrobes, slippers, self controlled air-conditioning unit and opening windows. We provide complimentary Wi-Fi and Water. All of our Suites have been newly refurbished in soothing pastille colours creating a relaxing luxurious space.  Can sleep up to 3 with an extra bed.</p>'),
(60, 20, 'de', 'Junior Suite', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower.</p>', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower, Ren toiletries, bathrobes, slippers, self controlled air-conditioning unit and opening windows. We provide complimentary Wi-Fi and Water. All of our Suites have been newly refurbished in soothing pastille colours creating a relaxing luxurious space.  Can sleep up to 3 with an extra bed.</p>'),
(61, 21, 'en', 'Twin Room', '<p>Twin rooms can accommodate up to two people in adjacent twin beds (90cm wide). Our twin rooms overlook the courtyard, ensuring the utmost peace and quiet for our guests. All twin rooms have an en-suite bathroom with bath and toilet.</p>', '<p>Twin rooms can accommodate up to two people in adjacent twin beds (90cm wide). Our twin rooms overlook the courtyard, ensuring the utmost peace and quiet for our guests. All twin rooms have an en-suite bathroom with bath and toilet.</p>\r\n<p>It also features a large window, with black out shutters, and shared bathroom facilities . Linen and towels are included in the price. This room can only be booked for minimum of 2 persons.</p>'),
(62, 21, 'es', 'Twin Room', '<p>Las habitaciones dobles tienen capacidad para dos personas en camas adyacentes (90 cm de ancho). Nuestras habitaciones dobles tienen vistas al patio, lo que garantiza la máxima tranquilidad para nuestros huéspedes. Todas las habitaciones dobles disponen de cuarto de baño con bañera y WC.</p>', '<p>Las habitaciones dobles tienen capacidad para dos personas en camas adyacentes (90 cm de ancho). Nuestras habitaciones dobles tienen vistas al patio, lo que garantiza la máxima tranquilidad para nuestros huéspedes. Todas las habitaciones dobles disponen de cuarto de baño con bañera y WC.</p>\r\n<p>También cuenta con un gran ventanal, con persianas opacas y baño compartido. Ropa de cama y las toallas están incluidas en el precio. Esta habitación sólo se puede reservar para un mínimo de 2 personas.</p>'),
(63, 21, 'de', 'Twin Room', '<p>Doppelzimmer bietet Platz für bis zu zwei Personen in benachbarten Einzelbetten (90cm breit) unterzubringen. Unsere Doppelzimmer blicken auf den Innenhof, gleichzeitig die größtmögliche Ruhe für unsere Gäste. Alle Doppelzimmer verfügen über ein eigenes Bad mit Badewanne und WC.</p>', '<p>Doppelzimmer bietet Platz für bis zu zwei Personen in benachbarten Einzelbetten (90cm breit) unterzubringen. Unsere Doppelzimmer blicken auf den Innenhof, gleichzeitig die größtmögliche Ruhe für unsere Gäste. Alle Doppelzimmer verfügen über ein eigenes Bad mit Badewanne und WC.</p>\r\n<p>Es verfügt auch über ein großes Fenster mit Verdunklungsläden , und ein Gemeinschaftsbad. Bettwäsche und Handtücher sind im Preis inbegriffen. Dieses Zimmer kann nur für mindestens 2 Personen gebucht werden.</p>'),
(64, 22, 'en', 'Junior Suite', '<p>The Jr. Suite at the Sheraton Rhodes Resort. Enjoy spacious and welcoming living area, flat screen LCD 32” television, marble bathroom, private furnished balcony and your private coffee &amp; tea facilities: unique view over the Aegean Sea, living area,     sheraton Sweet Sleeper Bed (king size), branded bathroom amenities, bathrobes &amp; slippers.</p>', '<p>The Jr. Suite at the Sheraton Rhodes Resort. Enjoy spacious and welcoming living area, flat screen LCD 32” television, marble bathroom, private furnished balcony and your private coffee &amp; tea facilities: unique view over the Aegean Sea, living area,     sheraton Sweet Sleeper Bed (king size), branded bathroom amenities, bathrobes &amp; slippers.</p>'),
(65, 22, 'es', 'Junior Suite', '<p>La suite junior en el Sheraton Rhodes Resort. Disfrute amplia y acogedora sala de estar, pantalla plana LCD de 32 "de televisión, baño de mármol, balcón privado y sus instalaciones de café y té privadas: vista única sobre el mar Egeo, sala de estar, cama Sheraton Sweet Sleeper (king size), marca de tocador , albornoces y zapatillas.</p>', '<p>La suite junior en el Sheraton Rhodes Resort. Disfrute amplia y acogedora sala de estar, pantalla plana LCD de 32 "de televisión, baño de mármol, balcón privado y sus instalaciones de café y té privadas: vista única sobre el mar Egeo, sala de estar, cama Sheraton Sweet Sleeper (king size), marca de tocador , albornoces y zapatillas.</p>'),
(66, 22, 'de', 'Junior Suite', '<p>Die Junior Suite im Sheraton Rhodes Resort. Genießen Sie geräumige und einladende Wohnbereich, Flachbild-LCD 32 "Fernseher, Marmorbad, privaten Balkon und private Kaffee und Tee Einrichtungen: einzigartigen Blick auf das Ägäische Meer, Wohnbereich, Sheraton Sweet Sleeper Bett (Kingsize), Markentoiletten , Bademäntel und Hausschuhe.</p>', '<p>Die Junior Suite im Sheraton Rhodes Resort. Genießen Sie geräumige und einladende Wohnbereich, Flachbild-LCD 32 "Fernseher, Marmorbad, privaten Balkon und private Kaffee und Tee Einrichtungen: einzigartigen Blick auf das Ägäische Meer, Wohnbereich, Sheraton Sweet Sleeper Bett (Kingsize), Markentoiletten , Bademäntel und Hausschuhe.</p>'),
(67, 23, 'en', 'Single Room', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet.</p>', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet. Very nice and guest-friendly room.</p>'),
(68, 23, 'es', 'Single Room', '<p>Esta habitación es más pequeña en tamaño, confort como habitaciones estándar. con capacidad para un máximo de 1 persona. (cama individual). Las habitaciones están ubicadas en el sexto piso del hotel y han renovado con una decoración y un diseño moderno. Habitaciones individuales están equipadas con té &amp; amp; café y una nevera. WiFi gratuito y conexión a internet por cable.</p>', '<p>Esta habitación es más pequeña en tamaño, confort como habitaciones estándar. con capacidad para un máximo de 1 persona. (cama individual). Las habitaciones están ubicadas en el sexto piso del hotel y han renovado con una decoración y un diseño moderno. Habitaciones individuales están equipadas con té &amp; amp; café y una nevera. WiFi gratuito y conexión a internet por cable. Muy agradable y de fácil uso habitación.</p>'),
(69, 23, 'de', 'Single Room', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet.</p>', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet. Very nice and guest-friendly room.</p>'),
(70, 24, 'en', 'Suite', '<p>Each Suite room includes one double bed, bedlinnen, 2 LCD TV''s with satellite cable channels and remote control, fully stocked mini-bar, IDD telephone, towels, shower gels, soap and shampoo. Shower and bathtub.</p>', '<p>Each Suite room includes one double bed, bedlinnen, 2 LCD TV''s with satellite cable channels and remote control, fully stocked mini-bar, IDD telephone, towels, shower gels, soap and shampoo. Shower and bathtub.   <br /><br /> One TV is located in the bedroom, the other one in the dining/living room. There is also a kitchenette, dining table with three chairs, and you can use the Hair Dryer, and inroom safe free of charge, and each of our rooms offer two bottles of water free of charge with a water heating machine and tea and coffee assortment.   <br /><br /> WIFI is available in the room at a small fee and a password can be arranged at the lobby. Each room has a room service menu where you can order any dish you like.</p>'),
(71, 24, 'es', 'Suite', '<p>Cada habitación Suite incluye una cama doble, sabanas, 2 TV LCD con canales por cable vía satélite y control remoto, mini-bar completamente equipado, teléfono directo, toallas, gel de ducha, jabón y champú. Ducha y bañera.</p>', '<p>Cada habitación Suite incluye una cama doble, sabanas, 2 TV LCD con canales por cable vía satélite y control remoto, mini-bar completamente equipado, teléfono directo, toallas, gel de ducha, jabón y champú. Ducha y bañera. <br /> <br /> Una TV se encuentra en el dormitorio, el otro en el comedor / sala de estar. También hay una zona de cocina, mesa de comedor con tres sillas, y se puede utilizar el secador de pelo, y inroom seguro de forma gratuita, y cada una de nuestras habitaciones ofrecen dos botellas de agua gratis con una máquina de calentamiento de agua y té y café surtido . <br /> <br /> WIFI está disponible en la habitación por una pequeña cuota y una contraseña puede ser organizado en el vestíbulo. Cada habitación cuenta con un servicio de habitaciones donde se puede pedir cualquier plato que desee.</p>'),
(72, 24, 'de', 'Suite', '<p>Jede Suite Zimmer ist mit einem Doppelbett, Bettwäsche, 2 LCD-Fernseher mit Sat-Kabel-TV und Fernbedienung, gut bestückte Minibar, IDD-Telefon, Handtücher, Duschgel, Seife und Shampoo. Dusche und Badewanne.</p>', '<p>Jede Suite Zimmer ist mit einem Doppelbett, Bettwäsche, 2 LCD-Fernseher mit Sat-Kabel-TV und Fernbedienung, gut bestückte Minibar, IDD-Telefon, Handtücher, Duschgel, Seife und Shampoo. Dusche und Badewanne. <br /> <br /> Ein TV ist im Schlafzimmer, die andere im Wohn / Esszimmer. Es gibt auch eine Küchenzeile, Esstisch mit drei Stühlen, und Sie können den Föhn zu benutzen, und Safe im Zimmer kostenlos, und jedes der Zimmer bieten zwei Flaschen Wasser kostenlos mit Wasser-Heizung-Maschine und Tee-und Kaffeesortiment . <br /> <br /> WLAN ist gegen eine geringe Gebühr zur Verfügung im Zimmer und ein Passwort können Sie in der Lobby organisiert werden. Jedes Zimmer hat ein Zimmerservice-Menü, in dem Sie jedes Gericht Sie bestellen.</p>'),
(73, 25, 'en', 'Family Junior Suite', '<p>The ideal suite for enjoying vacations with all the family! Spacious suite measuring 42 m2 with lovely views of the gardens or pool area. All the Family Deluxe Junior Suites come with king size bed or two double beds on request on arrival at the hotel, plus a sofa-bed and a rollaway bed or bunk beds.</p>', '<p>The ideal suite for enjoying vacations with all the family! Spacious suite measuring 42 m2 with lovely views of the gardens or pool area. All the Family Deluxe Junior Suites come with king size bed or two double beds on request on arrival at the hotel, plus a sofa-bed and a rollaway bed or bunk beds. <br /><br /> For greater fun and additional comfort, the suite includes children’s bed linen, a dividing curtain for extra privacy, and the bathroom has special children’s amenities, such as a little step to reach the sink. <br /><br /> All the suites have sliding glass doors which lead onto the private terrace or balcony and allow greater natural light in suites which are ideal for enjoying with all the family.</p>'),
(74, 25, 'es', 'Junior Suite Familiar', '<p>La suite ideal para disfrutar de unas vacaciones con toda la familia! Amplia suite medir 42 m2 con preciosas vistas a los jardines oa la piscina. Toda la Deluxe Junior Suite Family cuentan con cama king size o dos camas dobles bajo petición a la llegada al hotel, además de un sofá-cama y una cama supletoria o literas.</p>', '<p>La suite ideal para disfrutar de unas vacaciones con toda la familia! Amplia suite medir 42 m2 con preciosas vistas a los jardines oa la piscina. Toda la Deluxe Junior Suite Family cuentan con cama king size o dos camas dobles bajo petición a la llegada al hotel, además de un sofá-cama y una cama supletoria o literas. <br /> <br /> Para mayor diversión y comodidad, la suite incluye ropa de cama de los niños, una cortina divisoria para mayor privacidad, y el baño tiene instalaciones especiales para los niños, como un pequeño paso para llegar al lavabo. <br /> <br /> Todas las suites tienen puertas corredizas de vidrio que dan a la terraza o balcón privado y permiten una mayor luz natural en las suites, que son ideales para disfrutar con toda la familia.</p>'),
(75, 25, 'de', 'Junior Suite für Familien', '<p>Die ideale Suite für die Ferien genießen mit der ganzen Familie! Geräumige Suite Messung 42 m2 mit herrlichem Blick auf den Garten oder den Poolbereich. Die ganze Familie Deluxe Junior Suiten sind mit Kingsize-Bett oder zwei Doppelbetten auf Anfrage bei der Ankunft im Hotel sowie ein Schlafsofa und ein Rollbett oder Etagenbett.</p>', '<p>Die ideale Suite für die Ferien genießen mit der ganzen Familie! Geräumige Suite Messung 42 m2 mit herrlichem Blick auf den Garten oder den Poolbereich. Die ganze Familie Deluxe Junior Suiten sind mit Kingsize-Bett oder zwei Doppelbetten auf Anfrage bei der Ankunft im Hotel sowie ein Schlafsofa und ein Rollbett oder Etagenbett. <br /> <br /> Für mehr Spaß und zusätzliche Komfortmerkmal dieser Suite Kinderbettwäsche, eine Trennvorhang für mehr Privatsphäre, und das Badezimmer verfügt über spezielle Kinderausstattung, wie ein kleiner Schritt, um das Waschbecken zu erreichen. <br /> <br /> Alle Suiten haben Glas-Schiebe-Türen, die auf der Terrasse oder einen Balkon führen und eine größere natürliche Licht in den Suiten, die ideal für den Genuss mit der ganzen Familie sind.</p>'),
(76, 26, 'en', 'Standard Twin Room', '<p>Enjoy in the view of our city Square that will inspire you to start a new adventure. No matter if you are business or tourist traveler this accommodation will settle all your needs. Standard Twin Room features two single beds, work desk with high-speed internet, LCD TV, mini bar and safe box. The bathroom has Jacuzzi bathtub with superb equipment and exclusive amenities.</p>', '<p>Enjoy in the view of our city Square that will inspire you to start a new adventure. No matter if you are business or tourist traveler this accommodation will settle all your needs. Standard Twin Room features two single beds, work desk with high-speed internet, LCD TV, mini bar and safe box. The bathroom has Jacuzzi bathtub with superb equipment and exclusive amenities.</p>'),
(77, 26, 'es', 'Standard Twin Room', '<p>Disfrute de la vista de nuestra ciudad la plaza que le inspirará para iniciar una nueva aventura. No importa si usted es de negocios o turista que viaja este alojamiento resolverá todas sus necesidades. Habitación Doble Estándar con dos camas individuales, escritorio con conexión a internet de alta velocidad, TV LCD, minibar y caja de seguridad. El baño tiene bañera de hidromasaje con equipamiento excelente y comodidades exclusivas.</p>', '<p>Disfrute de la vista de nuestra ciudad la plaza que le inspirará para iniciar una nueva aventura. No importa si usted es de negocios o turista que viaja este alojamiento resolverá todas sus necesidades. Habitación Doble Estándar con dos camas individuales, escritorio con conexión a internet de alta velocidad, TV LCD, minibar y caja de seguridad. El baño tiene bañera de hidromasaje con equipamiento excelente y comodidades exclusivas.</p>'),
(78, 26, 'de', 'Standard Twin Room', '<p>Genießen Sie in der Ansicht der Stadt-Platz, die Sie begeistern wird, ein neues Abenteuer zu starten. Egal, ob Sie einen Geschäfts- und Urlaubsreis dieser Unterkunft wird alle Ihre Bedürfnisse zu begleichen. Standard-Doppelzimmer mit zwei Einzelbetten, Schreibtisch mit High-Speed-Internetzugang, LCD-TV, Minibar und Safe. Das Badezimmer ist mit Jacuzzi-Badewanne mit hervorragenden Ausstattung und exklusiven Annehmlichkeiten.</p>', '<p>Genießen Sie in der Ansicht der Stadt-Platz, die Sie begeistern wird, ein neues Abenteuer zu starten. Egal, ob Sie einen Geschäfts- und Urlaubsreis dieser Unterkunft wird alle Ihre Bedürfnisse zu begleichen. Standard-Doppelzimmer mit zwei Einzelbetten, Schreibtisch mit High-Speed-Internetzugang, LCD-TV, Minibar und Safe. Das Badezimmer ist mit Jacuzzi-Badewanne mit hervorragenden Ausstattung und exklusiven Annehmlichkeiten.</p>'),
(79, 27, 'en', 'Suite with City View', '<p>Enjoy a luxury  hotel with our standard living space and elegance fit with floor-to-ceiling city views of the skyline and surrounding mountains. Relax on your luxurious sofa or entertain in your modern dining room. Show off your culinary skills in your European-style kitchen with top-notch appliances. Do it all during the best hotel stay you will ever have.</p>', '<p>Enjoy a luxury  hotel with our standard living space and elegance fit with floor-to-ceiling city views of the skyline and surrounding mountains. Relax on your luxurious sofa or entertain in your modern dining room. Show off your culinary skills in your European-style kitchen with top-notch appliances. Do it all during the best hotel stay you will ever have.</p>'),
(80, 27, 'es', 'Suite with City View', '<p>Disfrute de un hotel de lujo con nuestro espacio de vida estándar y elegancia en forma con vistas de piso a techo de la ciudad de los rascacielos y las montañas circundantes. Relájese en su sofá de lujo o entretener en su moderno comedor. Demuestra tus habilidades culinarias en la cocina de estilo europeo con electrodomésticos de primera categoría. Hacerlo todo en la mejor estancia de hotel que usted tendrá siempre.</p>', '<p>Disfrute de un hotel de lujo con nuestro espacio de vida estándar y elegancia en forma con vistas de piso a techo de la ciudad de los rascacielos y las montañas circundantes. Relájese en su sofá de lujo o entretener en su moderno comedor. Demuestra tus habilidades culinarias en la cocina de estilo europeo con electrodomésticos de primera categoría. Hacerlo todo en la mejor estancia de hotel que usted tendrá siempre.</p>'),
(81, 27, 'de', 'Suite with City View', '<p>Genießen Sie ein Luxus-Hotel mit unserer Standard-Wohnraum und Eleganz fit mit vom Boden bis zur Decke reichenden Stadt Blick auf die Skyline und die umliegenden Berge. Entspannen Sie auf Ihrem luxuriösen Sofa oder unterhalten in der modernen Speisesaal. Zeigen Sie Ihre kulinarischen Fähigkeiten in Ihrer europäischen Stil Küche mit erstklassigen Geräten. Haben sie alle in der besten Hotelaufenthalt du je haben wirst.</p>', '<p>Genießen Sie ein Luxus-Hotel mit unserer Standard-Wohnraum und Eleganz fit mit vom Boden bis zur Decke reichenden Stadt Blick auf die Skyline und die umliegenden Berge. Entspannen Sie auf Ihrem luxuriösen Sofa oder unterhalten in der modernen Speisesaal. Zeigen Sie Ihre kulinarischen Fähigkeiten in Ihrer europäischen Stil Küche mit erstklassigen Geräten. Haben sie alle in der besten Hotelaufenthalt du je haben wirst.</p>'),
(82, 28, 'en', 'Standard Double Room with Balcony', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel.</p>', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel, direct dial telephone, bathrobe &amp; slippers, beach towels, pillow ion, hairdryer, light Mini Bar (at an extra charge), a safe, and manually operated air conditioning which is centrally controlled.</p>'),
(83, 28, 'es', 'Standard Double Room with Balcony', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel.</p>', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel, direct dial telephone, bathrobe &amp; slippers, beach towels, pillow ion, hairdryer, light Mini Bar (at an extra charge), a safe, and manually operated air conditioning which is centrally controlled.</p>'),
(84, 28, 'de', 'Standard Double Room with Balcony', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel.</p>', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel, direct dial telephone, bathrobe &amp; slippers, beach towels, pillow ion, hairdryer, light Mini Bar (at an extra charge), a safe, and manually operated air conditioning which is centrally controlled.</p>'),
(85, 29, 'en', 'Superior King Room', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>'),
(86, 29, 'es', 'Superior King Room', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>'),
(87, 29, 'de', 'Superior King Room', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>'),
(88, 30, 'en', 'Superior Double Room', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>'),
(89, 30, 'es', 'Superior Double Room', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>'),
(90, 30, 'de', 'Superior Double Room', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>'),
(91, 31, 'en', 'Deluxe Two Queen Non-Smoking', '<p>Inviting and innovative, this non-smoking 350-square-foot GO King room features sleek, modern furniture and tech-savvy accessories including electronic window treatments, a 42-inch flat-screen TV and wireless internet (for a fee). The bathrooms come with stylish frosted glass walls and doors, built-in TVs in mirrors and luxurious bath amenities.</p>', '<p>Inviting and innovative, this non-smoking 350-square-foot GO King room features sleek, modern furniture and tech-savvy accessories including electronic window treatments, a 42-inch flat-screen TV and wireless internet (for a fee). The bathrooms come with stylish frosted glass walls and doors, built-in TVs in mirrors and luxurious bath amenities. Bathrooms include walk-in showers, but rooms with tubs are also available by request.</p>'),
(92, 31, 'es', 'Deluxe Two Queen Non-Smoking', '<p>Invitando e innovadora, esta no fumadores 350 metros cuadrados, sala de GO Rey cuenta con mobiliario elegante y moderno y accesorios de expertos en tecnología que incluye tratamientos de la ventana, equipos de TV de pantalla plana de 42 pulgadas y conexión inalámbrica a Internet (de pago). Los cuartos de baño con paredes de cristal esmerilado y elegantes puertas, televisores integrados en los espejos y baño de lujo.</p>', '<p>Invitando e innovadora, esta no fumadores 350 metros cuadrados, sala de GO Rey cuenta con mobiliario elegante y moderno y accesorios de expertos en tecnología que incluye tratamientos de la ventana, equipos de TV de pantalla plana de 42 pulgadas y conexión inalámbrica a Internet (de pago). Los cuartos de baño con paredes de cristal esmerilado y elegantes puertas, televisores integrados en los espejos y baño de lujo. Baños están equipados con duchas, pero las habitaciones con bañeras también están disponibles a pedido.</p>'),
(93, 31, 'de', 'Deluxe Two Queen Non-Smoking', '<p>Einladend und innovative, dieses Nichtraucher-350-square-foot GO König Zimmer verfügt über elegante, moderne Möbel und technisch versierte Zubehör einschließlich elektronischer Fenster Behandlungen, einem 42-Zoll-Flachbild-TV und WLAN-Internetzugang (gegen Gebühr). Die Badezimmer sind mit stilvollen Milchglaswänden und Türen, eingebauten Fernseher im Spiegel und luxuriöse Toilettenartikel. Die Bäder sind wie begehbare Duschen.</p>', '<p>Einladend und innovative, dieses Nichtraucher-350-square-foot GO König Zimmer verfügt über elegante, moderne Möbel und technisch versierte Zubehör einschließlich elektronischer Fenster Behandlungen, einem 42-Zoll-Flachbild-TV und WLAN-Internetzugang (gegen Gebühr). Die Badezimmer sind mit stilvollen Milchglaswänden und Türen, eingebauten Fernseher im Spiegel und luxuriöse Toilettenartikel. Die Bäder sind wie begehbare Duschen, aber die Zimmer mit Badewanne sind auf Anfrage erhältlich.</p>'),
(94, 32, 'en', 'Neapolitan King Suite ', '<p>Neapolitan King Suite</p>', '<p>Neapolitan King Suite</p>'),
(95, 32, 'es', 'Neapolitan King Suite ', '<p>Neapolitan King Suite</p>', '<p>Neapolitan King Suite</p>'),
(96, 32, 'de', 'Neapolitan King Suite ', '<p>Neapolitan King Suite</p>', '<p>Neapolitan King Suite</p>'),
(97, 33, 'en', 'Business Suite', '<p>Business Suite stands for business hedonism. Here, a remarkable bedroom is complemented with spacious up to date equipped office. The office can be transformed into a grandiose living room with eye appealing, leather pull out sofa, which gives to the room a warm but homey atmosphere.</p>', '<p>Business Suite stands for business hedonism. Here, a remarkable bedroom is complemented with spacious up to date equipped office. The office can be transformed into a grandiose living room with eye appealing, leather pull out sofa, which gives to the room a warm but homey atmosphere. The bathroom is an astonishing side dish in this perfect meal, perfectly equipped, soothing and roomy.</p>'),
(98, 33, 'es', 'Business Suite', '<p>Business Suite significa hedonismo negocio. Aquí, un dormitorio notable se complementa con una amplia hasta la fecha equipado oficina. La oficina se puede transformar en una sala de estar grandioso con ojo atractivo, cuero sofá, lo que da a la habitación un ambiente cálido pero acogedor.</p>', '<p>Business Suite significa hedonismo negocio. Aquí, un dormitorio notable se complementa con una amplia hasta la fecha equipado oficina. La oficina se puede transformar en una sala de estar grandioso con ojo atractivo, cuero sofá, lo que da a la habitación un ambiente cálido pero acogedor. El cuarto de baño es un plato sorprendente en esta comida perfecta, perfectamente equipada, relajante y espacioso.</p>'),
(99, 33, 'de', 'Business Suite', '<p>Business Suite steht für Business-Hedonismus. Hier wird eine bemerkenswerte Schlafzimmer mit geräumigen aktuell ausgestatteten Büro ergänzt. Das Büro kann in eine grandiose Wohnzimmer mit Auge ansprechend, Lederschlafsofa, das in den Raum eine warme, aber gemütliche Atmosphäre verleiht umgewandelt werden.</p>', '<p>Business Suite steht für Business-Hedonismus. Hier wird eine bemerkenswerte Schlafzimmer mit geräumigen aktuell ausgestatteten Büro ergänzt. Das Büro kann in eine grandiose Wohnzimmer mit Auge ansprechend, Lederschlafsofa, das in den Raum eine warme, aber gemütliche Atmosphäre verleiht umgewandelt werden. Das Badezimmer ist eine erstaunliche Beilage in diesem perfekte Mahlzeit, perfekt ausgestattet, beruhigend und geräumig.</p>'),
(100, 34, 'en', 'Superior Double Room', '<p>We like 30 hour days and deciding when the sun should rise. That’s why all Double Superior rooms in The Ushuaïa Club have blackout curtains. And free WiFi, so you can share instantly. Because time and space are relative and you control them. Who has lived the Ushuaïa experience knows this. Memories can be quite fuzzy.</p>', '<p>We like 30 hour days and deciding when the sun should rise. That’s why all Double Superior rooms in The Ushuaïa Club have blackout curtains. And free WiFi, so you can share instantly. Because time and space are relative and you control them. Who has lived the Ushuaïa experience knows this.</p>\r\n<p>Memories can be quite fuzzy.  Especially the ones from the last party. That’s why our Double Superior rooms have solid amenities: a maxi-bar, aromatherapy menu, sensual shower, designer furniture, bathroom amenities and color therapy system. And with its ample terrace, you can enjoy the party at your own pace. Luxury. Exclusivity. Technology. Vanguard. At the heart of the best daytime party in Ibiza. Pure Ushuaïa spirit.</p>'),
(101, 34, 'es', 'Superior Double Room', '<p>Nos gusta 30 horas al día y decidir cuando el sol se levante. Es por eso que todas las habitaciones doble superior en el Ushuaïa club tienen cortinas opacas. Y WiFi gratis, para que puedas compartir al instante. Porque el tiempo y el espacio son relativos y que ellos controlan. Que ha vivido la experiencia Ushuaïa sabe. Los recuerdos pueden ser bastante difusa.</p>', '<p>Nos gusta 30 horas al día y decidir cuando el sol se levante. Es por eso que todas las habitaciones doble superior en el Ushuaïa club tienen cortinas opacas. Y WiFi gratis, para que puedas compartir al instante. Porque el tiempo y el espacio son relativos y que ellos controlan. Que ha vivido la experiencia Ushuaïa sabe. Los recuerdos pueden ser bastante difusa.</p>\r\n<p>Especialmente los de la última fiesta. Es por eso que nuestras habitaciones dobles superiores tienen instalaciones sólidas: un maxi-bar, menú de aromaterapia, ducha sensual, muebles de diseño, artículos de aseo y sistema de cromoterapia. Y con su amplia terraza, se puede disfrutar de la fiesta a su propio ritmo. Lujo. La exclusividad. Technology. Vanguard. En el corazón de la mejor fiesta de día en Ibiza. Puro espíritu Ushuaïa.</p>'),
(102, 34, 'de', 'Superior Double Room', '<p>Wir möchten 30 Stunden Tag und zu entscheiden, wenn die Sonne sollte steigen. Deshalb werden alle Doppelzimmer Superior Zimmer in Ushuaia Verein haben Verdunklungsvorhänge. Und kostenlosem WLAN, so dass Sie sofort teilen können. Weil Zeit und Raum sind relativ und Sie sie zu kontrollieren. Wer verschenkt den Ushuaïa Erfahrung gelebt weiß dies. Erinnerungen können sehr unscharf sein.</p>', '<p>Wir möchten 30 Stunden Tag und zu entscheiden, wenn die Sonne sollte steigen. Deshalb werden alle Doppelzimmer Superior Zimmer in Ushuaia Verein haben Verdunklungsvorhänge. Und kostenlosem WLAN, so dass Sie sofort teilen können. Weil Zeit und Raum sind relativ und Sie sie zu kontrollieren. Wer verschenkt den Ushuaïa Erfahrung gelebt weiß dies.</p>\r\n<p>Erinnerungen können sehr unscharf sein.  Besonders die, von der letzten Party. Deshalb sind unsere Doppelzimmer Superior Zimmer verfügen über feste Einrichtungen: eine Maxi-Bar, ein Aromatherapie-Menü, sinnlich Dusche, Designer-Möbel, im Bad und Farbtherapie-System. Und mit seiner großen Terrasse, können Sie sich die Partei in Ihrem eigenen Tempo zu genießen. Luxus. Exklusivität. Technologie. Vanguard. Im Herzen der besten Tagesparty auf Ibiza. Reine Ushuaïa Geist.</p>'),
(103, 35, 'en', 'Single Room', '<p>An elegant room featuring a king size bed or twin beds offers individually controlled air-conditioning, bathroom with shower, hairdryer, cable TV, direct dial telephone, mini-bar and free WiFi Internet access. Single rooms feature modern amenities and a comfortable environment. The size of the rooms varies between 19-21m2.</p>', '<p>An elegant room featuring a king size bed or twin beds offers individually controlled air-conditioning, bathroom with shower, hairdryer, cable TV, direct dial telephone, mini-bar and free WiFi Internet access. Single rooms feature modern amenities and a comfortable environment. The size of the rooms varies between 19-21m2.</p>'),
(104, 35, 'es', 'Single Room', '<p>Habitación elegante con una cama king size o dos camas individuales ofrece control individual de aire acondicionado, cuarto de baño con ducha, secador de pelo, TV por cable, teléfono de línea directa, minibar y acceso a Internet WiFi gratuito. Habitaciones individuales cuentan con las comodidades modernas y un ambiente confortable. El tamaño de las habitaciones varía entre 19-21m2.</p>', '<p>Habitación elegante con una cama king size o dos camas individuales ofrece control individual de aire acondicionado, cuarto de baño con ducha, secador de pelo, TV por cable, teléfono de línea directa, minibar y acceso a Internet WiFi gratuito. Habitaciones individuales cuentan con las comodidades modernas y un ambiente confortable. El tamaño de las habitaciones varía entre 19-21m2.</p>'),
(105, 35, 'de', 'Single Room', '<p>Ein elegantes Zimmer mit einem Kingsize-Bett oder zwei Einzelbetten verfügt über individuell regulierbare Klimaanlage, Bad mit Dusche, Fön, Kabel-TV, Direktwahltelefon, Minibar und kostenlosem WLAN-Internetzugang. Einzelzimmer verfügen über moderne Annehmlichkeiten und eine komfortable Umgebung. Die Größe der Zimmer variiert zwischen 19-21m2.</p>', '<p>Ein elegantes Zimmer mit einem Kingsize-Bett oder zwei Einzelbetten verfügt über individuell regulierbare Klimaanlage, Bad mit Dusche, Fön, Kabel-TV, Direktwahltelefon, Minibar und kostenlosem WLAN-Internetzugang. Einzelzimmer verfügen über moderne Annehmlichkeiten und eine komfortable Umgebung. Die Größe der Zimmer variiert zwischen 19-21m2.</p>'),
(106, 1, 'ar', 'Single', '<p>Rooms measuring 15 m² equipped with all the details expected of a superior 4 star hotel. Services: Wake up call service, Customer service, Laundry service and express laundry, Concierge service, Pillow menu.</p>', '<p><strong>Description:</strong><br />Rooms measuring 15 m² equipped with all the details expected of a superior 4 star hotel.</p>\r\n<p><strong>Services: </strong>\r\n<ul class="services">\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul></p>'),
(107, 2, 'ar', 'Double', '<p>Modern and functional rooms measuring approximately 20-25 m² equipped with all the details expected of the hotel. The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres ideal for sports teams.</p>', '<p><strong>Description</strong>:<br />Modern and functional rooms measuring approximately 20-25 m² equipped with all the details expected of the hotel. <br /><br />The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 meters ideal for sports teams and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).<br /><br /><strong>Services</strong>:\r\n<ul class="services">\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul></p>'),
(108, 3, 'ar', 'Superior', '<p>Spacious rooms with exquisite decor, measuring approximately 25-30 m&sup2; and equipped with all the details expected of the hotel hotel. The rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres.</p>', '<p><strong>Description</strong>:\r\n<br />\r\nSpacious rooms with exquisite decor, measuring approximately 25-30 m² and equipped with all the details expected of the hotel hotel.\r\n<br /><br />\r\nThe rooms have a king or queen size bed or two single beds, in addition to beds measuring 1 by 2.2 metres ideal for sports teams and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).\r\n<br /><br />\r\n<strong>Services</strong>:\r\n<ul class="services">\r\n<li>24 hour room service</li>\r\n<li>Wake up call service</li>\r\n<li>Serviexpress customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n</ul>\r\n</p>'),
(109, 4, 'ar', 'Luxury', '<p>Spacious rooms with exquisite decor measuring approximately 25-30 m&sup2; and equipped with all the details expected of a superior 4 star Hotel. The rooms have a king or queen size bed or two single beds, and views of the streets.</p>', '<p><strong>Description</strong>:\r\n<br />\r\nSpacious rooms with exquisite decor measuring approximately 25-30 m² and equipped with all the details expected of a superior 4 star Hotel.\r\n<br /><br />\r\nThe rooms have a king or queen size bed or two single beds, and views of the streets of the quiet interior patios (request availability upon arrival at the hotel).\r\n<br /><br />\r\n<strong>Services</strong>:\r\n<br />\r\n<ul class="services">\r\n<li>Private reception located on the 6th floor</li>\r\n<li>Welcome courtesy replaced daily</li>\r\n<li>Buffet breakfast in private room between 7am and 11am</li>\r\n<li>Free Open Bar available on the Luxury Service floor, from 16:30 to 22:30</li>\r\n<li>24 hour room service</li>\r\n<li>10% discount on lunches and dinners at our Diábolo restaurant, after consultation and booking at the Royal Service reception and subject to availability</li>\r\n<li>Free 30 minute use per stay of computers in the Business Centre (hall), including printer and 25 photocopies</li>\r\n<li>Free 8 minute Ultra Violet Ray session per stay</li>\r\n<li>Wake up call service</li>\r\n<li>Customer service</li>\r\n<li>Laundry service and express laundry</li>\r\n<li>Concierge service</li>\r\n<li>Pillow menu</li>\r\n<li>Turn down service</li>\r\n</ul>\r\n* The Luxury Service is closed from Friday at 12:00 until Sunday at 15:00.\r\n</p>'),
(110, 5, 'ar', 'Standard Room', '<p>Relax in our standard room, complete with two queen size beds, customized furniture, gel-infused pillow top mattresses topped with luxurious duvets and duvet covers clean for every guest.</p>', '<p>Relax in our standard room, complete with two queen size beds, customized furniture, gel-infused pillow top mattresses topped with luxurious duvets and duvet covers clean for every guest, flat screen TV, mini-fridge, executive desk, wireless internet, all tastefully decorated with climate control at your fingertips. Exercise in our state of the art fitness facility, swim in our heated indoor swimming pool or relax in our sauna, all free of cost for our guests.</p>'),
(111, 6, 'ar', 'Double Room with Two Double Beds', '<p>A standard hotel room is an elongated hotel room designed for two people, though some standard doubles can accommodate up to four. The standard double hotel room is available at many full-service hotels, with the exclusion of facilities that house only suites or extended-stay guests.</p>', '<p>A standard hotel room is an elongated hotel room designed for two people, though some standard doubles can accommodate up to four. The standard double hotel room is available at many full-service hotels, with the exclusion of facilities that house only suites or extended-stay guests. The standard double room is ideal for a brief stay of up to a few days. It doesn''t contain a kitchen, so guests can''t cook their own meals.</p>');
INSERT INTO `uhb289_rooms_description` (`id`, `room_id`, `language_id`, `room_type`, `room_short_description`, `room_long_description`) VALUES
(112, 7, 'ar', 'Junior Suite', '<p>Our spacious Junior hotel Suites are 460 square feet (43 square meters) featuring floor-to-ceiling windows overlooking Manhattan from our New York City hotel suites. Junior Suites offer luxurious king beds, 55-inch flat-panel HDTV with Blu-ray player and iPod docking station, marble baths, and a large walk-in closet.</p>', '<p>Our spacious Junior hotel Suites are 460 square feet (43 square meters) featuring floor-to-ceiling windows overlooking Manhattan from our New York City hotel suites. Junior Suites offer luxurious king beds, 55-inch flat-panel HDTV with Blu-ray player and iPod docking station, marble baths, and a large walk-in closet.<br /> For your comfort and convenience, most also include a fully equipped European-style kitchen with appliances by Sub-Zero, and a sitting area with a twin-size sofa bed. All of our New York hotel guests enjoy full access to our health club and spa.</p>'),
(113, 8, 'ar', 'Executive Double Room', '<p>Stunning Executive Double bedrooms provide the perfect setting in the heart of NY. Exclusive features you won’t find in Double Cumberland Guest rooms include luxurious bathrobes and slippers, complimentary mineral water and full access to the Guoman Club Lounge with complimentary newspapers and refreshments available all day.</p>', '<p>Stunning Executive Double bedrooms provide the perfect setting in the heart of NY. Exclusive features you won’t find in Double Cumberland Guest rooms include luxurious bathrobes and slippers, complimentary mineral water and full access to the Guoman Club Lounge with complimentary newspapers and refreshments available all day.</p>\r\n<p>As you would expect from Guoman, all our 50 Executive Double bedrooms also benefit from fast, complimentary BT Wi-fi and entertainment at your fingertips with a 32-inch LCD TV. You’ll appreciate extra space to unwind and recharge for the day ahead with beautifully designed bathrooms featuring walk-in power showers and mist-free mirrors. Welcome details that provide an oasis of calm in the centre of London.</p>'),
(114, 9, 'ar', 'Junior Suite', '<p>These comfortable suites are ideal for guests looking for a little extra space. Featuring sumptuous carpets and gold silk curtains throughout, the large living area has a three-seater sofa, choice of beautifully upholstered armchairs and a dark wood coffee table, making it the perfect space for working, entertaining or relaxing. The bedroom area is a private retreat with king beds and large windows. Fashioned from black and white marble, bathrooms feature chequered floors and abstract artwork.</p>', '<p>These comfortable suites are ideal for guests looking for a little extra space. Featuring sumptuous carpets and gold silk curtains throughout, the large living area has a three-seater sofa, choice of beautifully upholstered armchairs and a dark wood coffee table, making it the perfect space for working, entertaining or relaxing. The bedroom area is a private retreat with king beds and large windows. Fashioned from black and white marble, bathrooms feature chequered floors and abstract artwork.</p>'),
(115, 10, 'ar', 'Super Deluxe', '<p>Our Superior Rooms feature a Double bed or 2 Single beds as required by our guests, we also offer zip and link beds.  The size of the room varies from 17 to 20 Sq. Meters.  Below is a list of room features and amenities that adorn the room to make your stay more enjoyable.</p>', '<p>Our Superior Rooms feature a Double bed or 2 Single beds as required by our guests, we also offer zip and link beds.  The size of the room varies from 17 to 20 Sq. Meters.  Below is a list of room features and amenities that adorn the room to make your stay more enjoyable.</p>'),
(116, 11, 'ar', 'Standard Double Room', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or etc.</p>', '<p>This room has a flat-screen satellite TV, air conditioning, coffee machine and a minibar. The private bathroom provides a hairdryer and bathrobes.  Room Facilities: Safe, Air conditioning, Desk, Heating, Soundproof, Hardwood/Parquet floors, Wardrobe/Closet, Hairdryer, Bathrobe, Free toiletries, Toilet, Bathroom, Slippers, Bathtub or shower, Telephone, Radio, Satellite channels, Laptop safe, Flat-screen TV, Minibar, Coffee machine, Wake-up service, Alarm clock, Towels, Linens  Free WiFi is available in all rooms.</p>'),
(117, 12, 'ar', 'Basic Double Room', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby.</p>', '<p>xcellent for couples looking for cheap hotel accommodation when enjoying a romantic evening out in our city or an extended stay in the Capital. Located near Hackney, Islington and Shoreditch we are in a great location to access many popular attractions nearby and our highly accessible transport options will get you into the heart of our city within minutes!</p>\r\n<p>Don''t forget to download and print your complimentary holiday packing list from the right-hand side!</p>'),
(118, 13, 'ar', 'Business Twin Room', '<p>The large windows in these generously spacious 26 square metre rooms  provide a sense of openness and executive charm. Designed with a sense  of exacting details to meet the combined productive and relaxation needs  of guests travelling on business.</p>', '<p>The large windows in these generously spacious 26 square metre rooms  provide a sense of openness and executive charm. Designed with a sense  of exacting details to meet the combined productive and relaxation needs  of guests travelling on business, each room is furnished with a large  desk and LAN access, and easy chairs to just unwind. The layout though  simple, exudes a sense of freshness and cleanliness.</p>'),
(119, 14, 'ar', 'Suite', '<p>A suite in a hotel or other public accommodation denotes a class of accommodations with more space than a typical hotel room.</p>', '<p>A suite in a hotel or other public accommodation denotes a class of accommodations with more space than a typical hotel room.  In luxury or upscale accommodations, such as Ritz Carlton, Marriott, or Embassy Suites, key features may include multiple rooms. Many independent properties have one or more honeymoon suites, and sometimes the best accommodation at a high-end hotel is called the presidential suite or royal suite.</p>'),
(120, 15, 'ar', 'Grand Sea View Room', '<p>Welcome to this contemporary room offering an amazing sea view, a balcony, work area and marble bathroom. Catch up on work at the desk or check your emails with complimentary internet access.</p>', '<p>Welcome to this contemporary room offering an amazing sea view, a balcony, work area and marble bathroom. Catch up on work at the desk or check your emails with complimentary internet access. Special touches include daily newspapers delivery upon request and welcome amenities.</p>'),
(121, 16, 'ar', 'Family studio sea view', '<p>Studios have a walk in Shower &amp; separate bathtub, king-size or twin beds, individually controlled air conditioning / heating, satellite TV with pay movies, complimentary WiFi &amp; broadband internet connection, safe, mini-bar, coffee &amp; tea making facilities, baby monitoring service via the telephone.</p>', '<p>Studios have a walk in Shower &amp; separate bathtub, king-size or twin beds, individually controlled air conditioning / heating, satellite TV with pay movies, complimentary WiFi &amp; broadband internet connection, safe, mini-bar, coffee &amp; tea making facilities, baby monitoring service via the telephone.</p>\r\n<p>All rooms have balcony (Beach Studios have either balcony or terrace) with one table and two chairs and boast panoramic views of the blue Mediterranean Sea.</p>'),
(122, 17, 'ar', 'Superior Double Room', '<p>Classically beautiful and individually designed rooms from 20 sqm/215 sqf. All rooms contain a comfortable seating area and a modern workplace with a desk and comfy king-size bed. Some rooms have a fantastic waterfront view of the Royal Palace and Gasmla Stand, our old town.</p>', '<p>Sometimes you need a little more space. We offer a number of larger suites that can be expanded to up to five rooms by adding beautifully decorated parlours. The parlours come in two sizes – grand and grandiose.</p>\r\n<p>Classically beautiful and individually designed rooms from 20 sqm/215 sqf. All rooms contain a comfortable seating area and a modern workplace with a desk and comfy king-size bed. Some rooms have a fantastic waterfront view of the Royal Palace and Gasmla Stand, our old town.</p>'),
(123, 18, 'ar', 'Family Room', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>', '<p>Hotel offers several different types of family rooms. There are rooms with a double bed and a sofa bed for one person (80 cm) or two people (120 cm) and rooms with connecting doors so that several rooms can be linked for large families.</p>\r\n<p>All suites have a stunning waterfront view of the Royal Palace and Gamla Stan, Stockholm’s old town. The suites and parlours can be combined and fully tailored to meet your wishes and requirements. You can also hire an entire floor or two. Just get in touch and we’ll make the arrangements.</p>'),
(124, 19, 'ar', 'Comfort Double or Twin Room', '<p>Stay and relax in our modern and spacious double or twin room perfectly suited for business style. All the rooms have authentic and distinctive design, a comfortable king size or twin bed, armchairs with coffee table and an integral desk for ease of work.  The rooms are intended to accommodate one, maximum two persons.</p>', '<p>Stay and relax in our modern and spacious double or twin room perfectly suited for business style. All the rooms have authentic and distinctive design, a comfortable king size or twin bed, armchairs with coffee table and an integral desk for ease of work.  The rooms are intended to accommodate one, maximum two persons.</p>'),
(125, 20, 'ar', 'Junior Suite', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower.</p>', '<p>Junior Suites are large open plan suites with a bedroom and a spacious sitting area separated by an archway. The suites have beautiful natural light and are available with King or Twin beds.  The room features include an interactive flat screen TV, large writing desk, in-room safe, marble en-suite bathroom with bathtub and shower, Ren toiletries, bathrobes, slippers, self controlled air-conditioning unit and opening windows. We provide complimentary Wi-Fi and Water. All of our Suites have been newly refurbished in soothing pastille colours creating a relaxing luxurious space.  Can sleep up to 3 with an extra bed.</p>'),
(126, 21, 'ar', 'Twin Room', '<p>Twin rooms can accommodate up to two people in adjacent twin beds (90cm wide). Our twin rooms overlook the courtyard, ensuring the utmost peace and quiet for our guests. All twin rooms have an en-suite bathroom with bath and toilet.</p>', '<p>Twin rooms can accommodate up to two people in adjacent twin beds (90cm wide). Our twin rooms overlook the courtyard, ensuring the utmost peace and quiet for our guests. All twin rooms have an en-suite bathroom with bath and toilet.</p>\r\n<p>It also features a large window, with black out shutters, and shared bathroom facilities . Linen and towels are included in the price. This room can only be booked for minimum of 2 persons.</p>'),
(127, 22, 'ar', 'Junior Suite', '<p>The Jr. Suite at the Sheraton Rhodes Resort. Enjoy spacious and welcoming living area, flat screen LCD 32” television, marble bathroom, private furnished balcony and your private coffee &amp; tea facilities: unique view over the Aegean Sea, living area,     sheraton Sweet Sleeper Bed (king size), branded bathroom amenities, bathrobes &amp; slippers.</p>', '<p>The Jr. Suite at the Sheraton Rhodes Resort. Enjoy spacious and welcoming living area, flat screen LCD 32” television, marble bathroom, private furnished balcony and your private coffee &amp; tea facilities: unique view over the Aegean Sea, living area,     sheraton Sweet Sleeper Bed (king size), branded bathroom amenities, bathrobes &amp; slippers.</p>'),
(128, 23, 'ar', 'Single Room', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet.</p>', '<p>This room is smaller in size, comfort as standard rooms. can accommodate a maximum of 1 person. (single bed). The rooms are located at the six floor of the hotel and have completely renovated featuring modern decor and design. Single rooms are equipped with tea &amp; coffee making facilities and a fridge. Free WiFi and wired internet. Very nice and guest-friendly room.</p>'),
(129, 24, 'ar', 'Suite', '<p>Each Suite room includes one double bed, bedlinnen, 2 LCD TV''s with satellite cable channels and remote control, fully stocked mini-bar, IDD telephone, towels, shower gels, soap and shampoo. Shower and bathtub.</p>', '<p>Each Suite room includes one double bed, bedlinnen, 2 LCD TV''s with satellite cable channels and remote control, fully stocked mini-bar, IDD telephone, towels, shower gels, soap and shampoo. Shower and bathtub.   <br /><br /> One TV is located in the bedroom, the other one in the dining/living room. There is also a kitchenette, dining table with three chairs, and you can use the Hair Dryer, and inroom safe free of charge, and each of our rooms offer two bottles of water free of charge with a water heating machine and tea and coffee assortment.   <br /><br /> WIFI is available in the room at a small fee and a password can be arranged at the lobby. Each room has a room service menu where you can order any dish you like.</p>'),
(130, 25, 'ar', 'Family Junior Suite', '<p>The ideal suite for enjoying vacations with all the family! Spacious suite measuring 42 m2 with lovely views of the gardens or pool area. All the Family Deluxe Junior Suites come with king size bed or two double beds on request on arrival at the hotel, plus a sofa-bed and a rollaway bed or bunk beds.</p>', '<p>The ideal suite for enjoying vacations with all the family! Spacious suite measuring 42 m2 with lovely views of the gardens or pool area. All the Family Deluxe Junior Suites come with king size bed or two double beds on request on arrival at the hotel, plus a sofa-bed and a rollaway bed or bunk beds. <br /><br /> For greater fun and additional comfort, the suite includes children’s bed linen, a dividing curtain for extra privacy, and the bathroom has special children’s amenities, such as a little step to reach the sink. <br /><br /> All the suites have sliding glass doors which lead onto the private terrace or balcony and allow greater natural light in suites which are ideal for enjoying with all the family.</p>'),
(131, 26, 'ar', 'Standard Twin Room', '<p>Enjoy in the view of our city Square that will inspire you to start a new adventure. No matter if you are business or tourist traveler this accommodation will settle all your needs. Standard Twin Room features two single beds, work desk with high-speed internet, LCD TV, mini bar and safe box. The bathroom has Jacuzzi bathtub with superb equipment and exclusive amenities.</p>', '<p>Enjoy in the view of our city Square that will inspire you to start a new adventure. No matter if you are business or tourist traveler this accommodation will settle all your needs. Standard Twin Room features two single beds, work desk with high-speed internet, LCD TV, mini bar and safe box. The bathroom has Jacuzzi bathtub with superb equipment and exclusive amenities.</p>'),
(132, 27, 'ar', 'Suite with City View', '<p>Enjoy a luxury  hotel with our standard living space and elegance fit with floor-to-ceiling city views of the skyline and surrounding mountains. Relax on your luxurious sofa or entertain in your modern dining room. Show off your culinary skills in your European-style kitchen with top-notch appliances. Do it all during the best hotel stay you will ever have.</p>', '<p>Enjoy a luxury  hotel with our standard living space and elegance fit with floor-to-ceiling city views of the skyline and surrounding mountains. Relax on your luxurious sofa or entertain in your modern dining room. Show off your culinary skills in your European-style kitchen with top-notch appliances. Do it all during the best hotel stay you will ever have.</p>'),
(133, 28, 'ar', 'Standard Double Room with Balcony', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel.</p>', '<p>These rooms are located in the wing areas of the hotel and have been charmingly furnished and decorated with attractive colours and offer every comfort with fully fitted tiled or carpeted floors, twin or double beds, balcony, bath / shower / WC. ed rooms are equipped with a third bed (sofa bed).  Standard rooms are equipped with satellite TV &amp; integrated music channel, direct dial telephone, bathrobe &amp; slippers, beach towels, pillow ion, hairdryer, light Mini Bar (at an extra charge), a safe, and manually operated air conditioning which is centrally controlled.</p>'),
(134, 29, 'ar', 'Superior King Room', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>', '<p>The 240 sq ft Superior King is located on the higher floors (11-17) and features king-size, comfy bed with Italian sheets and fluffy down pillows, stunning views through floor-to-ceiling, wall-to-wall windows (that open), a rain shower with natural light and city views, custom bath amenities, cozy robes, free WiFi, seating area with table, a giant plasma TV, an overstocked mini bar, and 24-hour room service.</p>'),
(135, 30, 'ar', 'Superior Double Room', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>', '<p>The comfortable Superior double rooms are equipped with queen size bed and offer a little more space and comfort on 15m². The rooms face the quiet courtyard and offer additional noise absorbing windows. The rooms are also equipped with a bathroom including shower, comfortable seating, desk and flat screen TV. Upon arrival you will find a bottle of mineral water in your room. Internet can be used via WiFi access (free of charge).</p>'),
(136, 31, 'ar', 'Deluxe Two Queen Non-Smoking', '<p>Inviting and innovative, this non-smoking 350-square-foot GO King room features sleek, modern furniture and tech-savvy accessories including electronic window treatments, a 42-inch flat-screen TV and wireless internet (for a fee). The bathrooms come with stylish frosted glass walls and doors, built-in TVs in mirrors and luxurious bath amenities.</p>', '<p>Inviting and innovative, this non-smoking 350-square-foot GO King room features sleek, modern furniture and tech-savvy accessories including electronic window treatments, a 42-inch flat-screen TV and wireless internet (for a fee). The bathrooms come with stylish frosted glass walls and doors, built-in TVs in mirrors and luxurious bath amenities. Bathrooms include walk-in showers, but rooms with tubs are also available by request.</p>'),
(137, 32, 'ar', 'Neapolitan King Suite ', '<p>Neapolitan King Suite</p>', '<p>Neapolitan King Suite</p>'),
(138, 33, 'ar', 'Business Suite', '<p>Business Suite stands for business hedonism. Here, a remarkable bedroom is complemented with spacious up to date equipped office. The office can be transformed into a grandiose living room with eye appealing, leather pull out sofa, which gives to the room a warm but homey atmosphere.</p>', '<p>Business Suite stands for business hedonism. Here, a remarkable bedroom is complemented with spacious up to date equipped office. The office can be transformed into a grandiose living room with eye appealing, leather pull out sofa, which gives to the room a warm but homey atmosphere. The bathroom is an astonishing side dish in this perfect meal, perfectly equipped, soothing and roomy.</p>'),
(139, 34, 'ar', 'Superior Double Room', '<p>We like 30 hour days and deciding when the sun should rise. That’s why all Double Superior rooms in The Ushuaïa Club have blackout curtains. And free WiFi, so you can share instantly. Because time and space are relative and you control them. Who has lived the Ushuaïa experience knows this. Memories can be quite fuzzy.</p>', '<p>We like 30 hour days and deciding when the sun should rise. That’s why all Double Superior rooms in The Ushuaïa Club have blackout curtains. And free WiFi, so you can share instantly. Because time and space are relative and you control them. Who has lived the Ushuaïa experience knows this.</p>\r\n<p>Memories can be quite fuzzy.  Especially the ones from the last party. That’s why our Double Superior rooms have solid amenities: a maxi-bar, aromatherapy menu, sensual shower, designer furniture, bathroom amenities and color therapy system. And with its ample terrace, you can enjoy the party at your own pace. Luxury. Exclusivity. Technology. Vanguard. At the heart of the best daytime party in Ibiza. Pure Ushuaïa spirit.</p>'),
(140, 35, 'ar', 'Single Room', '<p>An elegant room featuring a king size bed or twin beds offers individually controlled air-conditioning, bathroom with shower, hairdryer, cable TV, direct dial telephone, mini-bar and free WiFi Internet access. Single rooms feature modern amenities and a comfortable environment. The size of the rooms varies between 19-21m2.</p>', '<p>An elegant room featuring a king size bed or twin beds offers individually controlled air-conditioning, bathroom with shower, hairdryer, cable TV, direct dial telephone, mini-bar and free WiFi Internet access. Single rooms feature modern amenities and a comfortable environment. The size of the rooms varies between 19-21m2.</p>');
